import React from 'react';
import { BeamModel, AnalysisResult, UnitSystem } from '../types';
import { getFactor, getUnitLabel, formatNum } from '../utils/units';
import { CheckCircle2, AlertOctagon, Info, FileSpreadsheet } from 'lucide-react';

interface ReportViewProps {
  model: BeamModel;
  result: AnalysisResult | null;
  units: UnitSystem;
}

export const ReportView: React.FC<ReportViewProps> = ({
  model,
  result,
  units,
}) => {
  if (!result) {
    return (
      <div className="p-8 text-center text-slate-400">
        Fix model errors or add restraints to generate structural calculation report.
      </div>
    );
  }

  const Fu = getUnitLabel(units, 'F');
  const Lu = getUnitLabel(units, 'L');
  const Mu = getUnitLabel(units, 'M');
  const Su = getUnitLabel(units, 'S');
  const Du = getUnitLabel(units, 'D');

  const F_ = (v: number, d = 2) => formatNum(v * getFactor(units, 'F'), d);
  const L_ = (v: number, d = 2) => formatNum(v * getFactor(units, 'L'), d);
  const M_ = (v: number, d = 2) => formatNum(v * getFactor(units, 'M'), d);
  const S_ = (v: number, d = 1) => formatNum(v * getFactor(units, 'S'), d);
  const D_ = (v: number, d = 2) => formatNum(v * getFactor(units, 'D'), d);

  const isStressOk = result.sigma <= model.fy;
  const isDeflectionOk = Math.abs(result.Ym.y) <= result.allow;

  return (
    <div className="space-y-6 max-w-5xl mx-auto">
      {/* KPI Summary Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3">
        <div className="p-3 rounded-xl border border-slate-800 bg-slate-900/70 font-mono">
          <span className="text-[10px] text-slate-400 block mb-0.5">Max |Shear|</span>
          <span className="text-base font-bold text-blue-400">
            {F_(Math.abs(result.Vm.V))} {Fu}
          </span>
          <span className="text-[10px] text-slate-500 block mt-0.5">
            at x = {L_(result.Vm.x)} {Lu}
          </span>
        </div>

        <div className="p-3 rounded-xl border border-slate-800 bg-slate-900/70 font-mono">
          <span className="text-[10px] text-slate-400 block mb-0.5">Max Sagging M</span>
          <span className="text-base font-bold text-emerald-400">
            +{M_(Math.max(0, result.Mp.M))} {Mu}
          </span>
          <span className="text-[10px] text-slate-500 block mt-0.5">
            at x = {L_(result.Mp.x)} {Lu}
          </span>
        </div>

        <div className="p-3 rounded-xl border border-slate-800 bg-slate-900/70 font-mono">
          <span className="text-[10px] text-slate-400 block mb-0.5">Max Hogging M</span>
          <span className="text-base font-bold text-rose-400">
            {M_(Math.min(0, result.Mn.M))} {Mu}
          </span>
          <span className="text-[10px] text-slate-500 block mt-0.5">
            at x = {L_(result.Mn.x)} {Lu}
          </span>
        </div>

        <div className="p-3 rounded-xl border border-slate-800 bg-slate-900/70 font-mono">
          <span className="text-[10px] text-slate-400 block mb-0.5">Max Deflection</span>
          <span className="text-base font-bold text-purple-400">
            {D_(Math.abs(result.Ym.y))} {Du}
          </span>
          <span
            className={`text-[10px] font-bold block mt-0.5 ${
              isDeflectionOk ? 'text-emerald-400' : 'text-amber-400'
            }`}
          >
            {isDeflectionOk ? 'L/n PASS ✓' : 'EXCEEDED ⚠'}
          </span>
        </div>

        <div className="p-3 rounded-xl border border-slate-800 bg-slate-900/70 font-mono">
          <span className="text-[10px] text-slate-400 block mb-0.5">Bending Stress σ</span>
          <span className="text-base font-bold text-slate-200">
            {S_(result.sigma)} {Su}
          </span>
          <span
            className={`text-[10px] font-bold block mt-0.5 ${
              isStressOk ? 'text-emerald-400' : 'text-rose-400'
            }`}
          >
            {isStressOk ? 'PASS ≤ fy' : 'EXCEEDS fy ✗'}
          </span>
        </div>

        {result.hasN ? (
          <div className="p-3 rounded-xl border border-slate-800 bg-slate-900/70 font-mono">
            <span className="text-[10px] text-slate-400 block mb-0.5">Max |Axial| N</span>
            <span className="text-base font-bold text-cyan-400">
              {F_(Math.abs(result.Nm?.N || 0))} {Fu}
            </span>
            <span className="text-[10px] text-slate-500 block mt-0.5">
              at x = {L_(result.Nm?.x || 0)} {Lu}
            </span>
          </div>
        ) : (
          <div className="p-3 rounded-xl border border-slate-800 bg-slate-900/70 font-mono">
            <span className="text-[10px] text-slate-400 block mb-0.5">Static Elements</span>
            <span className="text-base font-bold text-slate-300">
              {result.nEl} FEM Elem
            </span>
            <span className="text-[10px] text-slate-500 block mt-0.5">Euler–Bernoulli</span>
          </div>
        )}
      </div>

      {/* Support Reactions Table */}
      <div className="p-5 rounded-2xl border border-slate-800 bg-slate-900/80 space-y-3">
        <h3 className="text-sm font-bold text-slate-100 flex items-center gap-2">
          <FileSpreadsheet className="w-4 h-4 text-blue-400" />
          <span>Support Reactions Table</span>
        </h3>

        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs font-mono">
            <thead>
              <tr className="border-b border-slate-800 text-slate-400">
                <th className="py-2 px-3">#</th>
                <th className="py-2 px-3">Support Type</th>
                <th className="py-2 px-3">Coordinate x ({Lu})</th>
                <th className="py-2 px-3">Vertical Force Ry ({Fu} ↑)</th>
                <th className="py-2 px-3">Reaction Moment MR ({Mu} ↺+)</th>
                {result.hasN && <th className="py-2 px-3">Horizontal Thrust H ({Fu} →)</th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/60">
              {result.rx.map((r, idx) => (
                <tr key={idx} className="hover:bg-slate-800/30">
                  <td className="py-2.5 px-3 text-slate-500">{idx + 1}</td>
                  <td className="py-2.5 px-3 font-semibold text-slate-200 capitalize">{r.t}</td>
                  <td className="py-2.5 px-3 text-slate-300">{L_(r.x)}</td>
                  <td className="py-2.5 px-3 text-emerald-400 font-bold">{F_(r.Ry)}</td>
                  <td className="py-2.5 px-3 text-purple-300">
                    {r.t === 'fixed' ? M_(r.M) : '—'}
                  </td>
                  {result.hasN && (
                    <td className="py-2.5 px-3 text-sky-400 font-bold">
                      {F_(r.H || 0)}
                    </td>
                  )}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Detailed Technical Calculation Audit Log */}
      <div className="p-5 rounded-2xl border border-slate-800 bg-slate-900/80 space-y-4">
        <h3 className="text-sm font-bold text-slate-100">
          Formal Structural Engineering Calculation Summary
        </h3>

        <div className="p-4 bg-slate-950 rounded-xl border border-slate-800/90 font-mono text-xs text-slate-300 whitespace-pre-wrap leading-relaxed overflow-x-auto">
{`========================================================================
BEAMLAB PRO STRUCTURAL ANALYSIS ENGINE — VERIFICATION REPORT
========================================================================

1. INPUT PARAMETERS
   • Total Span L            : ${L_(model.L)} ${Lu}
   • Young's Modulus E       : ${formatNum(model.E * getFactor(units, 'E'))} ${getUnitLabel(units, 'E')}
   • Moment of Inertia I     : ${formatNum(model.I * getFactor(units, 'I'))} ${getUnitLabel(units, 'I')}
   • Section Modulus Z       : ${formatNum(model.Z * getFactor(units, 'Z'))} ${getUnitLabel(units, 'Z')}
   • Base Flexural Rigidity  : EI = ${formatNum(model.E * model.I * 1e-5, 2)} kN·m²

2. SOLUTION METHODOLOGY
   • Direct-stiffness Finite Element Method (FEM) using ${result.nEl} cubic Euler–Bernoulli elements.
   • Consistent nodal load vectors for uniform and trapezoidal distributed loads.
   • Exact internal hinge release allowing slope discontinuity while enforcing transverse displacement continuity.
   • Statics integration applied across sections to recover exact continuous piecewise internal shear V(x) and moment M(x).

3. GLOBAL EQUILIBRIUM AUDIT
   • Total applied vertical load   : ${F_(result.Ptot)} ${Fu}
   • Sum of vertical reactions     : ${F_(result.sRy)} ${Fu}
   • Vertical balance residual     : ${formatNum((result.sRy - result.Ptot) * getFactor(units, 'F'), 4)} ${Fu} (PASS)
   • Right end boundary shear      : ${F_(result.endV, 4)} ${Fu} (Boundary residual -> 0)
   • Right end boundary moment     : ${M_(result.endM, 4)} ${Mu} (Boundary residual -> 0)

4. SECTION CAPACITY & ELASTIC STRENGTH CHECK
   • Governing Design Moment M_max : ${M_(result.Mmax)} ${Mu}
   • Max Elastic Bending Stress σ  : M_max / Z = ${S_(result.sigma)} ${Su}
   • Material Yield Strength fy    : ${S_(model.fy)} ${Su}
   • Demand / Capacity (D/C) Ratio : ${(result.sigma / model.fy).toFixed(3)}
   • Strength Status               : ${isStressOk ? 'PASS (Adequate bending capacity)' : 'FAIL (Bending stress exceeds yield)'}

5. SERVICEABILITY DEFLECTION CHECK
   • Maximum Span Deflection δ_max : ${D_(Math.abs(result.Ym.y))} ${Du} at x = ${L_(result.Ym.x)} ${Lu}
   • Allowable Deflection (L/${model.lim})   : ${D_(result.allow)} ${Du}
   • Deflection Ratio (δ / δ_allow): ${(Math.abs(result.Ym.y) / result.allow).toFixed(3)}
   • Serviceability Status         : ${isDeflectionOk ? 'PASS (Within deflection limit)' : 'FAIL (Deflection exceeds limit)'}

Note: Axial force from inclined loads is solved via 1D bar stiffness and displayed separately.`}
        </div>
      </div>
    </div>
  );
};
