export interface MovingEnvelope {
  x: number;
  maxV: number;
  minV: number;
  maxM: number;
  minM: number;
}

export function calculateVehicleEnvelope(
  baseModel: BeamModel,
  vehicle: MovingVehicle,
  nSteps: number = 80
): MovingEnvelope[] {
  const L = baseModel.L;
  const totalVehicleLength = Math.max(...vehicle.axles.map((a: MovingVehicleAxle) => a.offset));
  const startX = -totalVehicleLength;
  const endX = L;
  const stepSize = (endX - startX) / nSteps;

  // Discrete points along beam to monitor
  const numSamplePoints = 100;
  const sampleXs: number[] = [];
  for (let i = 0; i <= numSamplePoints; i++) {
    sampleXs.push((L * i) / numSamplePoints);
  }

  const envelope: MovingEnvelope[] = sampleXs.map((x) => ({
    x,
    maxV: -Infinity,
    minV: Infinity,
    maxM: -Infinity,
    minM: Infinity,
  }));

  for (let s = 0; s <= nSteps; s++) {
    const frontPos = startX + s * stepSize;
    // Generate axle point loads that are currently on the beam
    const activeLoads: BeamModel['lds'] = [];
    vehicle.axles.forEach((axle: MovingVehicleAxle, idx: number) => {
      const axleX = frontPos - axle.offset;
      if (axleX >= 0 && axleX <= L) {
        activeLoads.push({
          id: `axle-${idx}`,
          t: 'point',
          x1: axleX,
          w1: axle.load,
        });
      }
    });

    if (activeLoads.length === 0) continue;

    try {
      const res = solveBeam(
        {
          ...baseModel,
          lds: activeLoads,
        },
        { fast: false, N: 30 }
      );

      sampleXs.forEach((x, idx) => {
        // Find nearest result point
        let best = res.pts[0];
        let minDist = Math.abs(res.pts[0].x - x);
        for (let p = 1; p < res.pts.length; p++) {
          const d = Math.abs(res.pts[p].x - x);
          if (d < minDist) {
            minDist = d;
            best = res.pts[p];
          }
        }

        if (best) {
          envelope[idx].maxV = Math.max(envelope[idx].maxV, best.V);
          envelope[idx].minV = Math.min(envelope[idx].minV, best.V);
          envelope[idx].maxM = Math.max(envelope[idx].maxM, best.M);
          envelope[idx].minM = Math.min(envelope[idx].minM, best.M);
        }
      });
    } catch {
      // ignore transient positions if any
    }
  }

  // Sanitize infinities if any point was untouched
  envelope.forEach((e) => {
    if (e.maxV === -Infinity) e.maxV = 0;
    if (e.minV === Infinity) e.minV = 0;
    if (e.maxM === -Infinity) e.maxM = 0;
    if (e.minM === Infinity) e.minM = 0;
  });

  return envelope;
}
