import React, { useRef, useEffect } from 'react';
import { BeamModel, AnalysisResult, UnitSystem } from '../types';
import { getFactor, getUnitLabel, formatNum } from '../utils/units';

interface FreeBodyCanvasProps {
  model: BeamModel;
  result: AnalysisResult | null;
  units: UnitSystem;
}

export const FreeBodyCanvas: React.FC<FreeBodyCanvasProps> = ({
  model,
  result,
  units,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const PAD_LEFT = 75;
  const PAD_RIGHT = 45;
  const BEAM_Y = 85;

  const L = model.L;

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    const w = rect.width;
    const h = 180;

    canvas.width = Math.round(w * dpr);
    canvas.height = Math.round(h * dpr);
    ctx.scale(dpr, dpr);

    const isDark = true;
    const colBg = '#0b1329';
    const colBeam = '#94a3b8';
    const colReaction = '#22c55e'; // vibrant green for reactions
    const colLoad = '#fbbf24'; // amber for loads
    const colText = '#cbd5e1';

    ctx.fillStyle = colBg;
    ctx.fillRect(0, 0, w, h);

    const getXCoord = (x: number) => {
      const activeWidth = w - PAD_LEFT - PAD_RIGHT;
      return PAD_LEFT + (Math.max(0, Math.min(L, x)) / L) * activeWidth;
    };

    const x0 = getXCoord(0);
    const xL = getXCoord(L);

    // Free Beam Axis
    ctx.beginPath();
    ctx.moveTo(x0, BEAM_Y);
    ctx.lineTo(xL, BEAM_Y);
    ctx.strokeStyle = colBeam;
    ctx.lineWidth = 10;
    ctx.lineCap = 'round';
    ctx.stroke();

    // Internal hinges if any
    model.sup
      .filter((s) => s.t === 'hinge')
      .forEach((hng) => {
        const hx = getXCoord(hng.x);
        ctx.fillStyle = colBg;
        ctx.strokeStyle = '#f472b6';
        ctx.lineWidth = 2.5;
        ctx.beginPath();
        ctx.arc(hx, BEAM_Y, 5, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
      });

    // Draw applied loads above the beam
    model.lds.forEach((l) => {
      const lx = getXCoord(l.x1);
      if (l.t === 'point') {
        const isUp = l.up || false;
        const arrowLen = 35;
        const startY = BEAM_Y + (isUp ? arrowLen : -arrowLen);
        const endY = BEAM_Y;

        ctx.strokeStyle = colLoad;
        ctx.fillStyle = colLoad;
        ctx.lineWidth = 2;

        ctx.beginPath();
        ctx.moveTo(lx, startY);
        ctx.lineTo(lx, endY);
        ctx.stroke();

        ctx.beginPath();
        const headDir = isUp ? -1 : 1;
        ctx.moveTo(lx, endY);
        ctx.lineTo(lx - 4, endY - headDir * 7);
        ctx.lineTo(lx + 4, endY - headDir * 7);
        ctx.closePath();
        ctx.fill();

        ctx.font = '9px "Fira Code", monospace';
        ctx.textAlign = 'center';
        ctx.fillText(
          `${formatNum(l.w1 * getFactor(units, 'F'), 1)}`,
          lx,
          startY + (isUp ? 11 : -5)
        );
      } else if (l.t === 'udl' || l.t === 'tri') {
        const lx2 = getXCoord(l.x2 || l.x1);
        ctx.strokeStyle = colLoad;
        ctx.fillStyle = 'rgba(251, 191, 36, 0.15)';
        ctx.lineWidth = 1.5;

        ctx.strokeRect(lx, BEAM_Y - 20, lx2 - lx, 20);
        ctx.fillRect(lx, BEAM_Y - 20, lx2 - lx, 20);

        ctx.fillStyle = colLoad;
        ctx.font = '9px "Fira Code", monospace';
        ctx.textAlign = 'center';
        ctx.fillText(
          `${formatNum(l.w1 * getFactor(units, 'w'), 1)}`,
          (lx + lx2) / 2,
          BEAM_Y - 24
        );
      }
    });

    // Draw Reaction vectors below or around beam
    if (result && result.rx) {
      result.rx.forEach((r) => {
        const rx = getXCoord(r.x);

        // Vertical reaction Ry
        const isUp = r.Ry >= 0;
        const arrowLen = 42;
        const startY = BEAM_Y + (isUp ? arrowLen : -arrowLen);
        const endY = BEAM_Y;

        ctx.strokeStyle = colReaction;
        ctx.fillStyle = colReaction;
        ctx.lineWidth = 2.5;

        ctx.beginPath();
        ctx.moveTo(rx, startY);
        ctx.lineTo(rx, endY);
        ctx.stroke();

        ctx.beginPath();
        const headDir = isUp ? 1 : -1;
        ctx.moveTo(rx, endY);
        ctx.lineTo(rx - 4, endY + headDir * 7);
        ctx.lineTo(rx + 4, endY + headDir * 7);
        ctx.closePath();
        ctx.fill();

        // Label
        ctx.font = 'bold 10px "Fira Code", monospace';
        ctx.textAlign = 'center';
        const ryText = `Ry=${formatNum(r.Ry * getFactor(units, 'F'), 2)}`;
        ctx.fillText(ryText, rx, startY + (isUp ? 12 : -7));

        // Horizontal reaction H if present
        if (Math.abs(r.H || 0) > 1e-3) {
          const isRight = (r.H || 0) >= 0;
          const hLen = 35;
          const hStartX = rx - (isRight ? hLen : -hLen);
          ctx.beginPath();
          ctx.moveTo(hStartX, BEAM_Y);
          ctx.lineTo(rx, BEAM_Y);
          ctx.stroke();

          ctx.beginPath();
          const headXDir = isRight ? 1 : -1;
          ctx.moveTo(rx, BEAM_Y);
          ctx.lineTo(rx - headXDir * 6, BEAM_Y - 3.5);
          ctx.lineTo(rx - headXDir * 6, BEAM_Y + 3.5);
          ctx.closePath();
          ctx.fill();

          ctx.font = '9px "Fira Code", monospace';
          ctx.fillText(`H=${formatNum(Math.abs(r.H || 0) * getFactor(units, 'F'), 1)}`, rx - 18, BEAM_Y - 8);
        }

        // Moment reaction M if fixed
        if (r.t === 'fixed' && Math.abs(r.M) > 1e-3) {
          const isCCW = r.M >= 0;
          ctx.strokeStyle = '#a855f7';
          ctx.fillStyle = '#a855f7';
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.arc(rx, BEAM_Y, 18, isCCW ? -0.8 * Math.PI : -0.2 * Math.PI, isCCW ? 0.3 * Math.PI : 1.2 * Math.PI);
          ctx.stroke();

          ctx.font = 'bold 9px "Fira Code", monospace';
          ctx.fillText(`MR=${formatNum(Math.abs(r.M) * getFactor(units, 'M'), 2)}`, rx, BEAM_Y + 30);
        }
      });
    }
  }, [model, result, units, L]);

  return (
    <div className="relative w-full rounded-xl border border-slate-800 bg-slate-900/70 shadow-sm overflow-hidden select-none">
      <div className="flex items-center justify-between px-3.5 py-2 border-b border-slate-800/80 bg-slate-950/40">
        <div>
          <h4 className="text-xs font-semibold text-slate-200 tracking-wide">
            Free Body Diagram (FBD)
          </h4>
          <p className="text-[11px] text-slate-500 mt-0.5">
            Boundary restraints replaced by evaluated reaction forces and moments
          </p>
        </div>
        {result && (
          <div className="flex items-center gap-3 text-xs font-mono">
            <span className="text-emerald-400 bg-emerald-950/60 border border-emerald-800/60 px-2 py-0.5 rounded">
              ΣFy = 0 ✓ ({formatNum((result.sRy - result.Ptot) * getFactor(units, 'F'), 3)}{' '}
              {getUnitLabel(units, 'F')})
            </span>
          </div>
        )}
      </div>
      <canvas ref={canvasRef} className="w-full h-[180px] block" />
    </div>
  );
};
