import React, { useState, useEffect } from 'react';
import { BeamModel } from '../types';
import {
  X,
  Save,
  FolderOpen,
  Trash2,
  Download,
  Upload,
  Check,
  Database,
  Calendar,
  Layers,
  ArrowRight,
  Sparkles,
} from 'lucide-react';
import {
  SavedProject,
  getAllProjectsFromDB,
  saveProjectToDB,
  deleteProjectFromDB,
  generateDefaultProjectName,
} from '../utils/indexedDB';

interface ProjectModalProps {
  currentModel: BeamModel;
  onLoadModel: (model: BeamModel) => void;
  onClose: () => void;
}

export const ProjectModal: React.FC<ProjectModalProps> = ({
  currentModel,
  onLoadModel,
  onClose,
}) => {
  const [projects, setProjects] = useState<SavedProject[]>([]);
  const [projectName, setProjectName] = useState<string>('');
  const [savedSuccess, setSavedSuccess] = useState<boolean>(false);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [activeLoadedId, setActiveLoadedId] = useState<string | null>(null);

  // Initialize with automatic default name and load projects from IndexedDB
  useEffect(() => {
    setProjectName(generateDefaultProjectName(currentModel));
    loadProjects();
  }, [currentModel]);

  const loadProjects = async () => {
    setIsLoading(true);
    try {
      const list = await getAllProjectsFromDB();
      setProjects(list);
    } catch (err) {
      console.error('Error reading IndexedDB:', err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSaveCurrent = async () => {
    const finalName = projectName.trim() || generateDefaultProjectName(currentModel);
    const now = Date.now();
    const newProj: SavedProject = {
      id: `proj-${now}-${Math.random().toString(36).substr(2, 4)}`,
      name: finalName,
      createdAt: now,
      updatedAt: now,
      dateStr: new Date(now).toLocaleString([], {
        month: 'short',
        day: 'numeric',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
      }),
      model: JSON.parse(JSON.stringify(currentModel)),
      summary: {
        span: currentModel.L,
        supportCount: currentModel.sup.length,
        loadCount: currentModel.lds.length,
        supportTypes: currentModel.sup.map((s) => s.t),
      },
    };

    try {
      await saveProjectToDB(newProj);
      setSavedSuccess(true);
      setTimeout(() => setSavedSuccess(false), 2500);
      await loadProjects();
      // Generate next default name
      setProjectName(generateDefaultProjectName(currentModel));
    } catch (err) {
      alert('Failed to save to browser IndexedDB.');
    }
  };

  const handleDelete = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    try {
      await deleteProjectFromDB(id);
      setProjects((prev) => prev.filter((p) => p.id !== id));
    } catch (err) {
      alert('Failed to delete project from IndexedDB.');
    }
  };

  const handleLoad = (p: SavedProject) => {
    setActiveLoadedId(p.id);
    onLoadModel(p.model);
    setTimeout(() => {
      onClose();
    }, 300);
  };

  const exportJSON = () => {
    const dataStr =
      'data:text/json;charset=utf-8,' +
      encodeURIComponent(JSON.stringify(currentModel, null, 2));
    const dlAnchorElem = document.createElement('a');
    dlAnchorElem.setAttribute('href', dataStr);
    dlAnchorElem.setAttribute('download', `BeamLab_Project_${Date.now()}.json`);
    dlAnchorElem.click();
  };

  const importJSON = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const parsed = JSON.parse(event.target?.result as string);
        if (parsed.L && Array.isArray(parsed.sup) && Array.isArray(parsed.lds)) {
          onLoadModel(parsed);
          onClose();
        } else {
          alert('Invalid BeamLab model JSON format.');
        }
      } catch {
        alert('Could not parse JSON file.');
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-3 sm:p-5 overflow-y-auto">
      <div className="bg-slate-900 border border-slate-700/80 rounded-2xl w-full max-w-2xl max-h-[90vh] flex flex-col shadow-2xl overflow-hidden">
        {/* Header */}
        <div className="p-4 sm:p-5 border-b border-slate-800 bg-slate-950 flex items-center justify-between">
          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 rounded-xl bg-blue-600/20 text-blue-400 border border-blue-500/30 flex items-center justify-center">
              <Database className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-base sm:text-lg font-bold text-white flex items-center gap-2">
                <span>IndexedDB Project Manager</span>
                <span className="text-[10px] bg-blue-500/20 text-blue-300 font-mono px-2 py-0.5 rounded border border-blue-500/30">
                  Browser Persistent Storage
                </span>
              </h2>
              <p className="text-xs text-slate-400">
                Save and load your structural models directly inside your browser’s IndexedDB database
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-slate-400 hover:text-white hover:bg-slate-800 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="p-5 sm:p-6 overflow-y-auto space-y-6">
          {/* Save Current Project Box */}
          <div className="p-4 rounded-xl bg-slate-950/80 border border-slate-800 space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-xs font-semibold text-slate-300 flex items-center gap-1.5">
                <Save className="w-4 h-4 text-blue-400" />
                <span>Save Active Project</span>
              </span>
              <span className="text-[11px] font-mono text-slate-400">
                Span: {currentModel.L}m · {currentModel.sup.length} Supports · {currentModel.lds.length} Loads
              </span>
            </div>

            <div className="flex flex-col sm:flex-row gap-2">
              <div className="relative flex-1">
                <input
                  type="text"
                  value={projectName}
                  onChange={(e) => setProjectName(e.target.value)}
                  placeholder="Enter project name..."
                  className="w-full bg-slate-900 border border-slate-700 hover:border-slate-600 rounded-xl px-3.5 py-2 text-xs text-slate-100 font-medium focus:border-blue-500 focus:outline-none transition-colors"
                />
              </div>

              <button
                onClick={handleSaveCurrent}
                className="px-4 py-2 rounded-xl bg-blue-600 hover:bg-blue-500 text-white font-semibold text-xs flex items-center justify-center gap-1.5 shadow-md shadow-blue-500/20 transition-all cursor-pointer whitespace-nowrap"
              >
                {savedSuccess ? (
                  <>
                    <Check className="w-4 h-4 text-emerald-300" />
                    <span>Saved to IndexedDB!</span>
                  </>
                ) : (
                  <>
                    <Save className="w-4 h-4" />
                    <span>Save Project</span>
                  </>
                )}
              </button>
            </div>

            <p className="text-[11px] text-slate-500">
              * A default project name is automatically generated based on beam span, supports, and current timestamp. You can edit it anytime.
            </p>
          </div>

          {/* Saved Projects List */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-xs font-bold text-white uppercase tracking-wider flex items-center gap-1.5">
                <FolderOpen className="w-4 h-4 text-amber-400" />
                <span>Saved Projects in IndexedDB ({projects.length})</span>
              </span>

              <div className="flex items-center gap-2">
                <button
                  onClick={exportJSON}
                  className="text-xs text-slate-400 hover:text-slate-200 px-2 py-1 rounded bg-slate-800/80 hover:bg-slate-700 flex items-center gap-1"
                  title="Download current model as JSON"
                >
                  <Download className="w-3.5 h-3.5" />
                  <span>Export JSON</span>
                </button>

                <label className="text-xs text-slate-400 hover:text-slate-200 px-2 py-1 rounded bg-slate-800/80 hover:bg-slate-700 flex items-center gap-1 cursor-pointer">
                  <Upload className="w-3.5 h-3.5" />
                  <span>Import JSON</span>
                  <input
                    type="file"
                    accept=".json"
                    onChange={importJSON}
                    className="hidden"
                  />
                </label>
              </div>
            </div>

            {isLoading ? (
              <div className="py-8 text-center text-xs text-slate-500">
                Loading projects from browser IndexedDB...
              </div>
            ) : projects.length === 0 ? (
              <div className="py-8 px-4 rounded-xl border border-dashed border-slate-800 text-center space-y-1.5">
                <p className="text-xs text-slate-400 font-medium">No saved projects found in IndexedDB yet.</p>
                <p className="text-[11px] text-slate-500">
                  Click the Save Project button above to store your first beam configuration.
                </p>
              </div>
            ) : (
              <div className="space-y-2 max-h-[320px] overflow-y-auto pr-1">
                {projects.map((p) => {
                  const isLoaded = activeLoadedId === p.id;
                  return (
                    <div
                      key={p.id}
                      onClick={() => handleLoad(p)}
                      className={`p-3.5 rounded-xl border transition-all cursor-pointer flex items-center justify-between gap-3 ${
                        isLoaded
                          ? 'border-emerald-500 bg-emerald-950/40'
                          : 'border-slate-800 bg-slate-950/60 hover:border-slate-700 hover:bg-slate-950'
                      }`}
                    >
                      <div className="space-y-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <h4 className="text-xs font-bold text-slate-100 truncate">
                            {p.name}
                          </h4>
                          {isLoaded && (
                            <span className="text-[10px] bg-emerald-500/20 text-emerald-400 px-1.5 py-0.5 rounded font-mono">
                              Loaded!
                            </span>
                          )}
                        </div>

                        <div className="flex flex-wrap items-center gap-3 text-[11px] text-slate-400 font-mono">
                          <span className="text-blue-400">Span: {p.model.L}m</span>
                          <span>•</span>
                          <span>{p.model.sup.length} Supports</span>
                          <span>•</span>
                          <span>{p.model.lds.length} Loads</span>
                          <span>•</span>
                          <span className="text-slate-500">{p.dateStr}</span>
                        </div>
                      </div>

                      <div className="flex items-center gap-2 flex-shrink-0">
                        <button
                          onClick={() => handleLoad(p)}
                          className="px-3 py-1.5 rounded-lg bg-slate-800 hover:bg-blue-600 text-slate-300 hover:text-white text-xs font-semibold flex items-center gap-1 transition-all"
                        >
                          <span>Load</span>
                          <ArrowRight className="w-3.5 h-3.5" />
                        </button>

                        <button
                          onClick={(e) => handleDelete(p.id, e)}
                          className="p-1.5 rounded-lg text-slate-500 hover:text-rose-400 hover:bg-rose-950/30 transition-colors"
                          title="Delete from IndexedDB"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-800 bg-slate-950 flex items-center justify-between text-xs text-slate-500">
          <span>Browser IndexedDB: Database persistent across browser sessions</span>
          <button
            onClick={onClose}
            className="px-3 py-1.5 rounded-lg border border-slate-800 hover:bg-slate-800 text-slate-300 font-medium transition-colors"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
};
