import { BeamModel, AnalysisResult, SupportReaction, DataPoint, InfluencePoint, InfluenceQuantity } from '../types';

export function getInertiaAt(m: BeamModel, x: number): number {
  const seg = (m.Iseg || []).find((g) => x > g.x1 && x < g.x2);
  return seg ? seg.I : m.I;
}

export function validateModel(m: BeamModel): void {
  if (!(m.L > 0)) throw new Error('Beam length must be greater than zero.');
  if (!(m.E > 0)) throw new Error("Young's modulus E must be greater than zero.");
  if (!(m.I > 0)) throw new Error('Second moment of area I must be greater than zero.');
  if (!(m.Z > 0)) throw new Error('Section modulus Z must be greater than zero.');

  const realSupports = m.sup.filter((s) => s.t !== 'hinge');
  if (realSupports.length === 0) {
    throw new Error('No supports: the beam is unstable. Add at least a pinned and roller support, or a fixed support.');
  }

  // Check for duplicate supports at the same position
  const positions: number[] = [];
  for (const s of realSupports) {
    if (positions.some((p) => Math.abs(p - s.x) < 1e-4)) {
      throw new Error(`Two supports at the same position x = ${s.x.toFixed(2)} m.`);
    }
    positions.push(s.x);
  }

  // Check for supports outside beam bounds
  for (const s of m.sup) {
    if (s.x < -1e-4 || s.x > m.L + 1e-4) {
      throw new Error(`Support at x = ${s.x.toFixed(2)} m is outside the beam span [0, ${m.L.toFixed(2)}].`);
    }
  }

  // Check loads
  for (const l of m.lds) {
    if (l.x1 < -1e-4 || l.x1 > m.L + 1e-4) {
      throw new Error(`Load at x = ${l.x1.toFixed(2)} m is outside the beam span.`);
    }
    if ((l.t === 'udl' || l.t === 'tri') && l.x2 !== undefined) {
      if (l.x2 < -1e-4 || l.x2 > m.L + 1e-4) {
        throw new Error(`Distributed load end x = ${l.x2.toFixed(2)} m is outside the beam span.`);
      }
      if (l.x2 <= l.x1) {
        throw new Error(`Distributed load must have end coordinate x2 > x1.`);
      }
    }
  }
}

export function solveBeam(
  model: BeamModel,
  options?: { fast?: boolean; N?: number }
): AnalysisResult {
  validateModel(model);

  const { L, E, I, sup } = model;
  let rawLoads = [...model.lds];

  // Include self-weight if enabled
  if (model.selfWeight && model.area && model.density) {
    // Area in cm^2 -> m^2 = area * 1e-4
    // Density in kg/m^3
    // Mass per m = area * 1e-4 * density (kg/m)
    // Weight per m = mass * 9.80665 / 1000 (kN/m)
    const q_sw = (model.area * 1e-4 * model.density * 9.80665) / 1000;
    rawLoads.push({
      id: 'self-weight',
      t: 'udl',
      x1: 0,
      x2: L,
      w1: q_sw,
      w2: q_sw,
    });
  }

  const lds = rawLoads.map((l) => {
    if (l.t !== 'point') return { ...l, hx: 0 };
    const th = ((l.ang || 0) * Math.PI) / 180;
    return {
      ...l,
      w1: l.w1 * Math.cos(th) * (l.up ? -1 : 1),
      hx: l.w1 * Math.sin(th),
    };
  });

  // Base EI in N·m^2 (E in GPa = 1e9 Pa, I in cm^4 = 1e-8 m^4)
  const EI = E * 1e9 * I * 1e-8;
  const TOL = 1e-6;

  // Key coordinate collection
  const keyCoords: number[] = [0, L];
  (model.Iseg || []).forEach((g) => keyCoords.push(g.x1, g.x2));
  sup.forEach((s) => keyCoords.push(s.x));
  lds.forEach((l) => {
    keyCoords.push(l.x1);
    if ((l.t === 'udl' || l.t === 'tri') && l.x2 !== undefined) {
      keyCoords.push(l.x2);
    }
  });

  // Internal element discretization
  const N = options?.N || Math.max(40, Math.min(140, Math.round(L * 12)));
  for (let i = 0; i <= N; i++) {
    keyCoords.push((L * i) / N);
  }

  // Sorted unique coordinates
  const xs = [...new Set(keyCoords.map((x) => Math.round(x / TOL) * TOL))].sort((a, b) => a - b);
  const nNodes = xs.length;

  const getNearestNodeIndex = (x: number) => {
    let best = 0;
    for (let i = 1; i < nNodes; i++) {
      if (Math.abs(xs[i] - x) < Math.abs(xs[best] - x)) best = i;
    }
    return best;
  };

  // Internal hinge nodes: separate rotational DOF on left and right
  const hingeIndices = new Set(
    sup.filter((s) => s.t === 'hinge').map((s) => getNearestNodeIndex(s.x))
  );

  interface NodeDof {
    v: number;
    l: number; // left rotation DOF
    r: number; // right rotation DOF
  }

  const dofMap: NodeDof[] = [];
  let totalDof = 0;
  for (let i = 0; i < nNodes; i++) {
    if (hingeIndices.has(i)) {
      dofMap.push({ v: totalDof, l: totalDof + 1, r: totalDof + 2 });
      totalDof += 3;
    } else {
      dofMap.push({ v: totalDof, l: totalDof + 1, r: totalDof + 1 });
      totalDof += 2;
    }
  }

  const K = Array.from({ length: totalDof }, () => new Float64Array(totalDof));
  const F = new Float64Array(totalDof);

  // Assemble element stiffness
  for (let e = 0; e < nNodes - 1; e++) {
    const Le = xs[e + 1] - xs[e];
    if (Le <= 0) continue;
    const a = dofMap[e];
    const b = dofMap[e + 1];
    const dofs = [a.v, a.r, b.v, b.l];

    const midX = (xs[e] + xs[e + 1]) / 2;
    const elemI = getInertiaAt(model, midX);
    const c = (EI * elemI) / I / Math.pow(Le, 3);

    const kElem = [
      [12, 6 * Le, -12, 6 * Le],
      [6 * Le, 4 * Le * Le, -6 * Le, 2 * Le * Le],
      [-12, -6 * Le, 12, -6 * Le],
      [6 * Le, 2 * Le * Le, -6 * Le, 4 * Le * Le],
    ];

    for (let i = 0; i < 4; i++) {
      for (let j = 0; j < 4; j++) {
        K[dofs[i]][dofs[j]] += c * kElem[i][j];
      }
    }

    // Equivalent nodal loads for distributed loads
    lds.forEach((l) => {
      if (l.t !== 'udl' && l.t !== 'tri') return;
      if (l.x2 === undefined) return;
      const dx = l.x2 - l.x1;
      if (xs[e] < l.x1 - TOL || xs[e + 1] > l.x2 + TOL || dx <= 0) return;

      const w1 = l.w1;
      const w2 = l.w2 !== undefined ? l.w2 : l.w1;
      const wa = (w1 + ((w2 - w1) * (xs[e] - l.x1)) / dx) * 1e3; // N/m
      const wb = (w1 + ((w2 - w1) * (xs[e + 1] - l.x1)) / dx) * 1e3;

      F[a.v] -= (Le * (7 * wa + 3 * wb)) / 20;
      F[b.v] -= (Le * (3 * wa + 7 * wb)) / 20;
      F[a.r] -= (Le * Le * (3 * wa + 2 * wb)) / 60;
      F[b.l] += (Le * Le * (2 * wa + 3 * wb)) / 60;
    });
  }

  // Point loads & Moments
  lds.forEach((l) => {
    const i = getNearestNodeIndex(l.x1);
    if (l.t === 'point') {
      F[dofMap[i].v] -= l.w1 * 1e3;
    }
    if (l.t === 'moment') {
      F[dofMap[i].r] += (l.cw ? -1 : 1) * l.w1 * 1e3;
    }
  });

  // Boundary conditions
  const fixedDofs = new Set<number>();
  for (const s of sup) {
    if (s.t === 'hinge') continue;
    const i = getNearestNodeIndex(s.x);
    const q = dofMap[i];
    fixedDofs.add(q.v); // Restrains vertical motion
    if (s.t === 'fixed') {
      fixedDofs.add(q.l);
      fixedDofs.add(q.r);
    }
  }

  const freeDofs: number[] = [];
  for (let i = 0; i < totalDof; i++) {
    if (!fixedDofs.has(i)) freeDofs.push(i);
  }

  if (fixedDofs.size === 0) {
    throw new Error('No supports restrain the beam.');
  }

  const nFree = freeDofs.length;
  const A = freeDofs.map((i) => Array.from(freeDofs, (j) => K[i][j]));
  const B = freeDofs.map((i) => F[i]);

  const maxDiag = Math.max(...freeDofs.map((i) => Math.abs(K[i][i])));

  // Gaussian elimination with partial pivoting
  for (let i = 0; i < nFree; i++) {
    let pivot = i;
    for (let k = i + 1; k < nFree; k++) {
      if (Math.abs(A[k][i]) > Math.abs(A[pivot][i])) pivot = k;
    }
    if (Math.abs(A[pivot][i]) < 1e-9 * maxDiag) {
      throw new Error('Unstable structure (mechanism): beam supports or internal hinges cannot maintain static equilibrium.');
    }
    [A[i], A[pivot]] = [A[pivot], A[i]];
    [B[i], B[pivot]] = [B[pivot], B[i]];

    for (let k = i + 1; k < nFree; k++) {
      const factor = A[k][i] / A[i][i];
      if (factor !== 0) {
        for (let j = i; j < nFree; j++) {
          A[k][j] -= factor * A[i][j];
        }
        B[k] -= factor * B[i];
      }
    }
  }

  // Back-substitution
  const uFree = new Float64Array(nFree);
  for (let i = nFree - 1; i >= 0; i--) {
    let s = B[i];
    for (let j = i + 1; j < nFree; j++) s -= A[i][j] * uFree[j];
    uFree[i] = s / A[i][i];
  }

  const U = new Float64Array(totalDof);
  freeDofs.forEach((d, idx) => {
    U[d] = uFree[idx];
  });

  // Calculate nodal reaction forces: R = K*U - F
  const calcReaction = (d: number) => {
    let s = -F[d];
    for (let j = 0; j < totalDof; j++) s += K[d][j] * U[j];
    return s;
  };

  const rx: SupportReaction[] = sup
    .filter((s) => s.t !== 'hinge')
    .map((s) => {
      const q = dofMap[getNearestNodeIndex(s.x)];
      return {
        x: s.x,
        t: s.t,
        Ry: calcReaction(q.v) / 1e3, // in kN
        M: s.t === 'fixed' ? calcReaction(q.r) / 1e3 : 0, // in kN·m
      };
    })
    .sort((a, b) => a.x - b.x);

  if (options?.fast) {
    return {
      pts: [],
      rx,
      Vm: { x: 0, V: 0 },
      Mp: { x: 0, M: 0 },
      Mn: { x: 0, M: 0 },
      Ym: { x: 0, y: 0 },
      hasN: false,
      Ptot: 0,
      sRy: 0,
      endV: 0,
      endM: 0,
      sigma: 0,
      allow: 0,
      nEl: nNodes - 1,
      Mmax: 0,
    };
  }

  // Solve horizontal/axial reactions if inclined loads exist
  const horizontalLoads = lds.filter((l) => l.t === 'point' && Math.abs(l.hx || 0) > 1e-9);
  const horizontalSupports = sup
    .filter((s) => s.t === 'pinned' || s.t === 'fixed')
    .map((s) => getNearestNodeIndex(s.x));

  if (horizontalLoads.length > 0) {
    if (horizontalSupports.length === 0) {
      throw new Error('Inclined loads produce axial thrust: add a pinned or fixed support to resist horizontal force.');
    }
    const KA = Array.from({ length: nNodes }, () => new Float64Array(nNodes));
    const FA = new Float64Array(nNodes);

    for (let e = 0; e < nNodes - 1; e++) {
      const k = 1 / (xs[e + 1] - xs[e]);
      KA[e][e] += k;
      KA[e + 1][e + 1] += k;
      KA[e][e + 1] -= k;
      KA[e + 1][e] -= k;
    }

    horizontalLoads.forEach((l) => {
      FA[getNearestNodeIndex(l.x1)] += (l.hx || 0) * 1e3;
    });

    const freeA: number[] = [];
    for (let i = 0; i < nNodes; i++) {
      if (!horizontalSupports.includes(i)) freeA.push(i);
    }

    const qA = freeA.length;
    const AA = freeA.map((i) => Array.from(freeA, (j) => KA[i][j]));
    const BA = freeA.map((i) => FA[i]);

    for (let i = 0; i < qA; i++) {
      let p = i;
      for (let k = i + 1; k < qA; k++) {
        if (Math.abs(AA[k][i]) > Math.abs(AA[p][i])) p = k;
      }
      [AA[i], AA[p]] = [AA[p], AA[i]];
      [BA[i], BA[p]] = [BA[p], BA[i]];
      for (let k = i + 1; k < qA; k++) {
        const f = AA[k][i] / AA[i][i];
        for (let j = i; j < qA; j++) AA[k][j] -= f * AA[i][j];
        BA[k] -= f * BA[i];
      }
    }

    const uA = new Float64Array(nNodes);
    const yA = new Float64Array(qA);
    for (let i = qA - 1; i >= 0; i--) {
      let t = BA[i];
      for (let j = i + 1; j < qA; j++) t -= AA[i][j] * yA[j];
      yA[i] = t / AA[i][i];
    }
    freeA.forEach((d, i) => (uA[d] = yA[i]));

    rx.forEach((r) => {
      const i = getNearestNodeIndex(r.x);
      if (horizontalSupports.includes(i)) {
        let t = -FA[i];
        for (let j = 0; j < nNodes; j++) t += KA[i][j] * uA[j];
        r.H = t / 1e3;
      } else {
        r.H = 0;
      }
    });
  }

  // Exact statics section cut at coordinate x
  const calcAxialAt = (x: number, isRightOfCut: boolean) => {
    let a = 0;
    const condition = (rxCoord: number) => (isRightOfCut ? rxCoord <= x + TOL : rxCoord < x - TOL);
    rx.forEach((r) => {
      if (condition(r.x)) a += r.H || 0;
    });
    lds.forEach((l) => {
      if (l.t === 'point' && condition(l.x1)) a += l.hx || 0;
    });
    return -a; // tension positive
  };

  const calcDistResultant = (l: (typeof lds)[0], xCut: number): [number, number] => {
    const xEnd = Math.min(xCut, l.x2!);
    const span = xEnd - l.x1;
    if (span <= 0) return [0, 0];
    const w1 = l.w1;
    const w2 = l.w2 !== undefined ? l.w2 : w1;
    const dx = l.x2! - l.x1;
    const wEnd = w1 + ((w2 - w1) * span) / dx;
    const totalW = ((w1 + wEnd) / 2) * span;
    const sumW = w1 + wEnd;
    const centroid =
      l.x1 + (Math.abs(sumW) < 1e-12 ? span / 2 : (span * (w1 + 2 * wEnd)) / (3 * sumW));
    return [totalW, centroid];
  };

  const calcStaticsAt = (x: number, isRightOfCut: boolean) => {
    let V = 0;
    let M = 0;
    const cond = (rxCoord: number) => (isRightOfCut ? rxCoord <= x + TOL : rxCoord < x - TOL);

    rx.forEach((r) => {
      if (cond(r.x)) {
        V += r.Ry;
        M += r.Ry * (x - r.x) - r.M;
      }
    });

    lds.forEach((l) => {
      if (l.t === 'point' && cond(l.x1)) {
        V -= l.w1;
        M -= l.w1 * (x - l.x1);
      } else if (l.t === 'moment' && cond(l.x1)) {
        M += (l.cw ? 1 : -1) * l.w1;
      } else if ((l.t === 'udl' || l.t === 'tri') && x > l.x1 + TOL / 2) {
        const [W, xc] = calcDistResultant(l, x);
        V -= W;
        M -= W * (x - xc);
      }
    });

    return { V, M };
  };

  // Hermite interpolation for continuous deflection
  const calcDeflectionAt = (x: number) => {
    let elem = 0;
    for (let k = 0; k < nNodes - 1; k++) {
      if (x <= xs[k + 1] + TOL / 2) {
        elem = k;
        break;
      }
      elem = k;
    }
    const Le = xs[elem + 1] - xs[elem];
    const t = (x - xs[elem]) / Le;
    const a = dofMap[elem];
    const b = dofMap[elem + 1];

    const N1 = 1 - 3 * t * t + 2 * Math.pow(t, 3);
    const N2 = Le * (t - 2 * t * t + Math.pow(t, 3));
    const N3 = 3 * t * t - 2 * Math.pow(t, 3);
    const N4 = Le * (-t * t + Math.pow(t, 3));
    // Upward positive (+), downward negative (-)
    return (N1 * U[a.v] + N2 * U[a.r] + N3 * U[b.v] + N4 * U[b.l]) * 1e3; // mm
  };

  // Sample points across beam
  const samplePoints: [number, number][] = [];
  const M0 = Math.max(300, N * 3);
  for (let i = 0; i <= M0; i++) {
    samplePoints.push([(L * i) / M0, 0]);
  }
  // Add discontinuous step points at loads, supports, hinges
  keyCoords.forEach((k) => {
    const x = Math.min(L, Math.max(0, k));
    samplePoints.push([x, -1], [x, 1]);
  });
  samplePoints.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  const pts: DataPoint[] = samplePoints.map(([x, s]) => {
    const isRight = s >= 0 && !(x <= 0 && s < 0);
    const cut = calcStaticsAt(x, isRight);
    return {
      x,
      N: calcAxialAt(x, isRight),
      V: cut.V,
      M: cut.M,
      y: calcDeflectionAt(Math.min(L, Math.max(0, x + (s < 0 ? -1 : s > 0 ? 1 : 0) * 1e-9))),
    };
  });

  // Calculate extrema
  const Vm = pts.reduce((prev, curr) => (Math.abs(curr.V) > Math.abs(prev.V) ? curr : prev));
  const Mp = pts.reduce((prev, curr) => (curr.M > prev.M ? curr : prev));
  const Mn = pts.reduce((prev, curr) => (curr.M < prev.M ? curr : prev));
  const Ym = pts.reduce((prev, curr) => (Math.abs(curr.y) > Math.abs(prev.y) ? curr : prev));
  const Nm = pts.reduce((prev, curr) => (Math.abs(curr.N) > Math.abs(prev.N) ? curr : prev));

  const endCut = calcStaticsAt(L, true);
  const Ptot = lds.reduce((acc, l) => {
    if (l.t === 'point') return acc + l.w1;
    if (l.t === 'moment') return acc;
    const w1 = l.w1;
    const w2 = l.w2 !== undefined ? l.w2 : w1;
    return acc + ((w1 + w2) / 2) * (l.x2! - l.x1);
  }, 0);

  const sRy = rx.reduce((acc, r) => acc + r.Ry, 0);
  const Mmax = Math.max(Math.abs(Mp.M), Math.abs(Mn.M));

  // Elastic bending stress: sigma = M_max / Z (MPa)
  // M in kN·m = 1e6 N·mm
  // Z in cm^3 = 1e3 mm^3
  // sigma = (M * 1e6) / (Z * 1e3) = (M * 1000) / Z  in MPa
  const sigma = model.Z > 0 ? (Mmax * 1000) / model.Z : 0;
  const allow = (L * 1000) / model.lim; // mm

  return {
    pts,
    rx,
    Vm: { x: Vm.x, V: Vm.V },
    Mp: { x: Mp.x, M: Mp.M },
    Mn: { x: Mn.x, M: Mn.M },
    Ym: { x: Ym.x, y: Ym.y },
    Nm: { x: Nm.x, N: Nm.N },
    hasN: horizontalLoads.length > 0,
    Ptot,
    sRy,
    endV: endCut.V,
    endM: endCut.M,
    sigma,
    allow,
    nEl: nNodes - 1,
    Mmax,
  };
}

/**
 * Calculate Influence Line ordinates for quantity q at position a (or support idx)
 */
export function calculateInfluenceLine(
  model: BeamModel,
  quantity: InfluenceQuantity,
  sectionX: number,
  supportIdx: number
): InfluencePoint[] {
  validateModel(model);
  const L = model.L;
  const TOL = 1e-6;
  const realSups = model.sup.filter((s) => s.t !== 'hinge');

  if (realSups.length === 0) throw new Error('Add supports first.');
  if (quantity === 'MR' && realSups[supportIdx]?.t !== 'fixed') {
    throw new Error('Moment reaction influence line requires selecting a fixed support.');
  }

  const sampleCoords = new Set<number>([0, L, sectionX, ...model.sup.map((s) => s.x)]);
  for (let i = 0; i <= 160; i++) {
    sampleCoords.add(+((L * i) / 160).toFixed(6));
  }

  const sortedCoords = [...sampleCoords].sort((a, b) => a - b);
  const results: InfluencePoint[] = [];

  for (const xi of sortedCoords) {
    // Solve with unit moving downward load = 1 kN at xi
    const res = solveBeam(
      {
        ...model,
        lds: [{ id: 'unit-load', t: 'point', x1: xi, w1: 1 }],
      },
      { fast: true, N: 40 }
    );

    const evalQuantity = (isLeft: boolean): number => {
      if (quantity === 'R') {
        return res.rx[supportIdx]?.Ry || 0;
      }
      if (quantity === 'MR') {
        return res.rx[supportIdx]?.M || 0;
      }
      if (quantity === 'M') {
        let m = 0;
        res.rx.forEach((s) => {
          if (s.x <= sectionX + TOL) {
            m += s.Ry * (sectionX - s.x) - s.M;
          }
        });
        return isLeft ? m - (sectionX - xi) : m;
      }
      // Shear
      let v = 0;
      res.rx.forEach((s) => {
        if (quantity === 'VR' ? s.x <= sectionX + TOL : s.x < sectionX - TOL) {
          v += s.Ry;
        }
      });
      return isLeft ? v - 1 : v;
    };

    if (Math.abs(xi - sectionX) < TOL && quantity !== 'R' && quantity !== 'MR') {
      results.push({ x: xi, v: evalQuantity(true) });
      results.push({ x: xi, v: evalQuantity(false) });
    } else {
      results.push({ x: xi, v: evalQuantity(xi < sectionX) });
    }
  }

  return results;
}

/**
 * Interpolate influence line value at position x
 */
export function interpolateEta(pts: InfluencePoint[], x: number): number {
  if (!pts || pts.length === 0) return 0;
  let i = 1;
  while (i < pts.length - 1 && pts[i].x < x - 1e-9) i++;
  const p = pts[i - 1];
  const q = pts[i];
  if (!p || !q) return 0;
  return q.x === p.x ? q.v : p.v + ((q.v - p.v) * (x - p.x)) / (q.x - p.x);
}
