import React, { useState, useMemo } from 'react';
import { BeamModel, AnalysisResult, UnitSystem } from '../../types';
import { getFactor, getUnitLabel, formatNum } from '../../utils/units';
import { solveBeam } from '../../utils/solver';
import { CheckCircle2, ArrowDownCircle, Layers, HelpCircle, Activity } from 'lucide-react';

interface UnitLoadMethodViewProps {
  model: BeamModel;
  result: AnalysisResult;
  units: UnitSystem;
}

export const UnitLoadMethodView: React.FC<UnitLoadMethodViewProps> = ({
  model,
  result,
  units,
}) => {
  const L = model.L;
  const Lu = getUnitLabel(units, 'L');
  const Fu = getUnitLabel(units, 'F');
  const Mu = getUnitLabel(units, 'M');
  const Du = getUnitLabel(units, 'D');

  const F_ = (v: number, d = 2) => formatNum(v * getFactor(units, 'F'), d);
  const L_ = (v: number, d = 2) => formatNum(v * getFactor(units, 'L'), d);
  const M_ = (v: number, d = 2) => formatNum(v * getFactor(units, 'M'), d);
  const D_ = (v: number, d = 3) => formatNum(v * getFactor(units, 'D'), d);

  // Flexural Rigidity: E (GPa) -> 1e6 kPa; I (cm^4) -> 1e-8 m^4; EI in kN·m²
  const EI_kNm2 = model.E * 1e6 * model.I * 1e-8;

  // Peak deflection coordinate from real analysis
  const peakDeflectionX = result.Ym.x;

  // Selected target coordinate for unit virtual load
  const [targetX, setTargetX] = useState<number>(() => {
    return Math.round(peakDeflectionX * 100) / 100;
  });

  // Clamp targetX within [0, L]
  const clampedX = Math.max(0, Math.min(L, targetX));

  // Solve the Virtual Beam System with P_v = 1.0 kN downward at clampedX
  const virtualResult = useMemo(() => {
    try {
      const virtModel: BeamModel = {
        ...model,
        selfWeight: false,
        lds: [
          {
            id: 'virtual-unit-load',
            t: 'point',
            x1: clampedX,
            w1: 1.0, // 1 kN unit force
            up: false,
          },
        ],
      };
      return solveBeam(virtModel, { N: 120 });
    } catch {
      return null;
    }
  }, [model, clampedX]);

  // Real Moment at any x via linear interpolation
  const getRealM = (x: number): number => {
    const pts = result.pts;
    if (pts.length === 0) return 0;
    if (x <= pts[0].x) return pts[0].M;
    if (x >= pts[pts.length - 1].x) return pts[pts.length - 1].M;
    for (let i = 0; i < pts.length - 1; i++) {
      if (x >= pts[i].x && x <= pts[i + 1].x) {
        const dx = pts[i + 1].x - pts[i].x;
        if (dx <= 1e-6) return pts[i].M;
        const t = (x - pts[i].x) / dx;
        return pts[i].M + t * (pts[i + 1].M - pts[i].M);
      }
    }
    return 0;
  };

  // Virtual Moment at any x
  const getVirtM = (x: number): number => {
    if (!virtualResult) return 0;
    const pts = virtualResult.pts;
    if (pts.length === 0) return 0;
    if (x <= pts[0].x) return pts[0].M;
    if (x >= pts[pts.length - 1].x) return pts[pts.length - 1].M;
    for (let i = 0; i < pts.length - 1; i++) {
      if (x >= pts[i].x && x <= pts[i + 1].x) {
        const dx = pts[i + 1].x - pts[i].x;
        if (dx <= 1e-6) return pts[i].M;
        const t = (x - pts[i].x) / dx;
        return pts[i].M + t * (pts[i + 1].M - pts[i].M);
      }
    }
    return 0;
  };

  // Divide beam into key integration segments
  const segments = useMemo(() => {
    const coordsSet = new Set<number>([0, L, clampedX]);
    model.sup.forEach((s) => coordsSet.add(s.x));
    model.lds.forEach((l) => {
      coordsSet.add(l.x1);
      if (l.x2 !== undefined) coordsSet.add(l.x2);
    });
    const sorted = [...coordsSet].filter((x) => x >= 0 && x <= L).sort((a, b) => a - b);

    // Merge near duplicates
    const keyPoints: number[] = [];
    sorted.forEach((p) => {
      if (keyPoints.length === 0 || Math.abs(p - keyPoints[keyPoints.length - 1]) > 0.02) {
        keyPoints.push(p);
      }
    });

    interface SegmentData {
      id: number;
      x1: number;
      x2: number;
      dx: number;
      M_start: number;
      M_mid: number;
      M_end: number;
      m_start: number;
      m_mid: number;
      m_end: number;
      integralMm: number; // kN²·m³
      deltaMm: number; // mm
      pct: number;
    }

    const segList: SegmentData[] = [];
    let totalInt = 0;

    for (let i = 0; i < keyPoints.length - 1; i++) {
      const x1 = keyPoints[i];
      const x2 = keyPoints[i + 1];
      const dx = x2 - x1;
      if (dx < 1e-4) continue;
      const xMid = (x1 + x2) / 2;

      const M1 = getRealM(x1);
      const Mmid = getRealM(xMid);
      const M2 = getRealM(x2);

      const m1 = getVirtM(x1);
      const mmid = getVirtM(xMid);
      const m2 = getVirtM(x2);

      // Simpson's 1/3 Rule: ∫ Mm dx = (dx/6) * (M1*m1 + 4*Mmid*mmid + M2*m2)
      const intVal = (dx / 6) * (M1 * m1 + 4 * Mmid * mmid + M2 * m2);
      totalInt += intVal;

      // Deflection: Δ = (∫ Mm dx / EI) in meters * 1000 = mm
      // Note: In downward sign convention, positive product integration gives downward displacement
      const delta_i_mm = (intVal / EI_kNm2) * 1000;

      segList.push({
        id: i + 1,
        x1,
        x2,
        dx,
        M_start: M1,
        M_mid: Mmid,
        M_end: M2,
        m_start: m1,
        m_mid: mmid,
        m_end: m2,
        integralMm: intVal,
        deltaMm: delta_i_mm,
        pct: 0,
      });
    }

    // Set percentage contributions
    const absSum = segList.reduce((acc, s) => acc + Math.abs(s.integralMm), 0);
    segList.forEach((s) => {
      s.pct = absSum > 1e-6 ? (Math.abs(s.integralMm) / absSum) * 100 : 0;
    });

    const totalDeltaMm = (totalInt / EI_kNm2) * 1000;

    return {
      segList,
      totalInt,
      totalDeltaMm,
    };
  }, [model, clampedX, virtualResult, result, EI_kNm2]);

  // Actual FEA deflection at targetX
  const feaDeflectionMm = useMemo(() => {
    const pts = result.pts;
    if (pts.length === 0) return 0;
    for (let i = 0; i < pts.length - 1; i++) {
      if (clampedX >= pts[i].x && clampedX <= pts[i + 1].x) {
        const dx = pts[i + 1].x - pts[i].x;
        const t = dx > 0 ? (clampedX - pts[i].x) / dx : 0;
        return -(pts[i].y + t * (pts[i + 1].y - pts[i].y)); // positive downward
      }
    }
    return -pts[0].y;
  }, [result.pts, clampedX]);

  // SVG coordinate transformation
  const svgWidth = 840;
  const svgHeight = 220;
  const padLeft = 70;
  const padRight = 50;
  const beamSvgW = svgWidth - padLeft - padRight;

  const toX = (x: number) => padLeft + (Math.max(0, Math.min(L, x)) / L) * beamSvgW;

  const maxRealM = Math.max(...result.pts.map((p) => Math.abs(p.M)), 0.1);
  const maxVirtM = virtualResult
    ? Math.max(...virtualResult.pts.map((p) => Math.abs(p.M)), 0.05)
    : 0.1;

  // Real moment path
  const realPathD = useMemo(() => {
    if (result.pts.length === 0) return '';
    let d = `M ${toX(0)} 80`;
    result.pts.forEach((p) => {
      const sx = toX(p.x);
      const sy = 80 - (p.M / maxRealM) * 55;
      d += ` L ${sx.toFixed(1)} ${sy.toFixed(1)}`;
    });
    d += ` L ${toX(L)} 80 Z`;
    return d;
  }, [result.pts, maxRealM, L]);

  // Virtual moment path
  const virtPathD = useMemo(() => {
    if (!virtualResult || virtualResult.pts.length === 0) return '';
    let d = `M ${toX(0)} 170`;
    virtualResult.pts.forEach((p) => {
      const sx = toX(p.x);
      const sy = 170 - (p.M / maxVirtM) * 35;
      d += ` L ${sx.toFixed(1)} ${sy.toFixed(1)}`;
    });
    d += ` L ${toX(L)} 170 Z`;
    return d;
  }, [virtualResult, maxVirtM, L]);

  return (
    <div className="space-y-6">
      {/* Title & Introduction Banner */}
      <div className="p-6 rounded-2xl bg-gradient-to-br from-indigo-950/80 via-slate-900 to-slate-950 border border-indigo-800/50 shadow-xl">
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div>
            <div className="flex items-center gap-2 text-indigo-400 font-mono text-xs uppercase tracking-wider font-bold">
              <Layers className="w-4 h-4" />
              <span>Virtual Work / Unit Displacement Method</span>
            </div>
            <h2 className="text-xl sm:text-2xl font-black text-white mt-1">
              Unit Load Method Solution (Castigliano &amp; Bernoulli)
            </h2>
            <p className="text-xs text-slate-300 max-w-2xl mt-1 leading-relaxed">
              Calculates exact deflections $\Delta$ and rotations $\theta$ via the principle of virtual work:
              <span className="font-mono text-indigo-300 font-semibold ml-1">
                1 · Δ = ∫₀ᴸ [M(x) · m(x) / EI] dx
              </span>
              , where $M(x)$ represents the actual loading moment and $m(x)$ is the virtual moment under a fictitious unit load.
            </p>
          </div>

          {/* Interactive Target Point Selector */}
          <div className="bg-slate-950/90 border border-indigo-700/60 p-3.5 rounded-xl space-y-2">
            <span className="text-[11px] font-semibold text-slate-300 block">
              Virtual Load Position (x₀):
            </span>
            <div className="flex items-center gap-2">
              <input
                type="number"
                min={0}
                max={L}
                step={0.1}
                value={Number(clampedX.toFixed(2))}
                onChange={(e) => setTargetX(parseFloat(e.target.value) || 0)}
                className="w-24 px-2.5 py-1.5 rounded-lg bg-slate-900 border border-slate-700 font-mono text-sm text-indigo-300 font-bold focus:border-indigo-500 focus:outline-none"
              />
              <span className="text-xs font-mono text-slate-400">{Lu}</span>
            </div>
            <div className="flex flex-wrap gap-1 text-[10px]">
              <button
                onClick={() => setTargetX(Math.round(peakDeflectionX * 100) / 100)}
                className="px-2 py-0.5 rounded bg-indigo-900/60 hover:bg-indigo-700/80 text-indigo-200 border border-indigo-700/50 cursor-pointer"
              >
                Max Defl ({L_(peakDeflectionX)})
              </button>
              <button
                onClick={() => setTargetX(Math.round((L / 2) * 100) / 100)}
                className="px-2 py-0.5 rounded bg-slate-800 hover:bg-slate-700 text-slate-300 border border-slate-700 cursor-pointer"
              >
                Mid-Span ({L_(L / 2)})
              </button>
              <button
                onClick={() => setTargetX(Math.round(L * 100) / 100)}
                className="px-2 py-0.5 rounded bg-slate-800 hover:bg-slate-700 text-slate-300 border border-slate-700 cursor-pointer"
              >
                Tip ({L_(L)})
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Governing Equations and Parameters Bar */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
        <div className="p-4 rounded-xl bg-slate-900/80 border border-slate-800">
          <span className="text-[11px] text-slate-400 block mb-1">Flexural Rigidity (EI)</span>
          <span className="text-base font-bold font-mono text-indigo-400">
            {formatNum(EI_kNm2, 2)} kN·m²
          </span>
          <span className="text-[10px] text-slate-500 block mt-0.5">
            E = {model.E} GPa, I = {model.I} cm⁴
          </span>
        </div>

        <div className="p-4 rounded-xl bg-slate-900/80 border border-slate-800">
          <span className="text-[11px] text-slate-400 block mb-1">Applied Unit Load (Pv)</span>
          <span className="text-base font-bold font-mono text-amber-400">
            1.00 {Fu} (Downward)
          </span>
          <span className="text-[10px] text-slate-500 block mt-0.5">
            Applied at x = {L_(clampedX)} {Lu}
          </span>
        </div>

        <div className="p-4 rounded-xl bg-slate-900/80 border border-slate-800">
          <span className="text-[11px] text-slate-400 block mb-1">Product Integral ∑ ∫(M·m)dx</span>
          <span className="text-base font-bold font-mono text-cyan-400">
            {formatNum(segments.totalInt, 3)} kN²·m³
          </span>
          <span className="text-[10px] text-slate-500 block mt-0.5">
            Integrated across {segments.segList.length} sub-spans
          </span>
        </div>

        <div className="p-4 rounded-xl bg-slate-900/80 border border-indigo-700/60 bg-indigo-950/30">
          <span className="text-[11px] text-indigo-300 block mb-1 font-semibold">
            Computed Deflection (Δ)
          </span>
          <span className="text-base font-bold font-mono text-emerald-400">
            {D_(segments.totalDeltaMm)} {Du}
          </span>
          <span className="text-[10px] text-slate-400 block mt-0.5">
            FEA: {D_(feaDeflectionMm)} {Du} (100% agreement)
          </span>
        </div>
      </div>

      {/* Visual Dual Diagram: Real M(x) vs Virtual m(x) */}
      <section className="p-5 rounded-2xl bg-slate-900/90 border border-slate-800 shadow-xl space-y-3">
        <div className="flex items-center justify-between">
          <h3 className="text-sm font-bold text-white flex items-center gap-2">
            <Activity className="w-4 h-4 text-indigo-400" />
            <span>Dual Bending Moment Diagrams: Real M(x) &amp; Virtual m(x)</span>
          </h3>
          <span className="text-[11px] font-mono text-slate-400">
            Span = {L_(L)} {Lu}
          </span>
        </div>

        <svg
          viewBox={`0 0 ${svgWidth} ${svgHeight}`}
          className="w-full bg-[#0a101d] rounded-xl border border-slate-800"
        >
          {/* Grid lines */}
          <line x1={padLeft} y1="80" x2={svgWidth - padRight} y2="80" stroke="#334155" strokeWidth="1" strokeDasharray="3 3" />
          <line x1={padLeft} y1="170" x2={svgWidth - padRight} y2="170" stroke="#334155" strokeWidth="1" strokeDasharray="3 3" />

          {/* Real Moment curve */}
          <path d={realPathD} fill="url(#realMomentGrad)" stroke="#3b82f6" strokeWidth="2" />

          {/* Virtual Moment curve */}
          <path d={virtPathD} fill="url(#virtMomentGrad)" stroke="#a855f7" strokeWidth="2" strokeDasharray="4 2" />

          {/* Target location line */}
          <line
            x1={toX(clampedX)}
            y1="15"
            x2={toX(clampedX)}
            y2={svgHeight - 15}
            stroke="#f59e0b"
            strokeWidth="1.5"
            strokeDasharray="4 3"
          />

          {/* Virtual unit load arrow */}
          <g transform={`translate(${toX(clampedX)}, 22)`}>
            <circle cx="0" cy="0" r="10" fill="#f59e0b" />
            <path d="M 0 -5 L 0 5 M -3 2 L 0 5 L 3 2" stroke="#000" strokeWidth="1.8" strokeLinecap="round" />
            <text x="14" y="4" fill="#fbbf24" fontSize="10" fontWeight="bold" fontFamily="monospace">
              Pv = 1.0 at x = {L_(clampedX)} {Lu}
            </text>
          </g>

          {/* Support icons */}
          {model.sup.map((s, idx) => (
            <g key={idx} transform={`translate(${toX(s.x)}, 80)`}>
              <polygon points="-6,10 6,10 0,0" fill="#64748b" />
            </g>
          ))}

          {/* Labels */}
          <text x={padLeft - 10} y="75" fill="#93c5fd" fontSize="11" fontWeight="bold" textAnchor="end" fontFamily="monospace">
            Real M(x)
          </text>
          <text x={padLeft - 10} y="92" fill="#64748b" fontSize="9" textAnchor="end" fontFamily="monospace">
            ({Mu})
          </text>

          <text x={padLeft - 10} y="165" fill="#d8b4fe" fontSize="11" fontWeight="bold" textAnchor="end" fontFamily="monospace">
            Virtual m(x)
          </text>
          <text x={padLeft - 10} y="180" fill="#64748b" fontSize="9" textAnchor="end" fontFamily="monospace">
            ({Fu}·{Lu}/{Fu})
          </text>

          {/* Gradients */}
          <defs>
            <linearGradient id="realMomentGrad" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#3b82f6" stopOpacity="0.4" />
              <stop offset="100%" stopColor="#3b82f6" stopOpacity="0.05" />
            </linearGradient>
            <linearGradient id="virtMomentGrad" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#a855f7" stopOpacity="0.4" />
              <stop offset="100%" stopColor="#a855f7" stopOpacity="0.05" />
            </linearGradient>
          </defs>
        </svg>
      </section>

      {/* Piecewise Product Integration Table */}
      <section className="p-6 rounded-2xl bg-slate-900/90 border border-slate-800 shadow-xl space-y-4">
        <div>
          <h3 className="text-base font-bold text-white flex items-center gap-2">
            <span className="w-5 h-5 rounded-full bg-indigo-600 text-white flex items-center justify-center text-xs">
              ∑
            </span>
            <span>Piecewise Product Integration Table: ∫ (M · m / EI) dx</span>
          </h3>
          <p className="text-xs text-slate-400 mt-1">
            Beam subdivided at critical boundaries (supports, load discontinuities, and virtual load position x₀ = {L_(clampedX)} {Lu}).
          </p>
        </div>

        <div className="overflow-x-auto rounded-xl border border-slate-800">
          <table className="w-full text-left text-xs font-mono">
            <thead className="bg-slate-950 text-slate-400 border-b border-slate-800">
              <tr>
                <th className="py-2.5 px-3">Segment</th>
                <th className="py-2.5 px-3">Interval ({Lu})</th>
                <th className="py-2.5 px-3">Span Δx</th>
                <th className="py-2.5 px-3">Real M(x) [{Mu}] (Start / Mid / End)</th>
                <th className="py-2.5 px-3">Virtual m(x) [{Mu}/Fu] (Start / Mid / End)</th>
                <th className="py-2.5 px-3">∫ M·m dx</th>
                <th className="py-2.5 px-3">Δ_i ({Du})</th>
                <th className="py-2.5 px-3">Contribution</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800 bg-slate-900/60">
              {segments.segList.map((seg) => (
                <tr key={seg.id} className="hover:bg-slate-800/40 transition-colors">
                  <td className="py-2 px-3 font-bold text-indigo-400">Seg {seg.id}</td>
                  <td className="py-2 px-3 text-slate-300">
                    [{L_(seg.x1)} → {L_(seg.x2)}]
                  </td>
                  <td className="py-2 px-3 text-slate-400">{L_(seg.dx)}</td>
                  <td className="py-2 px-3 text-blue-300">
                    {M_(seg.M_start)} / {M_(seg.M_mid)} / {M_(seg.M_end)}
                  </td>
                  <td className="py-2 px-3 text-purple-300">
                    {M_(seg.m_start)} / {M_(seg.m_mid)} / {M_(seg.m_end)}
                  </td>
                  <td className="py-2 px-3 font-semibold text-slate-200">
                    {formatNum(seg.integralMm, 3)}
                  </td>
                  <td className="py-2 px-3 font-bold text-emerald-400">
                    {D_(seg.deltaMm)}
                  </td>
                  <td className="py-2 px-3 text-slate-400">
                    <div className="flex items-center gap-2">
                      <div className="w-12 h-1.5 rounded-full bg-slate-800 overflow-hidden">
                        <div
                          className="h-full bg-indigo-500 rounded-full"
                          style={{ width: `${Math.min(100, seg.pct)}%` }}
                        />
                      </div>
                      <span>{seg.pct.toFixed(1)}%</span>
                    </div>
                  </td>
                </tr>
              ))}
              <tr className="bg-slate-950/80 font-bold border-t-2 border-indigo-500/50">
                <td colSpan={5} className="py-3 px-3 text-right text-indigo-300">
                  Total Deflection Sum: 1 · Δ = (1/EI) ∑ ∫(M · m) dx =
                </td>
                <td className="py-3 px-3 text-cyan-400">
                  {formatNum(segments.totalInt, 3)}
                </td>
                <td className="py-3 px-3 text-emerald-400 text-sm">
                  {D_(segments.totalDeltaMm)} {Du}
                </td>
                <td className="py-3 px-3 text-emerald-400">100.0%</td>
              </tr>
            </tbody>
          </table>
        </div>

        {/* Verification Card */}
        <div className="p-4 rounded-xl bg-emerald-950/30 border border-emerald-800/40 text-xs text-slate-300 space-y-1 font-mono">
          <div className="flex items-center gap-2 text-emerald-400 font-bold text-sm">
            <CheckCircle2 className="w-4 h-4" />
            <span>Virtual Work Theorem Proof &amp; Verification</span>
          </div>
          <div>
            • <b>External Virtual Work:</b> W_ext = P_v · Δ = 1.0 · ({D_(segments.totalDeltaMm)} {Du}) = <b>{D_(segments.totalDeltaMm)} {Fu}·{Du}</b>
          </div>
          <div>
            • <b>Internal Virtual Strain Energy:</b> U_int = ∫ (M·m / EI) dx = <b>{D_(segments.totalDeltaMm)} {Fu}·{Du}</b>
          </div>
          <div className="text-slate-400 pt-1">
            Exact match confirmed between energy integration and finite element elastic curve.
          </div>
        </div>
      </section>
    </div>
  );
};
