/**
 * 2D Pin-Jointed Truss Solver (Direct Stiffness Method)
 * Formulates the global stiffness matrix, handles nodal restraints, solves nodal displacements,
 * and recovers member axial forces (Tension/Compression/Zero-force) and normal stresses.
 */

import { TrussModel, TrussResult, TrussNodeResult, TrussMemberResult } from '../types';

export function solveTruss(model: TrussModel): TrussResult {
  const { nodes, members, defaultE = 200, defaultA = 25 } = model;

  if (nodes.length < 3) {
    throw new Error('A truss requires at least 3 non-collinear nodes.');
  }
  if (members.length < 3) {
    throw new Error('A truss requires at least 3 members.');
  }

  // Node ID to index mapping
  const nodeIndexMap = new Map<string, number>();
  nodes.forEach((n, idx) => nodeIndexMap.set(n.id, idx));

  // Validate member connectivity
  for (const m of members) {
    if (!nodeIndexMap.has(m.node1Id) || !nodeIndexMap.has(m.node2Id)) {
      throw new Error(`Member "${m.id}" references an invalid node ID.`);
    }
    if (m.node1Id === m.node2Id) {
      throw new Error(`Member "${m.id}" connects a node to itself.`);
    }
  }

  const nNodes = nodes.length;
  const totalDof = 2 * nNodes; // 2 DOFs per node (u_x, u_y)

  // Initialize global stiffness matrix K and load vector F
  const K = Array.from({ length: totalDof }, () => new Float64Array(totalDof));
  const F = new Float64Array(totalDof);

  // Apply nodal point loads (fx, fy in kN -> N)
  nodes.forEach((node, idx) => {
    const dofX = 2 * idx;
    const dofY = 2 * idx + 1;
    if (node.fx) F[dofX] += node.fx * 1e3;
    if (node.fy) F[dofY] += node.fy * 1e3;
  });

  // Element assembly
  const memberGeometry = members.map((m) => {
    const i1 = nodeIndexMap.get(m.node1Id)!;
    const i2 = nodeIndexMap.get(m.node2Id)!;
    const n1 = nodes[i1];
    const n2 = nodes[i2];

    const dx = n2.x - n1.x;
    const dy = n2.y - n1.y;
    const L = Math.hypot(dx, dy);

    if (L <= 1e-6) {
      throw new Error(`Member "${m.id}" has zero length.`);
    }

    const c = dx / L; // cos(theta)
    const s = dy / L; // sin(theta)

    const E_GPa = m.E !== undefined ? m.E : defaultE;
    const A_cm2 = m.A !== undefined ? m.A : defaultA;

    // EA in Newtons: E(GPa) * 1e9 * A(cm^2) * 1e-4 = E * A * 1e5 N
    const EA = E_GPa * A_cm2 * 1e5;
    const k0 = EA / L;

    // 4x4 element stiffness in global DOFs [u1, v1, u2, v2]
    const dofs = [2 * i1, 2 * i1 + 1, 2 * i2, 2 * i2 + 1];

    const ke = [
      [c * c, c * s, -c * c, -c * s],
      [c * s, s * s, -c * s, -s * s],
      [-c * c, -c * s, c * c, c * s],
      [-c * s, -s * s, c * s, s * s],
    ];

    for (let r = 0; r < 4; r++) {
      for (let col = 0; col < 4; col++) {
        K[dofs[r]][dofs[col]] += k0 * ke[r][col];
      }
    }

    return { m, i1, i2, L, c, s, EA, k0, A_cm2 };
  });

  // Boundary conditions
  const fixedDofs = new Set<number>();
  nodes.forEach((n, idx) => {
    if (n.restraintX) fixedDofs.add(2 * idx);
    if (n.restraintY) fixedDofs.add(2 * idx + 1);
  });

  if (fixedDofs.size < 3) {
    throw new Error('A 2D truss requires at least 3 restrained DOFs to prevent rigid body motion.');
  }

  const freeDofs: number[] = [];
  for (let i = 0; i < totalDof; i++) {
    if (!fixedDofs.has(i)) freeDofs.push(i);
  }

  const nFree = freeDofs.length;
  if (nFree === 0) {
    throw new Error('All DOFs are restrained; no displacements to solve.');
  }

  // Extract reduced stiffness matrix A and load vector B
  const A = freeDofs.map((i) => Array.from(freeDofs, (j) => K[i][j]));
  const B = freeDofs.map((i) => F[i]);

  const maxDiag = Math.max(...freeDofs.map((i) => Math.abs(K[i][i])), 1.0);

  // Gaussian elimination with partial pivoting
  for (let i = 0; i < nFree; i++) {
    let pivot = i;
    for (let k = i + 1; k < nFree; k++) {
      if (Math.abs(A[k][i]) > Math.abs(A[pivot][i])) pivot = k;
    }
    if (Math.abs(A[pivot][i]) < 1e-11 * maxDiag) {
      throw new Error(
        'Unstable truss structure (mechanism): the truss lacks sufficient internal triangulation or external support reactions.'
      );
    }
    [A[i], A[pivot]] = [A[pivot], A[i]];
    [B[i], B[pivot]] = [B[pivot], B[i]];

    for (let k = i + 1; k < nFree; k++) {
      const factor = A[k][i] / A[i][i];
      if (factor !== 0) {
        for (let j = i; j < nFree; j++) {
          A[k][j] -= factor * A[i][j];
        }
        B[k] -= factor * B[i];
      }
    }
  }

  // Back-substitution
  const uFree = new Float64Array(nFree);
  for (let i = nFree - 1; i >= 0; i--) {
    let s = B[i];
    for (let j = i + 1; j < nFree; j++) s -= A[i][j] * uFree[j];
    uFree[i] = s / A[i][i];
  }

  // Assemble full displacement vector U (in meters)
  const U = new Float64Array(totalDof);
  freeDofs.forEach((dof, idx) => {
    U[dof] = uFree[idx];
  });

  // Calculate reactions: R = K * U - F (in Newtons)
  const calcReaction = (dof: number) => {
    let s = -F[dof];
    for (let j = 0; j < totalDof; j++) s += K[dof][j] * U[j];
    return s;
  };

  // Nodal results
  const nodeResults: TrussNodeResult[] = nodes.map((n, idx) => {
    const dofX = 2 * idx;
    const dofY = 2 * idx + 1;
    return {
      nodeId: n.id,
      dx: U[dofX] * 1e3, // meters to mm
      dy: U[dofY] * 1e3,
      rx: n.restraintX ? calcReaction(dofX) / 1e3 : 0, // N to kN
      ry: n.restraintY ? calcReaction(dofY) / 1e3 : 0,
    };
  });

  // Member results (axial forces & stresses)
  const memberResults: TrussMemberResult[] = memberGeometry.map((geom) => {
    const { m, i1, i2, L, c, s, k0, A_cm2 } = geom;
    const u1 = U[2 * i1];
    const v1 = U[2 * i1 + 1];
    const u2 = U[2 * i2];
    const v2 = U[2 * i2 + 1];

    // Elongation: delta = -c*u1 - s*v1 + c*u2 + s*v2
    const deltaL = -c * u1 - s * v1 + c * u2 + s * v2;
    const force_N = k0 * deltaL;
    const force_kN = force_N / 1e3;

    // Normal stress: sigma = Force / Area = (force_kN * 1e3) / (A_cm2 * 100 mm^2) = force_kN * 10 / A_cm2 (MPa)
    const stress_MPa = (force_kN * 10) / A_cm2;

    const isZeroForce = Math.abs(force_kN) < 0.02;
    let state: 'Tension' | 'Compression' | 'Zero-force' = 'Zero-force';
    if (!isZeroForce) {
      state = force_kN > 0 ? 'Tension' : 'Compression';
    }

    return {
      memberId: m.id,
      force: force_kN,
      stress: stress_MPa,
      isZeroForce,
      state,
      length: L,
    };
  });

  // Find extrema
  let maxTension = { memberId: '', force: 0 };
  let maxCompression = { memberId: '', force: 0 };
  for (const mr of memberResults) {
    if (mr.force > maxTension.force) {
      maxTension = { memberId: mr.memberId, force: mr.force };
    }
    if (mr.force < maxCompression.force) {
      maxCompression = { memberId: mr.memberId, force: mr.force };
    }
  }

  let maxDisp = { nodeId: '', disp: 0 };
  for (const nr of nodeResults) {
    const totalD = Math.hypot(nr.dx, nr.dy);
    if (totalD > maxDisp.disp) {
      maxDisp = { nodeId: nr.nodeId, disp: totalD };
    }
  }

  const sumFx = nodes.reduce((sum, n) => sum + (n.fx || 0), 0);
  const sumFy = nodes.reduce((sum, n) => sum + (n.fy || 0), 0);
  const sumRx = nodeResults.reduce((sum, n) => sum + n.rx, 0);
  const sumRy = nodeResults.reduce((sum, n) => sum + n.ry, 0);

  return {
    nodes: nodeResults,
    members: memberResults,
    maxTension,
    maxCompression,
    maxDisplacement: maxDisp,
    sumFx,
    sumFy,
    sumRx,
    sumRy,
  };
}

