import { BeamModel } from '../types';

export interface SavedProject {
  id: string;
  name: string;
  createdAt: number;
  updatedAt: number;
  dateStr: string;
  model: BeamModel;
  summary: {
    span: number;
    supportCount: number;
    loadCount: number;
    supportTypes: string[];
  };
}

const DB_NAME = 'BeamLabDB';
const DB_VERSION = 1;
const STORE_NAME = 'projects';

export function openProjectDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') {
      reject(new Error('IndexedDB is not supported in this environment.'));
      return;
    }

    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        store.createIndex('updatedAt', 'updatedAt', { unique: false });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('Failed to open IndexedDB.'));
  });
}

export async function getAllProjectsFromDB(): Promise<SavedProject[]> {
  try {
    const db = await openProjectDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const store = tx.objectStore(STORE_NAME);
      const request = store.getAll();

      request.onsuccess = () => {
        const list = (request.result as SavedProject[]) || [];
        // Sort newest first
        list.sort((a, b) => (b.updatedAt || b.createdAt) - (a.updatedAt || a.createdAt));
        resolve(list);
      };
      request.onerror = () => reject(request.error);
    });
  } catch (err) {
    console.warn('IndexedDB fallback or error:', err);
    // Fallback to localStorage if IndexedDB fails
    try {
      const raw = localStorage.getItem('beamlab_projects_fallback');
      return raw ? JSON.parse(raw) : [];
    } catch {
      return [];
    }
  }
}

export async function saveProjectToDB(project: SavedProject): Promise<void> {
  try {
    const db = await openProjectDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readwrite');
      const store = tx.objectStore(STORE_NAME);
      const request = store.put(project);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  } catch (err) {
    console.warn('Saving to localStorage fallback:', err);
    try {
      const existing = await getAllProjectsFromDB();
      const updated = [project, ...existing.filter((p) => p.id !== project.id)];
      localStorage.setItem('beamlab_projects_fallback', JSON.stringify(updated));
    } catch {
      throw new Error('Storage write failed.');
    }
  }
}

export async function deleteProjectFromDB(id: string): Promise<void> {
  try {
    const db = await openProjectDB();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(STORE_NAME, 'readwrite');
      const store = tx.objectStore(STORE_NAME);
      const request = store.delete(id);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  } catch (err) {
    console.warn('Deleting from localStorage fallback:', err);
    try {
      const existing = await getAllProjectsFromDB();
      const updated = existing.filter((p) => p.id !== id);
      localStorage.setItem('beamlab_projects_fallback', JSON.stringify(updated));
    } catch {
      // ignore
    }
  }
}

export function generateDefaultProjectName(model: BeamModel): string {
  const d = new Date();
  const timeStr = d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  const dateStr = d.toLocaleDateString([], { month: 'short', day: 'numeric' });
  const supTypes = model.sup.map((s) => s.t).join('+') || 'Unconstrained';
  return `Beam ${model.L}m (${supTypes}) - ${dateStr} ${timeStr}`;
}

export const AUTOSAVE_STORAGE_KEY = 'beamlab_autosave_model';
export const AUTOSAVE_META_KEY = 'beamlab_autosave_meta';

export function getAutoSavedModel(): {
  model: BeamModel;
  meta?: {
    presetName?: string;
    units?: string;
    activeView?: string;
    structuralMode?: string;
    timestamp?: number;
  };
} | null {
  try {
    const raw = localStorage.getItem(AUTOSAVE_STORAGE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (
      parsed &&
      typeof parsed.L === 'number' &&
      Array.isArray(parsed.sup) &&
      Array.isArray(parsed.lds)
    ) {
      let meta = undefined;
      const metaRaw = localStorage.getItem(AUTOSAVE_META_KEY);
      if (metaRaw) {
        try {
          meta = JSON.parse(metaRaw);
        } catch {
          // ignore
        }
      }
      return { model: parsed, meta };
    }
    return null;
  } catch (err) {
    console.warn('Failed to load auto-saved model from localStorage:', err);
    return null;
  }
}

export function saveAutoSaveModel(
  model: BeamModel,
  meta?: {
    presetName?: string;
    units?: string;
    activeView?: string;
    structuralMode?: string;
  }
): void {
  try {
    localStorage.setItem(AUTOSAVE_STORAGE_KEY, JSON.stringify(model));
    if (meta) {
      localStorage.setItem(
        AUTOSAVE_META_KEY,
        JSON.stringify({ ...meta, timestamp: Date.now() })
      );
    }
  } catch (err) {
    console.warn('Failed to auto-save to localStorage:', err);
  }
}

export async function saveAutoSaveToDB(
  model: BeamModel,
  meta?: {
    presetName?: string;
    units?: string;
    activeView?: string;
    structuralMode?: string;
  }
): Promise<void> {
  // 1. Instant sync write to localStorage for zero-lag refresh safety
  saveAutoSaveModel(model, meta);

  // 2. Persistent async write to IndexedDB
  try {
    const autoProject: SavedProject = {
      id: 'autosave-current-beam',
      name: `Auto-Save: ${meta?.presetName || 'Current Beam'}`,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      dateStr: new Date().toLocaleDateString([], { month: 'short', day: 'numeric' }),
      model,
      summary: {
        span: model.L,
        supportCount: model.sup.length,
        loadCount: model.lds.length,
        supportTypes: model.sup.map((s) => s.t),
      },
    };
    await saveProjectToDB(autoProject);
  } catch (e) {
    // localStorage already guaranteed
  }
}

export async function clearAutoSave(): Promise<void> {
  try {
    localStorage.removeItem(AUTOSAVE_STORAGE_KEY);
    localStorage.removeItem(AUTOSAVE_META_KEY);
  } catch (err) {
    console.warn('Failed to clear auto-save from localStorage:', err);
  }
  try {
    await deleteProjectFromDB('autosave-current-beam');
  } catch {
    // ignore
  }
}
