import { UnitSystem } from '../types';

export interface SystemDef {
  F: [string, number]; // Force: [label, factor from kN]
  L: [string, number]; // Length: [label, factor from m]
  D: [string, number]; // Deflection: [label, factor from mm]
  S: [string, number]; // Stress: [label, factor from MPa]
  E: [string, number]; // Modulus: [label, factor from GPa]
  I: [string, number]; // Inertia: [label, factor from cm^4]
  Z: [string, number]; // Modulus: [label, factor from cm^3]
}

export const SYSTEMS: Record<UnitSystem, SystemDef> = {
  si: {
    F: ['kN', 1],
    L: ['m', 1],
    D: ['mm', 1],
    S: ['MPa', 1],
    E: ['GPa', 1],
    I: ['cm⁴', 1],
    Z: ['cm³', 1],
  },
  sn: {
    F: ['N', 1000],
    L: ['m', 1],
    D: ['mm', 1],
    S: ['MPa', 1],
    E: ['GPa', 1],
    I: ['cm⁴', 1],
    Z: ['cm³', 1],
  },
  us: {
    F: ['kip', 0.22480894],
    L: ['ft', 3.2808399],
    D: ['in', 0.039370078],
    S: ['ksi', 0.1450377],
    E: ['ksi', 145.0377],
    I: ['in⁴', 0.024025096],
    Z: ['in³', 0.061023744],
  },
};

export function getFactor(sys: UnitSystem, key: 'F' | 'L' | 'D' | 'S' | 'E' | 'I' | 'Z' | 'w' | 'M'): number {
  if (key === 'w') {
    return getFactor(sys, 'F') / getFactor(sys, 'L');
  }
  if (key === 'M') {
    return getFactor(sys, 'F') * getFactor(sys, 'L');
  }
  return SYSTEMS[sys][key][1];
}

export function getUnitLabel(sys: UnitSystem, key: 'F' | 'L' | 'D' | 'S' | 'E' | 'I' | 'Z' | 'w' | 'M'): string {
  if (key === 'w') {
    return `${SYSTEMS[sys].F[0]}/${SYSTEMS[sys].L[0]}`;
  }
  if (key === 'M') {
    return `${SYSTEMS[sys].F[0]}·${SYSTEMS[sys].L[0]}`;
  }
  return SYSTEMS[sys][key][0];
}

export function toDisplay(val: number, sys: UnitSystem, key: 'F' | 'L' | 'D' | 'S' | 'E' | 'I' | 'Z' | 'w' | 'M'): number {
  return +(val * getFactor(sys, key)).toPrecision(8);
}

export function fromDisplay(val: number, sys: UnitSystem, key: 'F' | 'L' | 'D' | 'S' | 'E' | 'I' | 'Z' | 'w' | 'M'): number {
  const f = getFactor(sys, key);
  return f === 0 ? 0 : val / f;
}

export function formatNum(val: number, decimals: number = 2): string {
  if (Math.abs(val) < 1e-12) return '0';
  if (Math.abs(val) >= 1e6 || (Math.abs(val) < 1e-3 && Math.abs(val) > 0)) {
    return val.toExponential(decimals);
  }
  return val.toLocaleString(undefined, {
    minimumFractionDigits: 0,
    maximumFractionDigits: decimals,
  });
}
