import React, { useRef, useEffect, useCallback } from 'react';
import { UnitSystem } from '../types';
import { getFactor, getUnitLabel, formatNum } from '../utils/units';

export interface DiagramPoint {
  x: number;
  val: number;
}

interface DiagramCanvasProps {
  title: string;
  subtitle?: string;
  data: DiagramPoint[];
  beamLength: number;
  units: UnitSystem;
  unitKey: 'F' | 'L' | 'D' | 'S' | 'E' | 'I' | 'Z' | 'w' | 'M';
  colorPositive?: string;
  colorNegative?: string;
  hoverX: number | null;
  onHoverX: (x: number | null) => void;
  height?: number;
  invertSign?: boolean; // e.g. for deflection downward positive
  extremaLabel?: { maxPos?: number; maxNeg?: number; labelPos?: string; labelNeg?: string };
}

export const DiagramCanvas: React.FC<DiagramCanvasProps> = ({
  title,
  subtitle,
  data,
  beamLength,
  units,
  unitKey,
  colorPositive = '#2563eb', // blue
  colorNegative = '#ec4899', // rose/pink
  hoverX,
  onHoverX,
  height = 170,
  invertSign = false,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const PAD_LEFT = 75;
  const PAD_RIGHT = 45;
  const PAD_TOP = 32;
  const PAD_BOTTOM = 26;

  const L = beamLength;

  const getXCoord = useCallback(
    (x: number, width: number) => {
      const activeWidth = width - PAD_LEFT - PAD_RIGHT;
      return PAD_LEFT + (Math.max(0, Math.min(L, x)) / L) * activeWidth;
    },
    [L]
  );

  const getBeamXFromPointer = useCallback(
    (px: number, width: number) => {
      const activeWidth = width - PAD_LEFT - PAD_RIGHT;
      if (activeWidth <= 0) return 0;
      const x = ((px - PAD_LEFT) / activeWidth) * L;
      const snapped = Math.round(x * 50) / 50;
      return Math.max(0, Math.min(L, snapped));
    },
    [L]
  );

  // Render diagram
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    const w = rect.width;
    const h = height;

    canvas.width = Math.round(w * dpr);
    canvas.height = Math.round(h * dpr);
    ctx.scale(dpr, dpr);

    const isDark = true;
    const colBg = '#0b1329';
    const colAxis = isDark ? '#475569' : '#94a3b8';
    const colGrid = 'rgba(51, 65, 85, 0.2)';
    const colText = '#94a3b8';

    // Clear background
    ctx.fillStyle = colBg;
    ctx.fillRect(0, 0, w, h);

    // Subtle grid
    ctx.strokeStyle = colGrid;
    ctx.lineWidth = 1;
    for (let x = 0; x < w; x += 30) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, h);
      ctx.stroke();
    }

    if (!data || data.length === 0) {
      ctx.fillStyle = colText;
      ctx.font = '12px "Inter", sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('No data available', w / 2, h / 2);
      return;
    }

    // Determine scale
    let maxVal = 0;
    let minVal = 0;
    data.forEach((p) => {
      const v = invertSign ? -p.val : p.val;
      if (v > maxVal) maxVal = v;
      if (v < minVal) minVal = v;
    });

    // Provide a small margin
    const peakAbs = Math.max(Math.abs(maxVal), Math.abs(minVal), 0.001);
    const plotMax = Math.max(peakAbs * 1.15, 0.001);

    const chartHeight = h - PAD_TOP - PAD_BOTTOM;
    const zeroY = PAD_TOP + chartHeight / 2; // symmetric or scaled zero baseline

    const getYCoord = (val: number) => {
      const v = invertSign ? -val : val;
      return zeroY - (v / plotMax) * (chartHeight / 2);
    };

    // 1. Draw Zero Datum Axis Line
    const x0 = getXCoord(0, w);
    const xL = getXCoord(L, w);

    ctx.beginPath();
    ctx.moveTo(x0, zeroY);
    ctx.lineTo(xL, zeroY);
    ctx.strokeStyle = colAxis;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // 2. Draw Shaded Polygons & Curve
    // Separate positive and negative areas or draw segmented polygons
    ctx.beginPath();
    ctx.moveTo(x0, zeroY);

    data.forEach((p) => {
      const px = getXCoord(p.x, w);
      const py = getYCoord(p.val);
      ctx.lineTo(px, py);
    });

    ctx.lineTo(xL, zeroY);
    ctx.closePath();

    // Gradient fill
    const grad = ctx.createLinearGradient(0, PAD_TOP, 0, h - PAD_BOTTOM);
    grad.addColorStop(0, 'rgba(56, 189, 248, 0.28)');
    grad.addColorStop(0.5, 'rgba(56, 189, 248, 0.04)');
    grad.addColorStop(1, 'rgba(236, 72, 153, 0.28)');
    ctx.fillStyle = grad;
    ctx.fill();

    // Stroke outline
    ctx.beginPath();
    data.forEach((p, idx) => {
      const px = getXCoord(p.x, w);
      const py = getYCoord(p.val);
      if (idx === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    });
    ctx.strokeStyle = colorPositive;
    ctx.lineWidth = 2.2;
    ctx.stroke();

    // 3. Mark Peak Max & Min Points with badges
    let peakPos = data[0];
    let peakNeg = data[0];
    data.forEach((p) => {
      if (p.val > peakPos.val) peakPos = p;
      if (p.val < peakNeg.val) peakNeg = p;
    });

    const drawPeakMarker = (pt: DiagramPoint, isMax: boolean) => {
      if (Math.abs(pt.val) < 1e-4) return;
      const px = getXCoord(pt.x, w);
      const py = getYCoord(pt.val);

      ctx.fillStyle = isMax ? colorPositive : colorNegative;
      ctx.beginPath();
      ctx.arc(px, py, 4, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 1.5;
      ctx.stroke();

      // Text label
      const valStr = formatNum(pt.val * getFactor(units, unitKey), 2);
      const label = `${valStr} ${getUnitLabel(units, unitKey)}`;
      ctx.font = 'bold 10px "Fira Code", monospace';
      ctx.fillStyle = isMax ? '#93c5fd' : '#f9a8d4';
      ctx.textAlign = 'center';
      const textY = isMax ? py - 8 : py + 14;
      ctx.fillText(label, px, Math.max(12, Math.min(h - 4, textY)));
    };

    drawPeakMarker(peakPos, true);
    if (Math.abs(peakNeg.val) > 1e-4 && Math.abs(peakNeg.val - peakPos.val) > 1e-3) {
      drawPeakMarker(peakNeg, false);
    }

    // 4. Zero Crossings (inflection or shear reversals)
    for (let i = 0; i < data.length - 1; i++) {
      const p1 = data[i];
      const p2 = data[i + 1];
      if ((p1.val > 0 && p2.val < 0) || (p1.val < 0 && p2.val > 0)) {
        const frac = Math.abs(p1.val) / (Math.abs(p1.val) + Math.abs(p2.val));
        const zx = p1.x + frac * (p2.x - p1.x);
        const px = getXCoord(zx, w);

        ctx.fillStyle = '#f59e0b';
        ctx.beginPath();
        ctx.arc(px, zeroY, 3, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = '#fde68a';
        ctx.font = '9px "Fira Code", monospace';
        ctx.textAlign = 'center';
        ctx.fillText(`x=${formatNum(zx * getFactor(units, 'L'), 2)}`, px, zeroY + 12);
      }
    }

    // 5. Crosshair line and Ordinate Inspector
    if (hoverX !== null && hoverX >= 0 && hoverX <= L) {
      const hx = getXCoord(hoverX, w);

      // Interpolate value at hoverX
      let valAtHover = 0;
      let idx = 1;
      while (idx < data.length - 1 && data[idx].x < hoverX - 1e-9) idx++;
      const pA = data[idx - 1] || data[0];
      const pB = data[idx] || data[data.length - 1];

      if (pA && pB) {
        if (Math.abs(pB.x - pA.x) < 1e-9) {
          valAtHover = pB.val;
        } else {
          valAtHover = pA.val + ((pB.val - pA.val) * (hoverX - pA.x)) / (pB.x - pA.x);
        }
      }

      const hy = getYCoord(valAtHover);

      // Vertical guide line
      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 1.2;
      ctx.setLineDash([4, 4]);
      ctx.beginPath();
      ctx.moveTo(hx, 0);
      ctx.lineTo(hx, h);
      ctx.stroke();
      ctx.setLineDash([]);

      // Highlight dot on curve
      ctx.fillStyle = '#38bdf8';
      ctx.beginPath();
      ctx.arc(hx, hy, 5, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 2;
      ctx.stroke();

      // Tooltip pill at top right
      const dispVal = formatNum(valAtHover * getFactor(units, unitKey), 2);
      const dispUnit = getUnitLabel(units, unitKey);
      const tipText = `${dispVal} ${dispUnit}`;

      ctx.fillStyle = 'rgba(15, 23, 42, 0.92)';
      ctx.strokeStyle = '#38bdf8';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.roundRect(w - PAD_RIGHT - 110, 8, 105, 22, 6);
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = '#38bdf8';
      ctx.font = 'bold 11px "Fira Code", monospace';
      ctx.textAlign = 'center';
      ctx.fillText(tipText, w - PAD_RIGHT - 57, 23);
    }
  }, [
    data,
    beamLength,
    units,
    unitKey,
    colorPositive,
    colorNegative,
    hoverX,
    height,
    invertSign,
    getXCoord,
    L,
  ]);

  const handlePointerMove = (e: React.PointerEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const px = e.clientX - rect.left;
    const width = rect.width;
    const beamX = getBeamXFromPointer(px, width);
    onHoverX(beamX);
  };

  const handlePointerLeave = () => {
    onHoverX(null);
  };

  return (
    <div className="relative w-full rounded-xl border border-slate-800 bg-slate-900/70 shadow-sm overflow-hidden select-none">
      <div className="flex items-center justify-between px-3.5 py-2 border-b border-slate-800/80 bg-slate-950/40">
        <div>
          <h4 className="text-xs font-semibold text-slate-200 tracking-wide">{title}</h4>
          {subtitle && <p className="text-[11px] text-slate-500 mt-0.5">{subtitle}</p>}
        </div>
        <div className="text-[11px] font-mono text-slate-400 bg-slate-800/80 px-2 py-0.5 rounded border border-slate-700/60">
          {getUnitLabel(units, unitKey)}
        </div>
      </div>
      <canvas
        ref={canvasRef}
        onPointerMove={handlePointerMove}
        onPointerLeave={handlePointerLeave}
        className="w-full block cursor-crosshair touch-none"
        style={{ height: `${height}px` }}
      />
    </div>
  );
};
