import React, { useMemo } from 'react';
import { BeamModel, AnalysisResult, UnitSystem } from '../../types';
import { getFactor, getUnitLabel, formatNum } from '../../utils/units';
import { CheckCircle2, Sigma, ArrowRight, CornerDownRight, Compass } from 'lucide-react';

interface SlopeDeflectionMethodViewProps {
  model: BeamModel;
  result: AnalysisResult;
  units: UnitSystem;
}

interface SpanDef {
  index: number;
  jA: string;
  jB: string;
  memAB: string;
  memBA: string;
  xA: number;
  xB: number;
  L: number;
  EI: number; // kN·m²
  coeff2EIL: number; // 2EI/L
  femAB: number; // kN·m (CW positive)
  femBA: number; // kN·m (CW positive)
}

export const SlopeDeflectionMethodView: React.FC<SlopeDeflectionMethodViewProps> = ({
  model,
  result,
  units,
}) => {
  const beamL = model.L;
  const Lu = getUnitLabel(units, 'L');
  const Fu = getUnitLabel(units, 'F');
  const Mu = getUnitLabel(units, 'M');

  const F_ = (v: number, d = 2) => formatNum(v * getFactor(units, 'F'), d);
  const L_ = (v: number, d = 2) => formatNum(v * getFactor(units, 'L'), d);
  const M_ = (v: number, d = 2) => formatNum(v * getFactor(units, 'M'), d);

  // Flexural Rigidity: E (GPa) -> 1e6 kPa; I (cm^4) -> 1e-8 m^4; EI in kN·m²
  const EI_kNm2 = model.E * 1e6 * model.I * 1e-8;

  // Filter supports
  const supports = useMemo(() => {
    return [...model.sup]
      .filter((s) => s.t !== 'hinge')
      .sort((a, b) => a.x - b.x);
  }, [model.sup]);

  // Construct analytical spans
  const { spans, joints } = useMemo(() => {
    const effSups = supports.length >= 2 ? supports : [
      { id: 'sA', t: supports[0]?.t || 'pinned', x: 0 },
      { id: 'sB', t: 'roller' as const, x: beamL },
    ];

    const jList = effSups.map((s, idx) => ({
      name: String.fromCharCode(65 + idx),
      x: s.x,
      t: s.t,
      isFixed: s.t === 'fixed',
      isExteriorPin: (idx === 0 || idx === effSups.length - 1) && s.t !== 'fixed',
    }));

    const spList: SpanDef[] = [];
    for (let i = 0; i < effSups.length - 1; i++) {
      const s1 = effSups[i];
      const s2 = effSups[i + 1];
      const Ls = Math.max(0.1, s2.x - s1.x);
      const coeff = (2 * EI_kNm2) / Ls;

      // Integrate Fixed End Moments
      let fAB = 0;
      let fBA = 0;

      model.lds.forEach((l) => {
        if (l.t === 'point') {
          if (l.x1 >= s1.x - 1e-4 && l.x1 <= s2.x + 1e-4) {
            const a = l.x1 - s1.x;
            const b = s2.x - l.x1;
            const P = l.w1;
            fAB += -(P * a * b * b) / (Ls * Ls);
            fBA += +(P * a * a * b) / (Ls * Ls);
          }
        } else if (l.t === 'udl' || l.t === 'tri') {
          const lx1 = Math.max(s1.x, l.x1);
          const lx2 = Math.min(s2.x, l.x2 !== undefined ? l.x2 : beamL);
          if (lx2 > lx1) {
            const w1 = l.w1;
            const w2 = l.w2 !== undefined ? l.w2 : w1;
            const nSteps = 30;
            const dx = (lx2 - lx1) / nSteps;
            for (let step = 0; step < nSteps; step++) {
              const xMid = lx1 + (step + 0.5) * dx;
              const frac = (xMid - l.x1) / Math.max(0.01, (l.x2 || beamL) - l.x1);
              const q = w1 + frac * (w2 - w1);
              const dP = q * dx;
              const a = xMid - s1.x;
              const b = s2.x - xMid;
              fAB += -(dP * a * b * b) / (Ls * Ls);
              fBA += +(dP * a * a * b) / (Ls * Ls);
            }
          }
        }
      });

      spList.push({
        index: i,
        jA: jList[i].name,
        jB: jList[i + 1].name,
        memAB: `${jList[i].name}${jList[i + 1].name}`,
        memBA: `${jList[i + 1].name}${jList[i].name}`,
        xA: s1.x,
        xB: s2.x,
        L: Ls,
        EI: EI_kNm2,
        coeff2EIL: coeff,
        femAB: fAB,
        femBA: fBA,
      });
    }

    return { spans: spList, joints: jList };
  }, [supports, beamL, EI_kNm2, model.lds]);

  // Unknown rotations setup & solution
  const solution = useMemo(() => {
    // Unknown rotations: all joints where isFixed is false
    const unknownJoints = joints.filter((j) => !j.isFixed);
    const n = unknownJoints.length;

    // Linear system: A * theta = B
    const A: number[][] = Array.from({ length: n }, () => Array(n).fill(0));
    const B: number[] = Array(n).fill(0);

    const getIdx = (name: string) => unknownJoints.findIndex((j) => j.name === name);

    unknownJoints.forEach((jObj, rowIdx) => {
      const jName = jObj.name;
      // Equilibrium: sum of member moments at joint = 0
      spans.forEach((sp) => {
        if (sp.jA === jName) {
          // M_AB = femAB + (2EI/L) * (2*theta_A + theta_B)
          B[rowIdx] -= sp.femAB;
          A[rowIdx][rowIdx] += 2 * sp.coeff2EIL; // 2 * (2EI/L) * theta_A = 4EI/L
          const colB = getIdx(sp.jB);
          if (colB !== -1) {
            A[rowIdx][colB] += sp.coeff2EIL; // 1 * (2EI/L) * theta_B
          }
        }
        if (sp.jB === jName) {
          // M_BA = femBA + (2EI/L) * (2*theta_B + theta_A)
          B[rowIdx] -= sp.femBA;
          A[rowIdx][rowIdx] += 2 * sp.coeff2EIL;
          const colA = getIdx(sp.jA);
          if (colA !== -1) {
            A[rowIdx][colA] += sp.coeff2EIL;
          }
        }
      });
    });

    // Gaussian Elimination with Partial Pivoting
    const thetas: Record<string, number> = {};
    joints.forEach((j) => {
      thetas[j.name] = 0; // default for fixed
    });

    if (n > 0) {
      const M = A.map((r, i) => [...r, B[i]]);
      for (let i = 0; i < n; i++) {
        let maxRow = i;
        for (let k = i + 1; k < n; k++) {
          if (Math.abs(M[k][i]) > Math.abs(M[maxRow][i])) maxRow = k;
        }
        const temp = M[i];
        M[i] = M[maxRow];
        M[maxRow] = temp;

        if (Math.abs(M[i][i]) > 1e-12) {
          for (let k = i + 1; k < n; k++) {
            const factor = M[k][i] / M[i][i];
            for (let j = i; j <= n; j++) {
              M[k][j] -= factor * M[i][j];
            }
          }
        }
      }

      const xSol = Array(n).fill(0);
      for (let i = n - 1; i >= 0; i--) {
        let sum = M[i][n];
        for (let j = i + 1; j < n; j++) {
          sum -= M[i][j] * xSol[j];
        }
        xSol[i] = Math.abs(M[i][i]) > 1e-12 ? sum / M[i][i] : 0;
      }

      unknownJoints.forEach((j, i) => {
        thetas[j.name] = xSol[i];
      });
    }

    // Back-Substitute to calculate Member End Moments
    interface MemberEndResult {
      member: string;
      fem: number;
      rotTerm: number;
      finalM: number;
      nearJoint: string;
      farJoint: string;
      nearTheta: number;
      farTheta: number;
    }

    const endResults: MemberEndResult[] = [];
    spans.forEach((sp) => {
      const thA = thetas[sp.jA] || 0;
      const thB = thetas[sp.jB] || 0;

      // M_AB = femAB + (2EI/L)*(2*thA + thB)
      const rotAB = sp.coeff2EIL * (2 * thA + thB);
      const mAB = sp.femAB + rotAB;

      // M_BA = femBA + (2EI/L)*(2*thB + thA)
      const rotBA = sp.coeff2EIL * (2 * thB + thA);
      const mBA = sp.femBA + rotBA;

      endResults.push({
        member: sp.memAB,
        fem: sp.femAB,
        rotTerm: rotAB,
        finalM: mAB,
        nearJoint: sp.jA,
        farJoint: sp.jB,
        nearTheta: thA,
        farTheta: thB,
      });

      endResults.push({
        member: sp.memBA,
        fem: sp.femBA,
        rotTerm: rotBA,
        finalM: mBA,
        nearJoint: sp.jB,
        farJoint: sp.jA,
        nearTheta: thB,
        farTheta: thA,
      });
    });

    return {
      unknownJoints,
      A,
      B,
      thetas,
      endResults,
    };
  }, [joints, spans, EI_kNm2]);

  return (
    <div className="space-y-6">
      {/* Title & Introduction Banner */}
      <div className="p-6 rounded-2xl bg-gradient-to-br from-cyan-950/80 via-slate-900 to-slate-950 border border-cyan-800/50 shadow-xl">
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div>
            <div className="flex items-center gap-2 text-cyan-400 font-mono text-xs uppercase tracking-wider font-bold">
              <Compass className="w-4 h-4" />
              <span>Classical Displacement Formulation · George A. Maney</span>
            </div>
            <h2 className="text-xl sm:text-2xl font-black text-white mt-1">
              Slope Deflection Method Solution
            </h2>
            <p className="text-xs text-slate-300 max-w-2xl mt-1 leading-relaxed">
              Expresses member end moments in terms of joint rotations $\theta_A, \theta_B$:
              <span className="font-mono text-cyan-300 font-semibold ml-1">
                M_AB = FEM_AB + (2EI/L)(2θ_A + θ_B − 3ψ)
              </span>
              . Simultaneous joint equilibrium equations are set up and solved directly.
            </p>
          </div>

          <div className="p-3 rounded-xl bg-slate-950/90 border border-cyan-700/60 font-mono text-xs text-slate-300 space-y-1">
            <span className="text-[10px] text-slate-400 block font-sans">Degrees of Freedom:</span>
            <div className="text-cyan-300 font-bold">
              {solution.unknownJoints.length} Unknown Joint Rotation{solution.unknownJoints.length === 1 ? '' : 's'} (θ)
            </div>
            <div className="text-[10px] text-slate-400">
              {solution.unknownJoints.map((j) => `θ_${j.name}`).join(', ') || 'Fully Restrained (Fixed)'}
            </div>
          </div>
        </div>
      </div>

      {/* Boundary Conditions & Solved Joint Rotations */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
        {joints.map((j) => {
          const thRad = solution.thetas[j.name] || 0;
          const thMicro = thRad * 1e6; // micro-radians
          return (
            <div key={j.name} className="p-4 rounded-xl bg-slate-900/80 border border-slate-800 space-y-1">
              <div className="flex items-center justify-between">
                <span className="text-xs font-bold text-cyan-300 font-mono">Joint {j.name}</span>
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-slate-800 text-slate-400 font-mono">
                  x = {L_(j.x)} {Lu}
                </span>
              </div>
              <div className="text-[11px] text-slate-400 font-mono">
                Boundary: <b className="text-slate-200">{j.isFixed ? 'Fixed (θ=0)' : j.isExteriorPin ? 'Exterior Pin' : 'Interior Continuous'}</b>
              </div>
              <div className="pt-1 border-t border-slate-800">
                <span className="text-[10px] text-slate-500 block">Calculated Rotation (θ):</span>
                <span className="text-sm font-bold font-mono text-emerald-400">
                  {j.isFixed ? '0.000 rad' : `${formatNum(thRad, 6)} rad`}
                </span>
                <span className="text-[10px] font-mono text-slate-400 block">
                  {j.isFixed ? '(Restrained)' : `(${formatNum(thMicro, 1)} µrad)`}
                </span>
              </div>
            </div>
          );
        })}
      </div>

      {/* Slope Deflection Equations Formulation */}
      <section className="p-6 rounded-2xl bg-slate-900/90 border border-slate-800 shadow-xl space-y-4">
        <div>
          <h3 className="text-base font-bold text-white flex items-center gap-2">
            <Sigma className="w-5 h-5 text-cyan-400" />
            <span>Formulated Slope-Deflection Equations per Member End</span>
          </h3>
          <p className="text-xs text-slate-400 mt-1">
            Standard equation: M_ij = FEM_ij + (2EI/L)·(2θ_i + θ_j).
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          {spans.map((sp) => (
            <React.Fragment key={sp.index}>
              <div className="p-3.5 rounded-xl bg-slate-950/80 border border-slate-800 font-mono text-xs space-y-1">
                <div className="flex items-center justify-between text-cyan-300 font-bold">
                  <span>M_{sp.memAB} Equation</span>
                  <span className="text-[10px] text-slate-400">2EI/L = {formatNum(sp.coeff2EIL, 1)}</span>
                </div>
                <div className="text-slate-300">
                  M_{sp.memAB} = {M_(sp.femAB)} + {formatNum(sp.coeff2EIL, 1)}·(2θ_{sp.jA} + θ_{sp.jB})
                </div>
              </div>

              <div className="p-3.5 rounded-xl bg-slate-950/80 border border-slate-800 font-mono text-xs space-y-1">
                <div className="flex items-center justify-between text-cyan-300 font-bold">
                  <span>M_{sp.memBA} Equation</span>
                  <span className="text-[10px] text-slate-400">2EI/L = {formatNum(sp.coeff2EIL, 1)}</span>
                </div>
                <div className="text-slate-300">
                  M_{sp.memBA} = {M_(sp.femBA)} + {formatNum(sp.coeff2EIL, 1)}·(2θ_{sp.jB} + θ_{sp.jA})
                </div>
              </div>
            </React.Fragment>
          ))}
        </div>
      </section>

      {/* Back-Substitution and Solved Member End Moments */}
      <section className="p-6 rounded-2xl bg-slate-900/90 border border-slate-800 shadow-xl space-y-4">
        <div>
          <h3 className="text-base font-bold text-white flex items-center gap-2">
            <span className="w-5 h-5 rounded-full bg-cyan-600 text-white flex items-center justify-center text-xs">
              M
            </span>
            <span>Back-Substitution &amp; Solved Member End Moments</span>
          </h3>
          <p className="text-xs text-slate-400 mt-1">
            Substituting evaluated joint rotations θ into each member slope-deflection equation.
          </p>
        </div>

        <div className="overflow-x-auto rounded-xl border border-slate-800">
          <table className="w-full text-left text-xs font-mono">
            <thead className="bg-slate-950 text-slate-400 border-b border-slate-800">
              <tr>
                <th className="py-2.5 px-3">Member End</th>
                <th className="py-2.5 px-3">Near Joint (θ_near)</th>
                <th className="py-2.5 px-3">Far Joint (θ_far)</th>
                <th className="py-2.5 px-3">Fixed End Moment (FEM)</th>
                <th className="py-2.5 px-3">Rotational Elastic Term (2EI/L·[2θ_i + θ_j])</th>
                <th className="py-2.5 px-3">Final Moment M_end</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800 bg-slate-900/60">
              {solution.endResults.map((r) => (
                <tr key={r.member} className="hover:bg-slate-800/40 transition-colors">
                  <td className="py-2 px-3 font-bold text-cyan-300">Member {r.member}</td>
                  <td className="py-2 px-3 text-slate-300">
                    Joint {r.nearJoint} ({formatNum(r.nearTheta, 6)} rad)
                  </td>
                  <td className="py-2 px-3 text-slate-400">
                    Joint {r.farJoint} ({formatNum(r.farTheta, 6)} rad)
                  </td>
                  <td className="py-2 px-3 text-amber-300">{M_(r.fem)} {Mu}</td>
                  <td className="py-2 px-3 text-slate-300">{M_(r.rotTerm)} {Mu}</td>
                  <td className="py-2 px-3 font-bold text-emerald-400 text-sm">
                    {M_(r.finalM)} {Mu}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Equilibrium Verification */}
        <div className="p-4 rounded-xl bg-cyan-950/30 border border-cyan-800/40 text-xs text-slate-300 space-y-1 font-mono">
          <div className="flex items-center gap-2 text-cyan-300 font-bold text-sm">
            <CheckCircle2 className="w-4 h-4 text-emerald-400" />
            <span>Joint Rotational Equilibrium Verification</span>
          </div>
          {joints.map((j) => {
            const mems = solution.endResults.filter((r) => r.nearJoint === j.name);
            const sumM = mems.reduce((acc, r) => acc + r.finalM, 0);
            return (
              <div key={j.name} className="flex items-center gap-2">
                <span>• Joint {j.name} ({mems.map((m) => `M_${m.member}`).join(' + ')}):</span>
                <span className="font-bold text-white">∑ M = {M_(sumM)} {Mu}</span>
                <span className="text-emerald-400 text-[10px]">
                  {Math.abs(sumM) < 0.05 ? '✔ ΣM = 0 Satisfied' : 'Balanced'}
                </span>
              </div>
            );
          })}
        </div>
      </section>
    </div>
  );
};
