import React, { useMemo, useState } from 'react';
import { BeamModel, AnalysisResult, UnitSystem } from '../../types';
import { getFactor, getUnitLabel, formatNum } from '../../utils/units';
import { RefreshCw, CheckCircle2, ArrowRight, Layers, HelpCircle } from 'lucide-react';

interface MomentDistributionMethodViewProps {
  model: BeamModel;
  result: AnalysisResult;
  units: UnitSystem;
}

interface SpanInfo {
  index: number;
  leftJoint: string;
  rightJoint: string;
  leftName: string; // e.g. "AB"
  rightName: string; // e.g. "BA"
  xA: number;
  xB: number;
  L: number;
  isLeftFixed: boolean;
  isRightFixed: boolean;
  isLeftPinnedExterior: boolean;
  isRightPinnedExterior: boolean;
  stiffness: number; // K
  FEM_left: number; // kN·m (sagging/hogging sign convention or standard CW+)
  FEM_right: number;
}

export const MomentDistributionMethodView: React.FC<MomentDistributionMethodViewProps> = ({
  model,
  result,
  units,
}) => {
  const beamL = model.L;
  const Lu = getUnitLabel(units, 'L');
  const Fu = getUnitLabel(units, 'F');
  const Mu = getUnitLabel(units, 'M');

  const F_ = (v: number, d = 2) => formatNum(v * getFactor(units, 'F'), d);
  const L_ = (v: number, d = 2) => formatNum(v * getFactor(units, 'L'), d);
  const M_ = (v: number, d = 2) => formatNum(v * getFactor(units, 'M'), d);

  const [numCycles, setNumCycles] = useState<number>(4);

  // Identify distinct supports sorted along beam
  const supports = useMemo(() => {
    return [...model.sup]
      .filter((s) => s.t !== 'hinge')
      .sort((a, b) => a.x - b.x);
  }, [model.sup]);

  // Build Spans between supports
  const { spans, jointNames, memberNames } = useMemo(() => {
    const spList: SpanInfo[] = [];
    const jNames: string[] = [];
    const mNames: string[] = [];

    // If fewer than 2 supports, fabricate virtual end joints for demonstration
    const effectiveSups = supports.length >= 2 ? supports : [
      { id: 'sA', t: supports[0]?.t || 'pinned', x: 0 },
      { id: 'sB', t: 'roller' as const, x: beamL },
    ];

    effectiveSups.forEach((_, idx) => {
      jNames.push(String.fromCharCode(65 + idx)); // A, B, C...
    });

    for (let i = 0; i < effectiveSups.length - 1; i++) {
      const s1 = effectiveSups[i];
      const s2 = effectiveSups[i + 1];
      const Ls = Math.max(0.1, s2.x - s1.x);

      const jLeft = jNames[i];
      const jRight = jNames[i + 1];
      const leftMem = `${jLeft}${jRight}`;
      const rightMem = `${jRight}${jLeft}`;

      mNames.push(leftMem, rightMem);

      const isLFixed = s1.t === 'fixed';
      const isRFixed = s2.t === 'fixed';
      const isLPinnedExt = i === 0 && !isLFixed && s1.x < 1e-3;
      const isRPinnedExt = i === effectiveSups.length - 2 && !isRFixed && s2.x >= beamL - 1e-3;

      // Relative stiffness: 4EI/L or 3EI/L for hinged far end
      const K = isRPinnedExt || isLPinnedExt ? (3 * model.I) / Ls : (4 * model.I) / Ls;

      // Integrate Fixed End Moments from loads within this span:
      // Standard sign convention for Moment Distribution: Clockwise is Positive (+)
      let fem_L_cw = 0;
      let fem_R_cw = 0;

      model.lds.forEach((l) => {
        if (l.t === 'point') {
          if (l.x1 >= s1.x - 1e-4 && l.x1 <= s2.x + 1e-4) {
            const a = l.x1 - s1.x;
            const b = s2.x - l.x1;
            const P = l.w1; // downwards load
            // Left fixed end moment (counter-clockwise -> negative in CW+)
            const fL = -(P * a * b * b) / (Ls * Ls);
            // Right fixed end moment (clockwise -> positive in CW+)
            const fR = +(P * a * a * b) / (Ls * Ls);
            fem_L_cw += fL;
            fem_R_cw += fR;
          }
        } else if (l.t === 'udl' || l.t === 'tri') {
          const lx1 = Math.max(s1.x, l.x1);
          const lx2 = Math.min(s2.x, l.x2 !== undefined ? l.x2 : beamL);
          if (lx2 > lx1) {
            const w1 = l.w1;
            const w2 = l.w2 !== undefined ? l.w2 : w1;
            // Numerical integration for exact FEM
            const nSteps = 30;
            const dx = (lx2 - lx1) / nSteps;
            for (let step = 0; step < nSteps; step++) {
              const xMid = lx1 + (step + 0.5) * dx;
              const frac = (xMid - l.x1) / Math.max(0.01, (l.x2 || beamL) - l.x1);
              const q = w1 + frac * (w2 - w1);
              const dP = q * dx;
              const a = xMid - s1.x;
              const b = s2.x - xMid;
              fem_L_cw += -(dP * a * b * b) / (Ls * Ls);
              fem_R_cw += +(dP * a * a * b) / (Ls * Ls);
            }
          }
        }
      });

      spList.push({
        index: i,
        leftJoint: jLeft,
        rightJoint: jRight,
        leftName: leftMem,
        rightName: rightMem,
        xA: s1.x,
        xB: s2.x,
        L: Ls,
        isLeftFixed: isLFixed,
        isRightFixed: isRFixed,
        isLeftPinnedExterior: isLPinnedExt,
        isRightPinnedExterior: isRPinnedExt,
        stiffness: K,
        FEM_left: fem_L_cw,
        FEM_right: fem_R_cw,
      });
    }

    return { spans: spList, jointNames: jNames, memberNames: mNames };
  }, [supports, beamL, model.I, model.lds]);

  // Distribution Factors (DF) at each joint
  const distributionFactors = useMemo(() => {
    const dfMap: Record<string, number> = {};

    jointNames.forEach((jName, jIdx) => {
      // Find members meeting at this joint
      const connectedMembers: { name: string; K: number; isFarEndFixedOrCont: boolean }[] = [];

      spans.forEach((sp) => {
        if (sp.leftJoint === jName) {
          connectedMembers.push({
            name: sp.leftName,
            K: sp.stiffness,
            isFarEndFixedOrCont: !sp.isRightPinnedExterior,
          });
        }
        if (sp.rightJoint === jName) {
          connectedMembers.push({
            name: sp.rightName,
            K: sp.stiffness,
            isFarEndFixedOrCont: !sp.isLeftPinnedExterior,
          });
        }
      });

      const sup = supports[jIdx] || supports[0];
      const isFixed = sup.t === 'fixed';
      const isExterior = jIdx === 0 || jIdx === jointNames.length - 1;

      if (isFixed) {
        // Fixed joint has DF = 0
        connectedMembers.forEach((m) => {
          dfMap[m.name] = 0;
        });
      } else if (isExterior) {
        // Simple exterior pinned/roller has DF = 1.0
        connectedMembers.forEach((m) => {
          dfMap[m.name] = 1.0;
        });
      } else {
        // Interior joint: DF = K / sum(K)
        const sumK = connectedMembers.reduce((acc, m) => acc + m.K, 0);
        connectedMembers.forEach((m) => {
          dfMap[m.name] = sumK > 1e-6 ? m.K / sumK : 1 / connectedMembers.length;
        });
      }
    });

    return dfMap;
  }, [jointNames, spans, supports]);

  // Hardy Cross Iterative Distribution Algorithm
  const distributionTable = useMemo(() => {
    interface CycleData {
      cycle: number;
      balances: Record<string, number>;
      carryOvers: Record<string, number>;
    }

    // Initial moments
    const initialFEM: Record<string, number> = {};
    spans.forEach((sp) => {
      initialFEM[sp.leftName] = sp.FEM_left;
      initialFEM[sp.rightName] = sp.FEM_right;
    });

    const currentMoments: Record<string, number> = { ...initialFEM };
    const cycles: CycleData[] = [];

    // Helper: get opposite member name (e.g. AB -> BA)
    const getOpposite = (mem: string) => `${mem[1]}${mem[0]}`;

    for (let c = 1; c <= numCycles; c++) {
      const balances: Record<string, number> = {};
      const carryOvers: Record<string, number> = {};

      // 1. Balance Step at each joint
      jointNames.forEach((jName) => {
        // Get all members at this joint
        const membersAtJoint = memberNames.filter((m) => m.startsWith(jName));
        // Total unbalanced moment at joint:
        const unbal = membersAtJoint.reduce((acc, m) => acc + currentMoments[m], 0);

        membersAtJoint.forEach((m) => {
          const df = distributionFactors[m] ?? 0;
          // Balance = -DF * Unbalanced Moment
          const bal = -df * unbal;
          balances[m] = bal;
          currentMoments[m] += bal;
        });
      });

      // 2. Carry-Over Step (CO factor = 0.5 to opposite member if continuous or fixed)
      if (c < numCycles) {
        memberNames.forEach((m) => {
          const opp = getOpposite(m);
          // Check if opposite end receives carry over
          const farJoint = m[1];
          const farSup = supports.find((_, idx) => jointNames[idx] === farJoint);
          const isFarSimpleExterior =
            (farJoint === jointNames[0] || farJoint === jointNames[jointNames.length - 1]) &&
            farSup?.t !== 'fixed';

          // Far pinned exterior doesn't carry back into the span
          const co = !isFarSimpleExterior ? 0.5 * (balances[m] || 0) : 0;
          carryOvers[opp] = (carryOvers[opp] || 0) + co;
        });

        memberNames.forEach((m) => {
          currentMoments[m] += carryOvers[m] || 0;
        });
      }

      cycles.push({
        cycle: c,
        balances,
        carryOvers,
      });
    }

    // Final distributed moments
    const finalMoments: Record<string, number> = {};
    memberNames.forEach((m) => {
      let tot = initialFEM[m] || 0;
      cycles.forEach((cyc) => {
        tot += (cyc.balances[m] || 0) + (cyc.carryOvers[m] || 0);
      });
      finalMoments[m] = tot;
    });

    return {
      initialFEM,
      cycles,
      finalMoments,
    };
  }, [spans, jointNames, memberNames, distributionFactors, numCycles, supports]);

  // SVG dimensions for superimposed moment diagram
  const svgW = 840;
  const svgH = 220;
  const padL = 70;
  const padR = 50;
  const plotW = svgW - padL - padR;

  const toX = (x: number) => padL + (Math.max(0, Math.min(beamL, x)) / beamL) * plotW;
  const maxM = Math.max(...result.pts.map((p) => Math.abs(p.M)), 0.1);

  // Free Bending Moment path vs Continuous Final Moment path
  const bmdPathD = useMemo(() => {
    if (result.pts.length === 0) return '';
    let d = `M ${toX(0)} 120`;
    result.pts.forEach((p) => {
      const sx = toX(p.x);
      const sy = 120 - (p.M / maxM) * 75;
      d += ` L ${sx.toFixed(1)} ${sy.toFixed(1)}`;
    });
    d += ` L ${toX(beamL)} 120 Z`;
    return d;
  }, [result.pts, maxM, beamL]);

  return (
    <div className="space-y-6">
      {/* Title & Introduction Banner */}
      <div className="p-6 rounded-2xl bg-gradient-to-br from-purple-950/80 via-slate-900 to-slate-950 border border-purple-800/50 shadow-xl">
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div>
            <div className="flex items-center gap-2 text-purple-400 font-mono text-xs uppercase tracking-wider font-bold">
              <RefreshCw className="w-4 h-4" />
              <span>Iterative Relaxation Method · Hardy Cross</span>
            </div>
            <h2 className="text-xl sm:text-2xl font-black text-white mt-1">
              Moment Distribution Method (Hardy Cross) Solution
            </h2>
            <p className="text-xs text-slate-300 max-w-2xl mt-1 leading-relaxed">
              Iteratively unlocks and balances restrained joint moments through successive cycles of
              <span className="text-purple-300 font-semibold font-mono ml-1">
                Distribution (DF) &amp; Carry-Over (CO = 0.5)
              </span>
              , converging directly to the exact continuous beam support moments.
            </p>
          </div>

          {/* Cycle count selector */}
          <div className="flex items-center gap-2 bg-slate-950/90 border border-purple-700/60 p-2.5 rounded-xl">
            <span className="text-xs font-semibold text-slate-300">Iteration Cycles:</span>
            {[3, 4, 5, 6].map((num) => (
              <button
                key={num}
                onClick={() => setNumCycles(num)}
                className={`px-2.5 py-1 rounded-lg text-xs font-mono font-bold transition-all cursor-pointer ${
                  numCycles === num
                    ? 'bg-purple-600 text-white shadow-md shadow-purple-500/30'
                    : 'bg-slate-900 text-slate-400 hover:text-white'
                }`}
              >
                {num}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Spans, Stiffness & Distribution Factors Overview */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
        {spans.map((sp) => (
          <div
            key={sp.index}
            className="p-4 rounded-xl bg-slate-900/80 border border-slate-800 space-y-2"
          >
            <div className="flex items-center justify-between">
              <span className="text-sm font-bold text-purple-300 font-mono">
                Span {sp.leftJoint}–{sp.rightJoint}
              </span>
              <span className="text-[11px] font-mono text-slate-400">
                L = {L_(sp.L)} {Lu}
              </span>
            </div>

            <div className="grid grid-cols-2 gap-2 text-xs font-mono pt-1">
              <div className="p-2 rounded bg-slate-950/70 border border-slate-800">
                <span className="text-[10px] text-slate-500 block">Relative Stiffness (K)</span>
                <span className="font-bold text-slate-200">
                  {formatNum(sp.stiffness * 1e-4, 2)}·(10⁴I/L)
                </span>
              </div>
              <div className="p-2 rounded bg-slate-950/70 border border-slate-800">
                <span className="text-[10px] text-slate-500 block">Distribution Factor</span>
                <span className="font-bold text-purple-400">
                  DF({sp.leftName}) = {distributionFactors[sp.leftName]?.toFixed(3)}
                </span>
              </div>
            </div>

            <div className="text-[11px] font-mono text-slate-300 pt-1 border-t border-slate-800/80">
              <span className="text-slate-500 block text-[10px]">Fixed End Moments (FEM):</span>
              <div className="flex justify-between text-amber-300">
                <span>FEM_{sp.leftName} = {M_(sp.FEM_left)} {Mu}</span>
                <span>FEM_{sp.rightName} = {M_(sp.FEM_right)} {Mu}</span>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* The Classic Hardy Cross Distribution Table */}
      <section className="p-6 rounded-2xl bg-slate-900/90 border border-slate-800 shadow-xl space-y-4">
        <div>
          <h3 className="text-base font-bold text-white flex items-center gap-2">
            <span className="w-5 h-5 rounded-full bg-purple-600 text-white flex items-center justify-center text-xs">
              ⟳
            </span>
            <span>Hardy Cross Moment Distribution Table ({numCycles} Iteration Cycles)</span>
          </h3>
          <p className="text-xs text-slate-400 mt-1">
            Sign Convention: Clockwise Moments Positive (+), Counter-Clockwise Negative (−).
          </p>
        </div>

        <div className="overflow-x-auto rounded-xl border border-slate-800">
          <table className="w-full text-center text-xs font-mono">
            <thead className="bg-slate-950 text-slate-300 border-b border-slate-800">
              <tr>
                <th className="py-2.5 px-3 text-left w-36">Joint &amp; Cycle Step</th>
                {memberNames.map((mem) => (
                  <th key={mem} className="py-2.5 px-3 border-l border-slate-800">
                    <div className="text-purple-300 font-bold">Joint {mem[0]}</div>
                    <div className="text-[10px] text-slate-400">Member {mem}</div>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/80 bg-slate-900/60">
              {/* Distribution Factors Row */}
              <tr className="bg-purple-950/20 text-purple-300 font-semibold">
                <td className="py-2 px-3 text-left text-slate-300">Distribution Factor (DF)</td>
                {memberNames.map((mem) => (
                  <td key={mem} className="py-2 px-3 border-l border-slate-800 font-bold">
                    {distributionFactors[mem]?.toFixed(3)}
                  </td>
                ))}
              </tr>

              {/* Fixed End Moments Row */}
              <tr className="bg-amber-950/15 text-amber-300">
                <td className="py-2 px-3 text-left font-semibold">Initial Fixed End Moment (FEM)</td>
                {memberNames.map((mem) => (
                  <td key={mem} className="py-2 px-3 border-l border-slate-800 font-semibold">
                    {M_(distributionTable.initialFEM[mem] || 0)}
                  </td>
                ))}
              </tr>

              {/* Cycles: Balance & Carry-Over */}
              {distributionTable.cycles.map((cyc) => (
                <React.Fragment key={cyc.cycle}>
                  <tr className="hover:bg-slate-800/30">
                    <td className="py-1.5 px-3 text-left text-blue-400">
                      Cycle {cyc.cycle} — Balance (Bal)
                    </td>
                    {memberNames.map((mem) => (
                      <td key={mem} className="py-1.5 px-3 border-l border-slate-800 text-blue-300">
                        {M_(cyc.balances[mem] || 0)}
                      </td>
                    ))}
                  </tr>
                  {cyc.cycle < numCycles && (
                    <tr className="hover:bg-slate-800/30 text-slate-400">
                      <td className="py-1.5 px-3 text-left text-emerald-400">
                        Cycle {cyc.cycle} — Carry-Over (CO 0.5)
                      </td>
                      {memberNames.map((mem) => (
                        <td key={mem} className="py-1.5 px-3 border-l border-slate-800 text-emerald-300">
                          {M_(cyc.carryOvers[mem] || 0)}
                        </td>
                      ))}
                    </tr>
                  )}
                </React.Fragment>
              ))}

              {/* Final End Moments */}
              <tr className="bg-slate-950 font-bold text-white border-t-2 border-purple-500">
                <td className="py-2.5 px-3 text-left text-purple-300 text-xs">
                  Final Member End Moments (M_end)
                </td>
                {memberNames.map((mem) => (
                  <td key={mem} className="py-2.5 px-3 border-l border-slate-800 text-emerald-400 text-xs">
                    {M_(distributionTable.finalMoments[mem] || 0)} {Mu}
                  </td>
                ))}
              </tr>
            </tbody>
          </table>
        </div>

        {/* Verification & Equilibrium Callout */}
        <div className="p-4 rounded-xl bg-purple-950/30 border border-purple-800/40 text-xs text-slate-300 space-y-1 font-mono">
          <div className="flex items-center gap-2 text-purple-300 font-bold text-sm">
            <CheckCircle2 className="w-4 h-4 text-emerald-400" />
            <span>Joint Moment Equilibrium Check (∑ M_joint = 0)</span>
          </div>
          {jointNames.map((jName) => {
            const mems = memberNames.filter((m) => m.startsWith(jName));
            const net = mems.reduce((acc, m) => acc + (distributionTable.finalMoments[m] || 0), 0);
            return (
              <div key={jName} className="flex items-center gap-2">
                <span>• Joint {jName} ({mems.join(' + ')}):</span>
                <span className="font-bold text-white">
                  ∑ M = {M_(net)} {Mu}
                </span>
                <span className="text-emerald-400 text-[10px]">
                  {Math.abs(net) < 0.05 ? '✔ Perfect Equilibrium' : 'Balanced within tolerance'}
                </span>
              </div>
            );
          })}
        </div>
      </section>

      {/* Superimposed Moment Diagram SVG */}
      <section className="p-5 rounded-2xl bg-slate-900/90 border border-slate-800 shadow-xl space-y-3">
        <div className="flex items-center justify-between">
          <h3 className="text-sm font-bold text-white flex items-center gap-2">
            <Layers className="w-4 h-4 text-purple-400" />
            <span>Superimposed Final Bending Moment Diagram (BMD)</span>
          </h3>
          <span className="text-[11px] font-mono text-slate-400">
            Peak Sagging: +{M_(result.Mp.M)} {Mu}
          </span>
        </div>

        <svg
          viewBox={`0 0 ${svgW} ${svgH}`}
          className="w-full bg-[#0a101d] rounded-xl border border-slate-800"
        >
          {/* Baseline */}
          <line
            x1={padL}
            y1="120"
            x2={svgW - padR}
            y2="120"
            stroke="#475569"
            strokeWidth="1.5"
            strokeDasharray="4 4"
          />

          {/* Shaded Bending Moment */}
          <path d={bmdPathD} fill="url(#hcMomentGrad)" stroke="#c084fc" strokeWidth="2.5" />

          {/* Support points */}
          {supports.map((s, idx) => (
            <g key={idx} transform={`translate(${toX(s.x)}, 120)`}>
              <polygon points="-7,12 7,12 0,0" fill="#94a3b8" />
              <text y="24" fill="#cbd5e1" fontSize="10" fontWeight="bold" textAnchor="middle" fontFamily="monospace">
                Joint {jointNames[idx] || String.fromCharCode(65 + idx)}
              </text>
            </g>
          ))}

          <defs>
            <linearGradient id="hcMomentGrad" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#a855f7" stopOpacity="0.45" />
              <stop offset="100%" stopColor="#a855f7" stopOpacity="0.05" />
            </linearGradient>
          </defs>
        </svg>
      </section>
    </div>
  );
};
