import React from 'react';
import { BeamModel, AnalysisResult, UnitSystem } from '../types';
import { SolutionPreviewView } from './SolutionPreviewView';

interface StepByStepModalProps {
  model: BeamModel;
  result: AnalysisResult;
  units: UnitSystem;
  presetName?: string;
  onClose: () => void;
}

export const StepByStepModal: React.FC<StepByStepModalProps> = ({
  model,
  result,
  units,
  presetName,
  onClose,
}) => {
  return (
    <SolutionPreviewView
      model={model}
      result={result}
      units={units}
      presetName={presetName}
      onClose={onClose}
      isModal={true}
    />
  );
};
