import React, { useState, useMemo } from 'react';
import {
  BeamModel,
  UnitSystem,
  InfluenceQuantity,
  InfluencePoint,
  AnalysisResult,
} from '../types';
import {
  calculateInfluenceLine,
  interpolateEta,
  solveBeam,
} from '../utils/solver';
import { getFactor, getUnitLabel, formatNum } from '../utils/units';
import { DiagramCanvas } from './DiagramCanvas';
import {
  Sparkles,
  Info,
  BookOpen,
  Sliders,
  Maximize2,
  TrendingUp,
  TrendingDown,
  Target,
  ArrowRight,
  Truck,
  CheckCircle2,
  Compass,
} from 'lucide-react';
import { InfluenceLineTutorialModal } from './InfluenceLineTutorialModal';

interface InfluenceLinePanelProps {
  model: BeamModel;
  units: UnitSystem;
  onOpenStepByStep?: () => void;
  onSwitchToBeamEditor?: () => void;
}

export const InfluenceLinePanel: React.FC<InfluenceLinePanelProps> = ({
  model,
  units,
  onOpenStepByStep,
  onSwitchToBeamEditor,
}) => {
  const [showTutorial, setShowTutorial] = useState<boolean>(false);
  const [quantity, setQuantity] = useState<InfluenceQuantity>('M');
  const [supportIdx, setSupportIdx] = useState<number>(0);
  const [sectionX, setSectionX] = useState<number>(model.L / 2);
  const [hoverX, setHoverX] = useState<number | null>(null);

  // Interactive Live Moving Test Load in the Editor
  const [testLoadType, setTestLoadType] = useState<'point' | 'udl'>('point');
  const [testLoadP, setTestLoadP] = useState<number>(100); // kN
  const [testLoadW, setTestLoadW] = useState<number>(20); // kN/m
  const [testLoadX, setTestLoadX] = useState<number>(model.L / 2); // m
  const [showMullerMechanism, setShowMullerMechanism] = useState<boolean>(true);

  const realSupports = useMemo(
    () => model.sup.filter((s) => s.t !== 'hinge'),
    [model.sup]
  );

  // Compute Influence Line Points
  const { ilPoints, error } = useMemo(() => {
    try {
      if (realSupports.length === 0) {
        return { ilPoints: [], error: 'Add at least one support to generate influence lines.' };
      }
      const safeSupIdx = Math.max(0, Math.min(realSupports.length - 1, supportIdx));
      const safeSectionX = Math.max(0, Math.min(model.L, sectionX));
      const pts = calculateInfluenceLine(model, quantity, safeSectionX, safeSupIdx);
      return { ilPoints: pts, error: null };
    } catch (err: unknown) {
      return {
        ilPoints: [],
        error: err instanceof Error ? err.message : 'Error calculating influence line.',
      };
    }
  }, [model, quantity, sectionX, supportIdx, realSupports]);

  // Peak positive and negative ordinates
  const peakPos = useMemo(() => {
    if (!ilPoints || ilPoints.length === 0) return { x: 0, v: 0 };
    return ilPoints.reduce((m, c) => (c.v > m.v ? c : m), ilPoints[0]);
  }, [ilPoints]);

  const peakNeg = useMemo(() => {
    if (!ilPoints || ilPoints.length === 0) return { x: 0, v: 0 };
    return ilPoints.reduce((m, c) => (c.v < m.v ? c : m), ilPoints[0]);
  }, [ilPoints]);

  // Integrate areas under the ILD curve (Positive, Negative, Total)
  const areas = useMemo(() => {
    if (!ilPoints || ilPoints.length < 2) return { pos: 0, neg: 0, total: 0 };
    let pos = 0;
    let neg = 0;
    for (let i = 0; i < ilPoints.length - 1; i++) {
      const p1 = ilPoints[i];
      const p2 = ilPoints[i + 1];
      const dx = p2.x - p1.x;
      if (dx <= 0) continue;
      const avg = (p1.v + p2.v) / 2;
      if (avg >= 0) pos += avg * dx;
      else neg += avg * dx;
    }
    return { pos, neg, total: pos + neg };
  }, [ilPoints]);

  // Current evaluated ordinate at test load location
  const currentTestOrdinate = useMemo(() => {
    if (!ilPoints || ilPoints.length === 0) return 0;
    return interpolateEta(ilPoints, testLoadX);
  }, [ilPoints, testLoadX]);

  // Live computed response induced by current test load
  const liveInducedEffect = useMemo(() => {
    if (testLoadType === 'point') {
      return testLoadP * currentTestOrdinate;
    } else {
      // For UDL placed over entire positive or current span
      return testLoadW * areas.pos;
    }
  }, [testLoadType, testLoadP, testLoadW, currentTestOrdinate, areas.pos]);

  // Unit keys
  const isMomentQuantity = quantity === 'M' || quantity === 'MR';
  const unitKey = isMomentQuantity ? 'L' : 'F';
  const quantityName =
    quantity === 'R'
      ? `Vertical Support Reaction Ry at Support #${supportIdx + 1}`
      : quantity === 'MR'
      ? `Moment Reaction MR at Support #${supportIdx + 1}`
      : quantity === 'M'
      ? `Bending Moment M at Section x = ${formatNum(sectionX * getFactor(units, 'L'), 2)} ${getUnitLabel(units, 'L')}`
      : quantity === 'VL'
      ? `Shear Force Just Left of Section (V-) at x = ${formatNum(sectionX * getFactor(units, 'L'), 2)} ${getUnitLabel(units, 'L')}`
      : quantity === 'VR'
      ? `Shear Force Just Right of Section (V+) at x = ${formatNum(sectionX * getFactor(units, 'L'), 2)} ${getUnitLabel(units, 'L')}`
      : `Shear Force V at Section x = ${formatNum(sectionX * getFactor(units, 'L'), 2)} ${getUnitLabel(units, 'L')}`;

  const quantityUnit = isMomentQuantity
    ? `${getUnitLabel(units, 'M')}`
    : `${getUnitLabel(units, 'F')}`;

  return (
    <div className="space-y-5">
      {/* Top Interactive Editor Controls Card */}
      <div className="p-4 sm:p-5 rounded-2xl border border-slate-800 bg-slate-900/90 shadow-xl space-y-4">
        <div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-800 pb-3">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-xl bg-purple-600/20 text-purple-400 border border-purple-500/30 flex items-center justify-center">
              <Sparkles className="w-4 h-4" />
            </div>
            <div>
              <h3 className="text-sm font-bold text-white flex items-center gap-2">
                <span>Interactive Influence Line (ILD) Editor &amp; Load Simulator</span>
                <span className="text-[10px] bg-purple-500/20 text-purple-300 font-mono px-2 py-0.5 rounded border border-purple-500/30">
                  Unit Moving Load Response
                </span>
              </h3>
              <div className="flex flex-wrap items-center gap-2 mt-1">
                <span className="text-xs text-slate-400">
                  Calculated for your current constructed beam:
                </span>
                <span className="text-[11px] font-mono px-2 py-0.5 rounded bg-slate-800 border border-slate-700 text-sky-300">
                  L = {formatNum(model.L * getFactor(units, 'L'), 2)} {getUnitLabel(units, 'L')} ·{' '}
                  {realSupports.length} Supports · {model.lds.length} Loads
                </span>
                <span className="text-[10px] font-mono px-1.5 py-0.5 rounded bg-emerald-950/60 border border-emerald-800 text-emerald-300">
                  ✓ Auto-Saved
                </span>
                {onSwitchToBeamEditor && (
                  <button
                    type="button"
                    onClick={onSwitchToBeamEditor}
                    className="text-[11px] text-blue-400 hover:text-blue-300 underline font-medium cursor-pointer"
                  >
                    Modify Beam Structure ↗
                  </button>
                )}
              </div>
            </div>
          </div>

          <button
            onClick={() => setShowTutorial(true)}
            className="px-3 py-1.5 rounded-xl bg-fuchsia-600 hover:bg-fuchsia-500 text-xs text-white font-medium flex items-center gap-1.5 transition-colors shadow-sm cursor-pointer"
          >
            <BookOpen className="w-3.5 h-3.5" />
            <span>Influence Line Tutorial</span>
          </button>
        </div>

        {/* Primary Controls Grid */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {/* 1. Target Response Quantity */}
          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1.5 flex items-center gap-1.5">
              <span>Target Structural Action</span>
            </label>
            <select
              value={quantity}
              onChange={(e) => setQuantity(e.target.value as InfluenceQuantity)}
              className="w-full bg-slate-950 border border-slate-700 hover:border-slate-600 rounded-xl px-3 py-2 text-xs text-slate-100 font-medium focus:border-purple-500 focus:outline-none"
            >
              <option value="M">Bending Moment M at Section</option>
              <option value="V">Shear Force V at Section</option>
              <option value="VL">Shear Force Just Left of Section (V−)</option>
              <option value="VR">Shear Force Just Right of Section (V+)</option>
              <option value="R">Support Vertical Reaction Ry</option>
              <option value="MR">Support Moment Reaction MR (Fixed)</option>
            </select>
          </div>

          {/* 2. Section Cut or Support Selector */}
          {quantity === 'R' || quantity === 'MR' ? (
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1.5">
                Target Support
              </label>
              <select
                value={supportIdx}
                onChange={(e) => setSupportIdx(parseInt(e.target.value) || 0)}
                className="w-full bg-slate-950 border border-slate-700 hover:border-slate-600 rounded-xl px-3 py-2 text-xs text-slate-100 font-medium focus:border-purple-500 focus:outline-none"
              >
                {realSupports.map((s, idx) => (
                  <option key={s.id} value={idx}>
                    Support #{idx + 1}: {s.t} at x = {formatNum(s.x * getFactor(units, 'L'), 2)}{' '}
                    {getUnitLabel(units, 'L')}
                  </option>
                ))}
              </select>
            </div>
          ) : (
            <div>
              <div className="flex items-center justify-between mb-1.5">
                <label className="text-xs font-semibold text-slate-300">
                  Section Cut x_c: <span className="text-purple-400 font-mono">{formatNum(sectionX * getFactor(units, 'L'), 2)} {getUnitLabel(units, 'L')}</span>
                </label>
                <span className="text-[10px] text-slate-500 font-mono">({((sectionX / model.L) * 100).toFixed(0)}% span)</span>
              </div>
              <input
                type="range"
                min="0.05"
                max={model.L - 0.05}
                step="0.05"
                value={sectionX}
                onChange={(e) => setSectionX(parseFloat(e.target.value) || model.L / 2)}
                className="w-full accent-purple-500 cursor-pointer"
              />
              {/* Quick section buttons */}
              <div className="flex items-center gap-1.5 mt-1 text-[10px] font-mono">
                <button
                  onClick={() => setSectionX(model.L * 0.25)}
                  className="px-1.5 py-0.5 rounded bg-slate-800 hover:bg-slate-700 text-slate-300"
                >
                  0.25L
                </button>
                <button
                  onClick={() => setSectionX(model.L * 0.333)}
                  className="px-1.5 py-0.5 rounded bg-slate-800 hover:bg-slate-700 text-slate-300"
                >
                  0.33L
                </button>
                <button
                  onClick={() => setSectionX(model.L * 0.5)}
                  className="px-1.5 py-0.5 rounded bg-purple-600/30 text-purple-300 border border-purple-500/30 font-bold"
                >
                  0.50L (Mid)
                </button>
                <button
                  onClick={() => setSectionX(model.L * 0.667)}
                  className="px-1.5 py-0.5 rounded bg-slate-800 hover:bg-slate-700 text-slate-300"
                >
                  0.67L
                </button>
                <button
                  onClick={() => setSectionX(model.L * 0.75)}
                  className="px-1.5 py-0.5 rounded bg-slate-800 hover:bg-slate-700 text-slate-300"
                >
                  0.75L
                </button>
              </div>
            </div>
          )}

          {/* 3. Müller-Breslau Kinematic Release Mechanism Toggle */}
          <div className="flex flex-col justify-center space-y-1">
            <label className="flex items-center gap-2 cursor-pointer text-xs font-semibold text-slate-300 hover:text-white">
              <input
                type="checkbox"
                checked={showMullerMechanism}
                onChange={(e) => setShowMullerMechanism(e.target.checked)}
                className="rounded border-slate-700 text-purple-600 focus:ring-0"
              />
              <span>Show Müller-Breslau Mechanism</span>
            </label>
            <p className="text-[11px] text-slate-400 leading-snug">
              Displays the virtual released restraint and unit virtual displacement mechanism along the beam axis.
            </p>
          </div>
        </div>

        {/* Interactive Live Moving Load Placement Toolbar */}
        <div className="p-3.5 rounded-xl bg-slate-950/80 border border-slate-800/90 space-y-3">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="flex items-center gap-2">
              <Truck className="w-4 h-4 text-amber-400" />
              <span className="text-xs font-bold text-white uppercase tracking-wider">
                Live Moving Load Evaluator
              </span>
            </div>

            {/* Quick Max Optimization Buttons */}
            <div className="flex items-center gap-2 text-xs">
              <button
                onClick={() => setTestLoadX(peakPos.x)}
                className="px-2.5 py-1 rounded-lg bg-emerald-600/20 hover:bg-emerald-600/30 text-emerald-300 border border-emerald-500/30 font-medium flex items-center gap-1 transition-colors"
                title="Place load at maximum positive ordinate"
              >
                <Target className="w-3.5 h-3.5" />
                <span>Place at Max Positive Peak</span>
              </button>

              {peakNeg.v < -1e-4 && (
                <button
                  onClick={() => setTestLoadX(peakNeg.x)}
                  className="px-2.5 py-1 rounded-lg bg-rose-600/20 hover:bg-rose-600/30 text-rose-300 border border-rose-500/30 font-medium flex items-center gap-1 transition-colors"
                  title="Place load at maximum negative ordinate"
                >
                  <Target className="w-3.5 h-3.5" />
                  <span>Place at Max Negative Peak</span>
                </button>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 text-xs">
            {/* Load Position Slider */}
            <div>
              <div className="flex items-center justify-between mb-1">
                <span className="text-slate-400">Moving Load Position x_P:</span>
                <span className="font-mono text-amber-400 font-bold">
                  {formatNum(testLoadX * getFactor(units, 'L'), 2)} {getUnitLabel(units, 'L')}
                </span>
              </div>
              <input
                type="range"
                min="0"
                max={model.L}
                step="0.05"
                value={testLoadX}
                onChange={(e) => setTestLoadX(parseFloat(e.target.value) || 0)}
                className="w-full accent-amber-500 cursor-pointer"
              />
            </div>

            {/* Load Magnitude */}
            <div>
              <span className="text-slate-400 block mb-1">Concentrated Load P:</span>
              <div className="flex items-center gap-2">
                <input
                  type="number"
                  step="10"
                  value={testLoadP}
                  onChange={(e) => setTestLoadP(parseFloat(e.target.value) || 0)}
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-2.5 py-1 text-slate-100 font-mono text-xs focus:border-amber-500 focus:outline-none"
                />
                <span className="text-slate-400 font-mono">{getUnitLabel(units, 'F')}</span>
              </div>
            </div>

            {/* Real-time Response Readout */}
            <div className="p-2.5 rounded-lg bg-slate-900 border border-slate-800 flex flex-col justify-center">
              <span className="text-[10px] text-slate-500 block">Induced Effect for P={testLoadP}{getUnitLabel(units, 'F')}:</span>
              <span className={`text-sm font-bold font-mono ${liveInducedEffect >= 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                {liveInducedEffect >= 0 ? '+' : ''}
                {formatNum(liveInducedEffect * getFactor(units, unitKey), 2)} {quantityUnit}
              </span>
              <span className="text-[10px] text-slate-400 font-mono">
                ILD Ordinate: η = {currentTestOrdinate.toFixed(3)}
              </span>
            </div>
          </div>
        </div>
      </div>

      {error ? (
        <div className="p-4 rounded-xl border border-rose-800 bg-rose-950/40 text-rose-300 text-xs">
          ⚠ {error}
        </div>
      ) : (
        <>
          {/* KPI Stat Cards */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            <div className="p-3 rounded-xl border border-slate-800 bg-slate-900/60 font-mono">
              <span className="text-[10px] text-slate-400 block mb-0.5">Max Positive Ordinate</span>
              <span className="text-base font-bold text-emerald-400">
                +{formatNum(peakPos.v, 3)}
              </span>
              <span className="text-[10px] text-slate-500 block mt-0.5">
                at x = {formatNum(peakPos.x * getFactor(units, 'L'), 2)} {getUnitLabel(units, 'L')}
              </span>
            </div>

            <div className="p-3 rounded-xl border border-slate-800 bg-slate-900/60 font-mono">
              <span className="text-[10px] text-slate-400 block mb-0.5">Max Negative Ordinate</span>
              <span className="text-base font-bold text-rose-400">
                {formatNum(peakNeg.v, 3)}
              </span>
              <span className="text-[10px] text-slate-500 block mt-0.5">
                at x = {formatNum(peakNeg.x * getFactor(units, 'L'), 2)} {getUnitLabel(units, 'L')}
              </span>
            </div>

            <div className="p-3 rounded-xl border border-slate-800 bg-slate-900/60 font-mono">
              <span className="text-[10px] text-slate-400 block mb-0.5">Positive Area (A+)</span>
              <span className="text-base font-bold text-purple-400">
                +{formatNum(areas.pos, 2)} m
              </span>
              <span className="text-[10px] text-slate-500 block mt-0.5">
                Max UDL Effect: {(testLoadW * areas.pos).toFixed(1)} {quantityUnit}
              </span>
            </div>

            <div className="p-3 rounded-xl border border-slate-800 bg-slate-900/60 font-mono">
              <span className="text-[10px] text-slate-400 block mb-0.5">Negative Area (A-)</span>
              <span className="text-base font-bold text-pink-400">
                {formatNum(areas.neg, 2)} m
              </span>
              <span className="text-[10px] text-slate-500 block mt-0.5">
                Min UDL Effect: {(testLoadW * areas.neg).toFixed(1)} {quantityUnit}
              </span>
            </div>
          </div>

          {/* Interactive Influence Line Canvas */}
          <div className="space-y-2">
            <div className="flex items-center justify-between text-xs text-slate-400 px-1">
              <span className="font-semibold text-slate-300">{quantityName}</span>
              <span className="font-mono text-[11px]">Hover over diagram to inspect exact ordinate</span>
            </div>

            <DiagramCanvas
              title={`Influence Line Diagram (ILD)`}
              subtitle={quantityName}
              data={ilPoints.map((p) => ({ x: p.x, val: p.v }))}
              beamLength={model.L}
              units={units}
              unitKey={unitKey}
              colorPositive="#a855f7"
              colorNegative="#ec4899"
              hoverX={hoverX}
              onHoverX={setHoverX}
              height={230}
            />
          </div>
        </>
      )}

      {/* Influence Line Construction Tutorial Modal */}
      <InfluenceLineTutorialModal
        isOpen={showTutorial}
        onClose={() => setShowTutorial(false)}
      />
    </div>
  );
};
