import React, { useState, useMemo, useEffect } from 'react';
import { BeamModel, UnitSystem, AnalysisResult } from './types';
import { PRESETS } from './utils/sections';
import { solveBeam } from './utils/solver';
import { getFactor, getUnitLabel, formatNum } from './utils/units';

// Components
import { Header } from './components/Header';
import { BeamCanvas } from './components/BeamCanvas';
import { FreeBodyCanvas } from './components/FreeBodyCanvas';
import { DiagramCanvas } from './components/DiagramCanvas';
import { ModelEditor } from './components/ModelEditor';
import { InfluenceLinePanel } from './components/InfluenceLinePanel';
import { MovingLoadSimulator } from './components/MovingLoadSimulator';
import { ReportView } from './components/ReportView';
import { SolutionPreviewView } from './components/SolutionPreviewView';
import { TrussStudio } from './components/TrussStudio';
import { FrameStudio } from './components/FrameStudio';

// Modals
import { StepByStepModal } from './components/StepByStepModal';
import { DeveloperModal } from './components/DeveloperModal';
import { SectionCalculatorModal } from './components/SectionCalculatorModal';
import { ExportModal } from './components/ExportModal';
import { ProjectModal } from './components/ProjectModal';
import {
  getAutoSavedModel,
  saveAutoSaveToDB,
  clearAutoSave,
} from './utils/indexedDB';

import {
  AlertTriangle,
  Eye,
  SlidersHorizontal,
  Maximize2,
  CheckCircle,
  Save,
  RotateCcw,
} from 'lucide-react';

export default function App() {
  const [structuralMode, setStructuralMode] = useState<'beam' | 'truss' | 'frame'>(() => {
    const s = getAutoSavedModel();
    if (s?.meta?.structuralMode === 'truss' || s?.meta?.structuralMode === 'frame') {
      return s.meta.structuralMode;
    }
    return 'beam';
  });

  const [model, setModel] = useState<BeamModel>(() => {
    const s = getAutoSavedModel();
    return s?.model ? s.model : PRESETS[0].model;
  });

  const [activePresetName, setActivePresetName] = useState<string>(() => {
    const s = getAutoSavedModel();
    return s?.meta?.presetName || PRESETS[0].name;
  });

  const [units, setUnits] = useState<UnitSystem>(() => {
    const s = getAutoSavedModel();
    if (
      s?.meta?.units &&
      (s.meta.units === 'si' || s.meta.units === 'sn' || s.meta.units === 'us')
    ) {
      return s.meta.units as UnitSystem;
    }
    return 'si';
  });

  const [hoverX, setHoverX] = useState<number | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [activeView, setActiveView] = useState<'analysis' | 'solution' | 'influence' | 'vehicle' | 'report'>(() => {
    const s = getAutoSavedModel();
    if (
      s?.meta?.activeView &&
      ['analysis', 'solution', 'influence', 'vehicle', 'report'].includes(s.meta.activeView)
    ) {
      return s.meta.activeView as 'analysis' | 'solution' | 'influence' | 'vehicle' | 'report';
    }
    return 'analysis';
  });

  // Auto-save feedback state
  const [isSaving, setIsSaving] = useState<boolean>(false);
  const [lastSavedTime, setLastSavedTime] = useState<string | null>(() => {
    const s = getAutoSavedModel();
    if (s?.meta?.timestamp) {
      return new Date(s.meta.timestamp).toLocaleTimeString([], {
        hour: '2-digit',
        minute: '2-digit',
      });
    }
    return null;
  });

  // Display toggles
  const [showFBD, setShowFBD] = useState<boolean>(true);
  const [showDeflectionGhost, setShowDeflectionGhost] = useState<boolean>(true);

  // Modals state
  const [showStepByStep, setShowStepByStep] = useState<boolean>(false);
  const [showDeveloper, setShowDeveloper] = useState<boolean>(false);
  const [showSectionCalc, setShowSectionCalc] = useState<boolean>(false);
  const [showExport, setShowExport] = useState<boolean>(false);
  const [showProjects, setShowProjects] = useState<boolean>(false);

  // Solve beam direct stiffness FEM
  const { result, error } = useMemo(() => {
    try {
      const res = solveBeam(model);
      return { result: res, error: null };
    } catch (err: unknown) {
      return {
        result: null,
        error: err instanceof Error ? err.message : 'Unknown structural analysis error.',
      };
    }
  }, [model]);

  // Load preset problem
  const handleSelectPreset = (presetId: string) => {
    const p = PRESETS.find((item) => item.id === presetId);
    if (p) {
      setModel(JSON.parse(JSON.stringify(p.model)));
      setSelectedId(null);
      setActivePresetName(p.name);
    }
  };

  // Auto-save model whenever it changes (persisting to localStorage & IndexedDB)
  useEffect(() => {
    setIsSaving(true);
    const timer = setTimeout(() => {
      saveAutoSaveToDB(model, {
        presetName: activePresetName,
        units,
        activeView,
        structuralMode,
      });
      const nowStr = new Date().toLocaleTimeString([], {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
      });
      setLastSavedTime(nowStr);
      setIsSaving(false);
    }, 250);

    return () => clearTimeout(timer);
  }, [model, activePresetName, units, activeView, structuralMode]);

  const handleResetToPreset = () => {
    if (
      window.confirm?.(
        'Reset beam to standard simply supported preset? Your current edits will be cleared.'
      ) ??
      true
    ) {
      clearAutoSave();
      const def = PRESETS[0];
      setModel(JSON.parse(JSON.stringify(def.model)));
      setActivePresetName(def.name);
      setSelectedId(null);
    }
  };

  // Drag updates for supports
  const handleUpdateSupport = (id: string, newX: number) => {
    setModel((prev) => ({
      ...prev,
      sup: prev.sup.map((s) => (s.id === id ? { ...s, x: newX } : s)),
    }));
  };

  // Drag updates for loads (point load position or general)
  const handleUpdateLoad = (id: string, newX: number) => {
    setModel((prev) => ({
      ...prev,
      lds: prev.lds.map((l) => (l.id === id ? { ...l, x1: newX } : l)),
    }));
  };

  // Drag updates for distributed load spans (x1 and x2)
  const handleUpdateLoadSpan = (id: string, newX1: number, newX2: number) => {
    setModel((prev) => ({
      ...prev,
      lds: prev.lds.map((l) => (l.id === id ? { ...l, x1: newX1, x2: newX2 } : l)),
    }));
  };

  // Synchronized values at hoverX for crosshair HUD
  const hoverValues = useMemo(() => {
    if (!result || hoverX === null || hoverX < 0 || hoverX > model.L) return null;

    let idx = 1;
    while (idx < result.pts.length - 1 && result.pts[idx].x < hoverX - 1e-9) idx++;
    const pA = result.pts[idx - 1] || result.pts[0];
    const pB = result.pts[idx] || result.pts[result.pts.length - 1];

    if (!pA || !pB) return null;

    const t = Math.abs(pB.x - pA.x) < 1e-9 ? 0 : (hoverX - pA.x) / (pB.x - pA.x);
    const V = pA.V + t * (pB.V - pA.V);
    const M = pA.M + t * (pB.M - pA.M);
    const y = pA.y + t * (pB.y - pA.y);
    const N = (pA.N || 0) + t * ((pB.N || 0) - (pA.N || 0));

    // Elastic stress at x: sigma = |M| / Z
    const sigma = model.Z > 0 ? (Math.abs(M) * 1000) / model.Z : 0;

    return { V, M, y, N, sigma };
  }, [result, hoverX, model.L, model.Z]);

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col font-sans selection:bg-blue-600 selection:text-white">
      {/* Top Header */}
      <Header
        units={units}
        onChangeUnits={setUnits}
        onSelectPreset={handleSelectPreset}
        onOpenStepByStep={() => setShowStepByStep(true)}
        onOpenDeveloper={() => setShowDeveloper(true)}
        onOpenExport={() => setShowExport(true)}
        onOpenProjects={() => setShowProjects(true)}
        activeView={activeView}
        onChangeView={setActiveView}
        structuralMode={structuralMode}
        onChangeStructuralMode={setStructuralMode}
      />

      {/* Main App Container */}
      <main className="flex-1 max-w-7xl w-full mx-auto p-4 sm:p-6 space-y-5">
        {/* TRUSS SOLVER MODE */}
        {structuralMode === 'truss' && (
          <TrussStudio units={units} />
        )}

        {/* 2D PLANE FRAME SOLVER MODE */}
        {structuralMode === 'frame' && (
          <FrameStudio units={units} />
        )}

        {/* BEAM SOLVER MODE */}
        {structuralMode === 'beam' && (
          <>
            {/* Error notification banner if any */}
            {error && (
              <div className="p-4 rounded-xl border border-rose-800/80 bg-rose-950/40 text-rose-300 text-xs flex items-center gap-3 shadow-lg shadow-rose-950/20">
                <AlertTriangle className="w-5 h-5 flex-shrink-0 text-rose-400" />
                <div>
                  <span className="font-semibold block">Structural Instability or Model Error:</span>
                  <span>{error}</span>
                </div>
              </div>
            )}


        {/* VIEW 1: Structural Analysis & Diagrams */}
        {activeView === 'analysis' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
            {/* Left 8 Cols: Interactive Canvases & Diagrams */}
            <div className="lg:col-span-8 space-y-5">
              {/* Beam Canvas Toolbar */}
              <div className="flex flex-wrap items-center justify-between gap-2">
                <div className="flex items-center gap-2.5">
                  <span className="text-xs font-semibold uppercase tracking-wider text-slate-300">
                    Interactive Structural Beam Canvas
                  </span>
                  {/* Auto-save status badge */}
                  <div
                    className="flex items-center gap-1.5 px-2.5 py-0.5 rounded-full bg-slate-900/90 border border-slate-800 text-[11px] text-slate-400 font-mono shadow-sm"
                    title="Auto-saves automatically to browser localStorage and IndexedDB"
                  >
                    <span
                      className={`w-1.5 h-1.5 rounded-full transition-colors ${
                        isSaving
                          ? 'bg-amber-400 animate-pulse'
                          : 'bg-emerald-400 shadow-sm shadow-emerald-400/50'
                      }`}
                    />
                    <span>
                      {isSaving
                        ? 'Auto-saving...'
                        : lastSavedTime
                        ? `Auto-saved ${lastSavedTime}`
                        : 'Auto-saved'}
                    </span>
                  </div>
                </div>

                <div className="flex items-center gap-3 text-xs text-slate-400">
                  <button
                    type="button"
                    onClick={handleResetToPreset}
                    className="text-[11px] text-slate-500 hover:text-rose-400 flex items-center gap-1 transition-colors"
                    title="Reset to default simply supported beam"
                  >
                    <RotateCcw className="w-3 h-3" />
                    <span>Reset Preset</span>
                  </button>

                  <label className="flex items-center gap-1.5 cursor-pointer hover:text-slate-200">
                    <input
                      type="checkbox"
                      checked={showDeflectionGhost}
                      onChange={(e) => setShowDeflectionGhost(e.target.checked)}
                      className="rounded border-slate-700 text-blue-600 focus:ring-0"
                    />
                    <span>Deflected Ghost Shape</span>
                  </label>

                  <label className="flex items-center gap-1.5 cursor-pointer hover:text-slate-200">
                    <input
                      type="checkbox"
                      checked={showFBD}
                      onChange={(e) => setShowFBD(e.target.checked)}
                      className="rounded border-slate-700 text-blue-600 focus:ring-0"
                    />
                    <span>Show Free Body Diagram (FBD)</span>
                  </label>
                </div>
              </div>

              {/* Main Interactive Beam Canvas */}
              <BeamCanvas
                model={model}
                result={result}
                units={units}
                hoverX={hoverX}
                onHoverX={setHoverX}
                onUpdateSupport={handleUpdateSupport}
                onUpdateLoad={handleUpdateLoad}
                onUpdateLoadSpan={handleUpdateLoadSpan}
                selectedId={selectedId}
                onSelectId={setSelectedId}
                showDeflectionOverlay={showDeflectionGhost}
              />

              {/* Free Body Diagram (FBD) */}
              {showFBD && (
                <FreeBodyCanvas
                  model={model}
                  result={result}
                  units={units}
                />
              )}

              {/* KPI Stat Badges */}
              {result && (
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                  <div className="p-3 rounded-xl border border-slate-800 bg-slate-900/60 font-mono">
                    <span className="text-[10px] text-slate-400 block mb-0.5">Max |Shear|</span>
                    <span className="text-base font-bold text-blue-400">
                      {formatNum(Math.abs(result.Vm.V) * getFactor(units, 'F'), 2)}{' '}
                      {getUnitLabel(units, 'F')}
                    </span>
                    <span className="text-[10px] text-slate-500 block mt-0.5">
                      at x = {formatNum(result.Vm.x * getFactor(units, 'L'), 2)}{' '}
                      {getUnitLabel(units, 'L')}
                    </span>
                  </div>

                  <div className="p-3 rounded-xl border border-slate-800 bg-slate-900/60 font-mono">
                    <span className="text-[10px] text-slate-400 block mb-0.5">Max Sagging M+</span>
                    <span className="text-base font-bold text-emerald-400">
                      +{formatNum(Math.max(0, result.Mp.M) * getFactor(units, 'M'), 2)}{' '}
                      {getUnitLabel(units, 'M')}
                    </span>
                    <span className="text-[10px] text-slate-500 block mt-0.5">
                      at x = {formatNum(result.Mp.x * getFactor(units, 'L'), 2)}{' '}
                      {getUnitLabel(units, 'L')}
                    </span>
                  </div>

                  <div className="p-3 rounded-xl border border-slate-800 bg-slate-900/60 font-mono">
                    <span className="text-[10px] text-slate-400 block mb-0.5">Max Hogging M-</span>
                    <span className="text-base font-bold text-rose-400">
                      {formatNum(Math.min(0, result.Mn.M) * getFactor(units, 'M'), 2)}{' '}
                      {getUnitLabel(units, 'M')}
                    </span>
                    <span className="text-[10px] text-slate-500 block mt-0.5">
                      at x = {formatNum(result.Mn.x * getFactor(units, 'L'), 2)}{' '}
                      {getUnitLabel(units, 'L')}
                    </span>
                  </div>

                  <div className="p-3 rounded-xl border border-slate-800 bg-slate-900/60 font-mono">
                    <span className="text-[10px] text-slate-400 block mb-0.5">Max Deflection</span>
                    <span className="text-base font-bold text-purple-400">
                      {formatNum(Math.abs(result.Ym.y) * getFactor(units, 'D'), 2)}{' '}
                      {getUnitLabel(units, 'D')}
                    </span>
                    <span
                      className={`text-[10px] font-bold block mt-0.5 ${
                        Math.abs(result.Ym.y) <= result.allow
                          ? 'text-emerald-400'
                          : 'text-amber-400'
                      }`}
                    >
                      {Math.abs(result.Ym.y) <= result.allow ? 'PASS (<= L/n)' : 'EXCEEDED'}
                    </span>
                  </div>
                </div>
              )}

              {/* Diagrams Stack */}
              {result && (
                <div className="space-y-4">
                  {/* Shear Force Diagram */}
                  <DiagramCanvas
                    title="Shear Force Diagram (SFD) — V(x)"
                    subtitle="Positive shear plotted above datum axis"
                    data={result.pts.map((p) => ({ x: p.x, val: p.V }))}
                    beamLength={model.L}
                    units={units}
                    unitKey="F"
                    colorPositive="#3b82f6"
                    colorNegative="#ec4899"
                    hoverX={hoverX}
                    onHoverX={setHoverX}
                    height={160}
                  />

                  {/* Bending Moment Diagram */}
                  <DiagramCanvas
                    title="Bending Moment Diagram (BMD) — M(x)"
                    subtitle="Positive sagging moment plotted above datum axis"
                    data={result.pts.map((p) => ({ x: p.x, val: p.M }))}
                    beamLength={model.L}
                    units={units}
                    unitKey="M"
                    colorPositive="#10b981"
                    colorNegative="#f43f5e"
                    hoverX={hoverX}
                    onHoverX={setHoverX}
                    height={170}
                  />

                  {/* Deflection Curve */}
                  <DiagramCanvas
                    title="Elastic Deflection Curve — δ(x)"
                    subtitle="Downward deflection below zero axis (-), upward deflection above zero axis (+)"
                    data={result.pts.map((p) => ({ x: p.x, val: p.y }))}
                    beamLength={model.L}
                    units={units}
                    unitKey="D"
                    colorPositive="#a855f7"
                    colorNegative="#6366f1"
                    hoverX={hoverX}
                    onHoverX={setHoverX}
                    height={150}
                    invertSign={false}
                  />

                  {/* Axial Force Diagram (AFD) if inclined loads */}
                  {result.hasN && (
                    <DiagramCanvas
                      title="Axial Force Diagram (AFD) — N(x)"
                      subtitle="Tension positive, caused by inclined lateral force components"
                      data={result.pts.map((p) => ({ x: p.x, val: p.N }))}
                      beamLength={model.L}
                      units={units}
                      unitKey="F"
                      colorPositive="#06b6d4"
                      colorNegative="#eab308"
                      hoverX={hoverX}
                      onHoverX={setHoverX}
                      height={140}
                    />
                  )}
                </div>
              )}
            </div>

            {/* Right 4 Cols: Model Editor Sidebar */}
            <div className="lg:col-span-4">
              <div className="sticky top-20">
                <ModelEditor
                  model={model}
                  units={units}
                  onChangeModel={setModel}
                  onOpenSectionCalc={() => setShowSectionCalc(true)}
                  selectedId={selectedId}
                  onSelectId={setSelectedId}
                />
              </div>
            </div>
          </div>
        )}

        {/* VIEW 2: Complete Step-by-Step Solution Preview */}
        {activeView === 'solution' && result && (
          <SolutionPreviewView
            model={model}
            result={result}
            units={units}
            presetName={activePresetName}
            onClose={() => setActiveView('analysis')}
          />
        )}

        {/* VIEW 3: Influence Lines (ILD) */}
        {activeView === 'influence' && (
          <InfluenceLinePanel
            model={model}
            units={units}
            onOpenStepByStep={() => setShowStepByStep(true)}
            onSwitchToBeamEditor={() => setActiveView('analysis')}
          />
        )}

        {/* VIEW 4: Moving Vehicle Live Load Simulator */}
        {activeView === 'vehicle' && (
          <MovingLoadSimulator
            model={model}
            units={units}
          />
        )}

        {/* VIEW 5: Technical Report */}
        {activeView === 'report' && (
          <ReportView
            model={model}
            result={result}
            units={units}
          />
        )}
          </>
        )}
      </main>

      {/* Footer */}
      <footer className="mt-auto border-t border-slate-900 bg-slate-950/80 py-4 px-6 text-center text-xs text-slate-500 flex flex-wrap items-center justify-between max-w-7xl mx-auto w-full">
        <div>
          <span>BeamLab Pro · Developed with precision by </span>
          <button
            onClick={() => setShowDeveloper(true)}
            className="text-blue-400 hover:text-blue-300 font-semibold underline underline-offset-2"
          >
            Md. Nasir Uddin
          </button>
          <span> (BUET Civil Engineering · RAJUK AAO · 46th &amp; 47th BCS)</span>
        </div>
        <div className="flex items-center gap-3 mt-2 sm:mt-0 font-mono text-[11px]">
          <span>Euler-Bernoulli Direct Stiffness FEM</span>
          <span>•</span>
          <span>Hermite Cubic Interpolation</span>
        </div>
      </footer>

      {/* Modals */}
      {showStepByStep && result && (
        <StepByStepModal
          model={model}
          result={result}
          units={units}
          presetName={activePresetName}
          onClose={() => setShowStepByStep(false)}
        />
      )}

      {showDeveloper && (
        <DeveloperModal onClose={() => setShowDeveloper(false)} />
      )}

      {showSectionCalc && (
        <SectionCalculatorModal
          units={units}
          onApply={(props) => {
            setModel((prev) => ({
              ...prev,
              I: props.I,
              Z: props.Z,
              area: props.area,
            }));
          }}
          onClose={() => setShowSectionCalc(false)}
        />
      )}

      {showExport && (
        <ExportModal
          model={model}
          result={result}
          units={units}
          onClose={() => setShowExport(false)}
        />
      )}

      {showProjects && (
        <ProjectModal
          currentModel={model}
          onLoadModel={(loaded) => setModel(loaded)}
          onClose={() => setShowProjects(false)}
        />
      )}
    </div>
  );
}
