import React, { useState, useMemo } from 'react';
import { UnitSystem } from '../types';
import { formatNum, getUnitLabel } from '../utils/units';
import { X, Check, Box, Circle, Columns } from 'lucide-react';

interface SectionCalculatorModalProps {
  units: UnitSystem;
  onApply: (props: { I: number; Z: number; area: number }) => void;
  onClose: () => void;
}

type ShapeType = 'rect' | 'ibeam' | 'box' | 'circle' | 'pipe' | 'tbeam';

export const SectionCalculatorModal: React.FC<SectionCalculatorModalProps> = ({
  units,
  onApply,
  onClose,
}) => {
  const [shape, setShape] = useState<ShapeType>('ibeam');

  // Rectangular: width b, height h (mm)
  const [rectB, setRectB] = useState<number>(200);
  const [rectH, setRectH] = useState<number>(400);

  // I-Beam: h, b_f, t_f, t_w (mm)
  const [iH, setIH] = useState<number>(300);
  const [iB, setIB] = useState<number>(150);
  const [iTf, setITf] = useState<number>(10.7);
  const [iTw, setITw] = useState<number>(7.1);

  // Box: h, b, t (mm)
  const [boxH, setBoxH] = useState<number>(200);
  const [boxB, setBoxB] = useState<number>(100);
  const [boxT, setBoxT] = useState<number>(8);

  // Circle: d (mm)
  const [circD, setCircD] = useState<number>(150);

  // Pipe: D, t (mm)
  const [pipeD, setPipeD] = useState<number>(219.1);
  const [pipeT, setPipeT] = useState<number>(8);

  // Compute Properties in base SI (output cm^4 for I, cm^3 for Z, cm^2 for A)
  const properties = useMemo(() => {
    let A_mm2 = 0;
    let Ix_mm4 = 0;
    let Zx_mm3 = 0;

    if (shape === 'rect') {
      A_mm2 = rectB * rectH;
      Ix_mm4 = (rectB * Math.pow(rectH, 3)) / 12;
      Zx_mm3 = (rectB * Math.pow(rectH, 2)) / 6;
    } else if (shape === 'ibeam') {
      const hw = iH - 2 * iTf;
      // Outer rect minus two voids
      const outerI = (iB * Math.pow(iH, 3)) / 12;
      const innerI = ((iB - iTw) * Math.pow(hw, 3)) / 12;
      Ix_mm4 = outerI - innerI;
      A_mm2 = 2 * iB * iTf + hw * iTw;
      Zx_mm3 = Ix_mm4 / (iH / 2);
    } else if (shape === 'box') {
      const hi = boxH - 2 * boxT;
      const bi = boxB - 2 * boxT;
      Ix_mm4 = (boxB * Math.pow(boxH, 3) - bi * Math.pow(hi, 3)) / 12;
      A_mm2 = boxB * boxH - bi * hi;
      Zx_mm3 = Ix_mm4 / (boxH / 2);
    } else if (shape === 'circle') {
      const r = circD / 2;
      A_mm2 = Math.PI * r * r;
      Ix_mm4 = (Math.PI * Math.pow(circD, 4)) / 64;
      Zx_mm3 = (Math.PI * Math.pow(circD, 3)) / 32;
    } else if (shape === 'pipe') {
      const r_out = pipeD / 2;
      const r_in = r_out - pipeT;
      A_mm2 = Math.PI * (r_out * r_out - r_in * r_in);
      Ix_mm4 = (Math.PI * (Math.pow(pipeD, 4) - Math.pow(pipeD - 2 * pipeT, 4))) / 64;
      Zx_mm3 = Ix_mm4 / r_out;
    }

    // Convert mm^4 to cm^4: 1 cm^4 = 10,000 mm^4 -> / 1e4
    // Convert mm^3 to cm^3: 1 cm^3 = 1,000 mm^3 -> / 1e3
    // Convert mm^2 to cm^2: 1 cm^2 = 100 mm^2 -> / 100
    const I_cm4 = Math.max(1, Ix_mm4 / 10000);
    const Z_cm3 = Math.max(0.1, Zx_mm3 / 1000);
    const A_cm2 = Math.max(0.1, A_mm2 / 100);

    return {
      I: I_cm4,
      Z: Z_cm3,
      area: A_cm2,
      r: Math.sqrt(Ix_mm4 / A_mm2), // mm
    };
  }, [shape, rectB, rectH, iH, iB, iTf, iTw, boxH, boxB, boxT, circD, pipeD, pipeT]);

  const handleApply = () => {
    onApply({
      I: properties.I,
      Z: properties.Z,
      area: properties.area,
    });
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 bg-slate-950/80 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl max-w-2xl w-full flex flex-col shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-200">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-800 bg-slate-950/60">
          <div>
            <h3 className="text-base font-bold text-slate-100 flex items-center gap-2">
              <Columns className="w-5 h-5 text-blue-400" />
              <span>Parametric Cross-Section Geometric Calculator</span>
            </h3>
            <p className="text-xs text-slate-400">
              Calculate exact Moment of Inertia (I), Section Modulus (Z), and Area (A)
            </p>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 text-slate-400 hover:text-white rounded-lg hover:bg-slate-800 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="p-6 space-y-5">
          {/* Shape Selector */}
          <div className="grid grid-cols-5 gap-2">
            {[
              { id: 'ibeam', label: 'I-Beam', icon: Columns },
              { id: 'rect', label: 'Rectangular', icon: Box },
              { id: 'box', label: 'Hollow Box', icon: Box },
              { id: 'pipe', label: 'Pipe Tube', icon: Circle },
              { id: 'circle', label: 'Solid Bar', icon: Circle },
            ].map((s) => (
              <button
                key={s.id}
                onClick={() => setShape(s.id as ShapeType)}
                className={`py-2 px-1 rounded-xl border flex flex-col items-center gap-1.5 text-xs font-medium transition-all ${
                  shape === s.id
                    ? 'bg-blue-600 border-blue-500 text-white shadow-sm'
                    : 'bg-slate-950 border-slate-800 text-slate-400 hover:text-slate-200 hover:border-slate-700'
                }`}
              >
                <s.icon className="w-4 h-4" />
                <span>{s.label}</span>
              </button>
            ))}
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 items-center">
            {/* Input fields */}
            <div className="space-y-3 font-mono text-xs">
              {shape === 'rect' && (
                <>
                  <div>
                    <label className="block text-slate-400 mb-1">Width b (mm)</label>
                    <input
                      type="number"
                      value={rectB}
                      onChange={(e) => setRectB(parseFloat(e.target.value) || 1)}
                      className="w-full bg-slate-950 border border-slate-700 rounded-lg px-3 py-1.5 text-slate-100"
                    />
                  </div>
                  <div>
                    <label className="block text-slate-400 mb-1">Height h (mm)</label>
                    <input
                      type="number"
                      value={rectH}
                      onChange={(e) => setRectH(parseFloat(e.target.value) || 1)}
                      className="w-full bg-slate-950 border border-slate-700 rounded-lg px-3 py-1.5 text-slate-100"
                    />
                  </div>
                </>
              )}

              {shape === 'ibeam' && (
                <>
                  <div className="grid grid-cols-2 gap-2">
                    <div>
                      <label className="block text-slate-400 mb-1">Total Depth h (mm)</label>
                      <input
                        type="number"
                        value={iH}
                        onChange={(e) => setIH(parseFloat(e.target.value) || 1)}
                        className="w-full bg-slate-950 border border-slate-700 rounded px-2 py-1 text-slate-100"
                      />
                    </div>
                    <div>
                      <label className="block text-slate-400 mb-1">Flange Width b (mm)</label>
                      <input
                        type="number"
                        value={iB}
                        onChange={(e) => setIB(parseFloat(e.target.value) || 1)}
                        className="w-full bg-slate-950 border border-slate-700 rounded px-2 py-1 text-slate-100"
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    <div>
                      <label className="block text-slate-400 mb-1">Flange Thk tf (mm)</label>
                      <input
                        type="number"
                        step="0.1"
                        value={iTf}
                        onChange={(e) => setITf(parseFloat(e.target.value) || 1)}
                        className="w-full bg-slate-950 border border-slate-700 rounded px-2 py-1 text-slate-100"
                      />
                    </div>
                    <div>
                      <label className="block text-slate-400 mb-1">Web Thk tw (mm)</label>
                      <input
                        type="number"
                        step="0.1"
                        value={iTw}
                        onChange={(e) => setITw(parseFloat(e.target.value) || 1)}
                        className="w-full bg-slate-950 border border-slate-700 rounded px-2 py-1 text-slate-100"
                      />
                    </div>
                  </div>
                </>
              )}

              {shape === 'box' && (
                <>
                  <div className="grid grid-cols-2 gap-2">
                    <div>
                      <label className="block text-slate-400 mb-1">Outer Depth h (mm)</label>
                      <input
                        type="number"
                        value={boxH}
                        onChange={(e) => setBoxH(parseFloat(e.target.value) || 1)}
                        className="w-full bg-slate-950 border border-slate-700 rounded px-2 py-1 text-slate-100"
                      />
                    </div>
                    <div>
                      <label className="block text-slate-400 mb-1">Outer Width b (mm)</label>
                      <input
                        type="number"
                        value={boxB}
                        onChange={(e) => setBoxB(parseFloat(e.target.value) || 1)}
                        className="w-full bg-slate-950 border border-slate-700 rounded px-2 py-1 text-slate-100"
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-slate-400 mb-1">Wall Thickness t (mm)</label>
                    <input
                      type="number"
                      step="0.5"
                      value={boxT}
                      onChange={(e) => setBoxT(parseFloat(e.target.value) || 1)}
                      className="w-full bg-slate-950 border border-slate-700 rounded px-2 py-1 text-slate-100"
                    />
                  </div>
                </>
              )}

              {shape === 'circle' && (
                <div>
                  <label className="block text-slate-400 mb-1">Diameter d (mm)</label>
                  <input
                    type="number"
                    value={circD}
                    onChange={(e) => setCircD(parseFloat(e.target.value) || 1)}
                    className="w-full bg-slate-950 border border-slate-700 rounded-lg px-3 py-1.5 text-slate-100"
                  />
                </div>
              )}

              {shape === 'pipe' && (
                <>
                  <div>
                    <label className="block text-slate-400 mb-1">Outer Diameter D (mm)</label>
                    <input
                      type="number"
                      step="0.1"
                      value={pipeD}
                      onChange={(e) => setPipeD(parseFloat(e.target.value) || 1)}
                      className="w-full bg-slate-950 border border-slate-700 rounded-lg px-3 py-1.5 text-slate-100"
                    />
                  </div>
                  <div>
                    <label className="block text-slate-400 mb-1">Wall Thickness t (mm)</label>
                    <input
                      type="number"
                      step="0.5"
                      value={pipeT}
                      onChange={(e) => setPipeT(parseFloat(e.target.value) || 1)}
                      className="w-full bg-slate-950 border border-slate-700 rounded-lg px-3 py-1.5 text-slate-100"
                    />
                  </div>
                </>
              )}
            </div>

            {/* Calculated Results Card */}
            <div className="p-4 rounded-xl border border-blue-900/60 bg-blue-950/20 space-y-3 font-mono">
              <span className="text-xs font-semibold text-blue-400 uppercase tracking-wider block">
                Computed Section Properties
              </span>

              <div className="space-y-2 text-xs">
                <div className="flex justify-between border-b border-slate-800/80 pb-1.5">
                  <span className="text-slate-400">Second Moment I_x:</span>
                  <span className="text-blue-300 font-bold">
                    {formatNum(properties.I, 1)} cm⁴
                  </span>
                </div>

                <div className="flex justify-between border-b border-slate-800/80 pb-1.5">
                  <span className="text-slate-400">Elastic Modulus Z_x:</span>
                  <span className="text-blue-300 font-bold">
                    {formatNum(properties.Z, 1)} cm³
                  </span>
                </div>

                <div className="flex justify-between border-b border-slate-800/80 pb-1.5">
                  <span className="text-slate-400">Cross-Section Area A:</span>
                  <span className="text-blue-300 font-bold">
                    {formatNum(properties.area, 1)} cm²
                  </span>
                </div>

                <div className="flex justify-between">
                  <span className="text-slate-400">Radius of Gyration r:</span>
                  <span className="text-slate-200">
                    {formatNum(properties.r, 1)} mm
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-end gap-3 px-6 py-3 border-t border-slate-800 bg-slate-950/60">
          <button
            onClick={onClose}
            className="px-4 py-1.5 rounded-lg text-xs text-slate-400 hover:text-slate-200 hover:bg-slate-800"
          >
            Cancel
          </button>
          <button
            onClick={handleApply}
            className="px-4 py-1.5 rounded-lg bg-blue-600 hover:bg-blue-500 text-xs font-semibold text-white flex items-center gap-1.5 transition-colors"
          >
            <Check className="w-4 h-4" />
            <span>Apply to Current Beam</span>
          </button>
        </div>
      </div>
    </div>
  );
};
