import React, { useState } from 'react';
import { X, BookOpen, Sparkles, ChevronRight, CheckCircle2, ArrowRight, Compass, HelpCircle, Layers, Sliders } from 'lucide-react';

interface InfluenceLineTutorialModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const InfluenceLineTutorialModal: React.FC<InfluenceLineTutorialModalProps> = ({
  isOpen,
  onClose,
}) => {
  const [activeTab, setActiveTab] = useState<'muller' | 'simulator' | 'shear_moment' | 'moving_loads' | 'cheatsheet'>('muller');

  // Interactive Simulator State
  const [simSpan, setSimSpan] = useState<number>(10);
  const [simSection, setSimSection] = useState<number>(4);
  const [simUnitLoadX, setSimUnitLoadX] = useState<number>(4);
  const [simQuantity, setSimQuantity] = useState<'RA' | 'RB' | 'VC' | 'MC'>('MC');

  if (!isOpen) return null;

  // Simulator Geometry & Values
  const L = simSpan;
  const c = Math.min(Math.max(0.5, simSection), L - 0.5);
  const a = c;
  const b = L - c;
  const xP = Math.min(Math.max(0, simUnitLoadX), L);

  // Calculate current ILD value at unit load position xP
  let currentVal = 0;
  let maxPositiveVal = 0;
  let maxNegativeVal = 0;
  let ildFormula = '';
  let mullerAction = '';

  if (simQuantity === 'RA') {
    currentVal = 1 - xP / L;
    maxPositiveVal = 1.0;
    maxNegativeVal = 0.0;
    ildFormula = 'y(x) = (L - x) / L';
    mullerAction = 'Release vertical support at A and displace node A upwards by 1.0 unit. Support B remains fixed at datum.';
  } else if (simQuantity === 'RB') {
    currentVal = xP / L;
    maxPositiveVal = 1.0;
    maxNegativeVal = 0.0;
    ildFormula = 'y(x) = x / L';
    mullerAction = 'Release vertical support at B and displace node B upwards by 1.0 unit. Support A remains fixed at datum.';
  } else if (simQuantity === 'VC') {
    if (xP < c) {
      currentVal = -xP / L;
    } else if (xP > c) {
      currentVal = (L - xP) / L;
    } else {
      // At section cut
      currentVal = (L - xP) / L;
    }
    maxPositiveVal = b / L;
    maxNegativeVal = -a / L;
    ildFormula = `Left of C (x < c): y = -x/L  |  Right of C (x > c): y = (L - x)/L`;
    mullerAction = 'Cut section C, insert frictionless shear slide guide, and translate right side up & left side down by total relative displacement of 1.0.';
  } else if (simQuantity === 'MC') {
    if (xP <= c) {
      currentVal = (b * xP) / L;
    } else {
      currentVal = (a * (L - xP)) / L;
    }
    maxPositiveVal = (a * b) / L;
    maxNegativeVal = 0.0;
    ildFormula = `Left of C: y = (b/L)·x  |  Right of C: y = (a/L)·(L - x)  |  Peak = a·b/L = ${( (a * b) / L ).toFixed(2)}`;
    mullerAction = 'Insert internal hinge at section C and apply unit internal relative rotation (1.0 rad). The two segments lift into a triangle with apex at C.';
  }

  // SVG dimensions for simulator
  const svgW = 760;
  const svgH = 260;
  const padX = 60;
  const availW = svgW - 2 * padX;
  const toX = (x: number) => padX + (x / L) * availW;
  const baseLineY = 160;

  // Build ILD SVG Path for Simulator
  let ildPath = '';
  let releasePath = '';

  if (simQuantity === 'RA') {
    const yA = baseLineY - 90; // +1.0
    const yB = baseLineY; // 0.0
    ildPath = `M ${toX(0)} ${yA} L ${toX(L)} ${yB}`;
    releasePath = `M ${toX(0)} ${yA} L ${toX(L)} ${yB}`;
  } else if (simQuantity === 'RB') {
    const yA = baseLineY; // 0.0
    const yB = baseLineY - 90; // +1.0
    ildPath = `M ${toX(0)} ${yA} L ${toX(L)} ${yB}`;
    releasePath = `M ${toX(0)} ${yA} L ${toX(L)} ${yB}`;
  } else if (simQuantity === 'VC') {
    const yLeftPeak = baseLineY + (a / L) * 90; // -a/L is below axis
    const yRightPeak = baseLineY - (b / L) * 90; // +b/L is above axis
    ildPath = `M ${toX(0)} ${baseLineY} L ${toX(c)} ${yLeftPeak} M ${toX(c)} ${yRightPeak} L ${toX(L)} ${baseLineY}`;
    releasePath = `M ${toX(0)} ${baseLineY} L ${toX(c)} ${yLeftPeak} M ${toX(c)} ${yRightPeak} L ${toX(L)} ${baseLineY}`;
  } else if (simQuantity === 'MC') {
    const peakPx = Math.min(100, Math.max(30, ((a * b) / L) * 16));
    const yPeak = baseLineY - peakPx;
    ildPath = `M ${toX(0)} ${baseLineY} L ${toX(c)} ${yPeak} L ${toX(L)} ${baseLineY}`;
    releasePath = `M ${toX(0)} ${baseLineY} L ${toX(c)} ${yPeak} L ${toX(L)} ${baseLineY}`;
  }

  return (
    <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-3 sm:p-5 overflow-y-auto">
      <div className="bg-slate-900 border border-slate-700/80 rounded-2xl w-full max-w-5xl max-h-[92vh] flex flex-col shadow-2xl overflow-hidden">
        {/* Header */}
        <div className="p-4 sm:p-5 border-b border-slate-800 bg-slate-950 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-purple-600 to-indigo-500 flex items-center justify-center shadow-md">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <div>
              <h2 className="text-lg sm:text-xl font-bold text-white flex items-center gap-2">
                <span>Influence Line Construction Guide &amp; Masterclass</span>
                <span className="text-xs bg-purple-500/20 text-purple-300 font-mono px-2 py-0.5 rounded border border-purple-500/30">
                  Müller-Breslau
                </span>
              </h2>
              <p className="text-xs text-slate-400">
                Learn how to construct Influence Line Diagrams (ILD) easily for Reactions, Shear, and Moment under moving loads
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-xl text-slate-400 hover:text-white hover:bg-slate-800 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Tab Navigation */}
        <div className="flex items-center gap-1.5 px-4 pt-3 border-b border-slate-800 bg-slate-950/60 overflow-x-auto text-xs font-medium">
          <button
            onClick={() => setActiveTab('muller')}
            className={`px-3.5 py-2 rounded-t-lg transition-all flex items-center gap-1.5 whitespace-nowrap ${
              activeTab === 'muller'
                ? 'bg-purple-600 text-white font-semibold'
                : 'text-slate-400 hover:text-slate-200 hover:bg-slate-800/50'
            }`}
          >
            <BookOpen className="w-4 h-4" />
            <span>Müller-Breslau Principle</span>
          </button>

          <button
            onClick={() => setActiveTab('simulator')}
            className={`px-3.5 py-2 rounded-t-lg transition-all flex items-center gap-1.5 whitespace-nowrap ${
              activeTab === 'simulator'
                ? 'bg-purple-600 text-white font-semibold'
                : 'text-slate-400 hover:text-slate-200 hover:bg-slate-800/50'
            }`}
          >
            <Sliders className="w-4 h-4" />
            <span>Interactive ILD Simulator</span>
          </button>

          <button
            onClick={() => setActiveTab('shear_moment')}
            className={`px-3.5 py-2 rounded-t-lg transition-all flex items-center gap-1.5 whitespace-nowrap ${
              activeTab === 'shear_moment'
                ? 'bg-purple-600 text-white font-semibold'
                : 'text-slate-400 hover:text-slate-200 hover:bg-slate-800/50'
            }`}
          >
            <Compass className="w-4 h-4" />
            <span>Step-by-Step Construction</span>
          </button>

          <button
            onClick={() => setActiveTab('moving_loads')}
            className={`px-3.5 py-2 rounded-t-lg transition-all flex items-center gap-1.5 whitespace-nowrap ${
              activeTab === 'moving_loads'
                ? 'bg-purple-600 text-white font-semibold'
                : 'text-slate-400 hover:text-slate-200 hover:bg-slate-800/50'
            }`}
          >
            <Layers className="w-4 h-4" />
            <span>Truck &amp; Live Load Criteria</span>
          </button>

          <button
            onClick={() => setActiveTab('cheatsheet')}
            className={`px-3.5 py-2 rounded-t-lg transition-all flex items-center gap-1.5 whitespace-nowrap ${
              activeTab === 'cheatsheet'
                ? 'bg-purple-600 text-white font-semibold'
                : 'text-slate-400 hover:text-slate-200 hover:bg-slate-800/50'
            }`}
          >
            <CheckCircle2 className="w-4 h-4" />
            <span>Formulas Cheatsheet</span>
          </button>
        </div>

        {/* Modal Body */}
        <div className="p-5 sm:p-6 overflow-y-auto space-y-6">
          {/* TAB 1: Müller-Breslau Principle */}
          {activeTab === 'muller' && (
            <div className="space-y-6 text-sm text-slate-300">
              {/* Highlight Banner */}
              <div className="p-4 rounded-xl bg-gradient-to-r from-purple-950/60 to-indigo-950/40 border border-purple-800/60 space-y-2">
                <h3 className="text-base font-bold text-purple-300 flex items-center gap-2">
                  <Sparkles className="w-4 h-4 text-purple-400" />
                  <span>The Fundamental Law: Müller-Breslau Principle</span>
                </h3>
                <p className="text-xs sm:text-sm text-slate-300 leading-relaxed">
                  The easiest way to construct an Influence Line without tedious equilibrium algebra is Heinrich Müller-Breslau’s kinematic theorem (1886):
                </p>
                <div className="p-3 bg-purple-900/30 rounded-lg border border-purple-700/50 text-purple-200 font-mono text-xs sm:text-sm">
                  <b>Theorem:</b> The influence line for any reaction or internal action (shear, moment) is proportional to the <b>deflected shape of the structure</b> obtained by removing the restraint corresponding to that action and introducing a <b>unit displacement</b> in its positive direction.
                </div>
              </div>

              {/* Contrast: SFD/BMD vs ILD */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="p-4 rounded-xl bg-slate-950/60 border border-slate-800 space-y-2">
                  <h4 className="font-bold text-blue-400 text-sm flex items-center gap-1.5">
                    <span>Shear / Moment Diagram (SFD / BMD)</span>
                  </h4>
                  <ul className="text-xs space-y-1.5 text-slate-400">
                    <li>• Shows internal actions at <b>every section $x$</b> along the beam.</li>
                    <li>• Generated for a <b>fixed, static load configuration</b>.</li>
                    <li>• X-axis: Coordinate of the section of interest.</li>
                  </ul>
                </div>

                <div className="p-4 rounded-xl bg-slate-950/60 border border-slate-800 space-y-2">
                  <h4 className="font-bold text-purple-400 text-sm flex items-center gap-1.5">
                    <span>Influence Line Diagram (ILD)</span>
                  </h4>
                  <ul className="text-xs space-y-1.5 text-slate-400">
                    <li>• Focuses on <b>one specific section or support</b> of interest.</li>
                    <li>• Generated for a <b>unit load ($P = 1$) that moves across</b> the beam.</li>
                    <li>• X-axis: Current location of the moving load.</li>
                  </ul>
                </div>
              </div>

              {/* 3 Step Rule for Determinate Structures */}
              <div className="space-y-3">
                <h4 className="font-bold text-white text-sm">The 3-Step Construction Recipe:</h4>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
                  <div className="p-3.5 rounded-xl bg-slate-950 border border-slate-800 space-y-1.5">
                    <span className="text-xs font-mono font-bold text-purple-400 bg-purple-950 px-2 py-0.5 rounded border border-purple-800">
                      Step 1: Release
                    </span>
                    <h5 className="font-bold text-xs text-white">Remove the Restraint</h5>
                    <p className="text-xs text-slate-400">
                      Remove the capacity of the beam to resist the desired quantity (remove roller/pin, cut beam, or insert hinge).
                    </p>
                  </div>

                  <div className="p-3.5 rounded-xl bg-slate-950 border border-slate-800 space-y-1.5">
                    <span className="text-xs font-mono font-bold text-purple-400 bg-purple-950 px-2 py-0.5 rounded border border-purple-800">
                      Step 2: Displace
                    </span>
                    <h5 className="font-bold text-xs text-white">Apply Unit Movement</h5>
                    <p className="text-xs text-slate-400">
                      Displace the released restraint by <b>1.0 unit</b> (1.0 meter upward for reaction/shear, or 1.0 radian for moment).
                    </p>
                  </div>

                  <div className="p-3.5 rounded-xl bg-slate-950 border border-slate-800 space-y-1.5">
                    <span className="text-xs font-mono font-bold text-purple-400 bg-purple-950 px-2 py-0.5 rounded border border-purple-800">
                      Step 3: Trace
                    </span>
                    <h5 className="font-bold text-xs text-white">Connect the Geometry</h5>
                    <p className="text-xs text-slate-400">
                      For statically determinate beams, the segments remain rigid straight lines. The resulting shape <b>is</b> the exact ILD!
                    </p>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* TAB 2: Interactive Simulator */}
          {activeTab === 'simulator' && (
            <div className="space-y-4">
              {/* Controls Toolbar */}
              <div className="p-4 rounded-xl bg-slate-950 border border-slate-800 grid grid-cols-1 sm:grid-cols-4 gap-4 text-xs">
                <div>
                  <label className="block font-medium text-slate-300 mb-1">Target Action</label>
                  <select
                    value={simQuantity}
                    onChange={(e) => setSimQuantity(e.target.value as any)}
                    className="w-full bg-slate-900 border border-slate-700 rounded-lg px-2.5 py-1.5 text-white font-medium focus:border-purple-500 focus:outline-none"
                  >
                    <option value="RA">Left Support Reaction RA</option>
                    <option value="RB">Right Support Reaction RB</option>
                    <option value="VC">Shear Force VC at Section C</option>
                    <option value="MC">Bending Moment MC at Section C</option>
                  </select>
                </div>

                <div>
                  <label className="block font-medium text-slate-300 mb-1">Beam Span L: {simSpan} m</label>
                  <input
                    type="range"
                    min="4"
                    max="20"
                    step="1"
                    value={simSpan}
                    onChange={(e) => setSimSpan(Number(e.target.value))}
                    className="w-full accent-purple-500"
                  />
                </div>

                <div>
                  <label className="block font-medium text-slate-300 mb-1">Section Cut c: {c.toFixed(1)} m</label>
                  <input
                    type="range"
                    min="1"
                    max={simSpan - 1}
                    step="0.5"
                    value={simSection}
                    onChange={(e) => setSimSection(Number(e.target.value))}
                    className="w-full accent-purple-500"
                  />
                </div>

                <div>
                  <label className="block font-medium text-slate-300 mb-1">Moving Unit Load xP: {xP.toFixed(1)} m</label>
                  <input
                    type="range"
                    min="0"
                    max={simSpan}
                    step="0.2"
                    value={simUnitLoadX}
                    onChange={(e) => setSimUnitLoadX(Number(e.target.value))}
                    className="w-full accent-purple-500"
                  />
                </div>
              </div>

              {/* Kinematic Action Explanation */}
              <div className="p-3 bg-purple-950/40 rounded-xl border border-purple-800/60 text-xs text-purple-200">
                <span className="font-bold text-purple-300">Müller-Breslau Action: </span>
                <span>{mullerAction}</span>
              </div>

              {/* Canvas SVG Display */}
              <div className="relative rounded-2xl border border-slate-800 bg-[#080e1d] p-3 shadow-inner">
                <svg viewBox={`0 0 ${svgW} ${svgH}`} className="w-full h-auto select-none">
                  {/* Zero Datum Line */}
                  <line
                    x1={padX}
                    y1={baseLineY}
                    x2={svgW - padX}
                    y2={baseLineY}
                    stroke="#475569"
                    strokeWidth="2"
                    strokeDasharray="5 3"
                  />

                  {/* Beam Support Indicators */}
                  {/* Pin at A */}
                  <polygon
                    points={`${toX(0)},${baseLineY} ${toX(0) - 10},${baseLineY + 16} ${toX(0) + 10},${baseLineY + 16}`}
                    fill="#3b82f6"
                    opacity={simQuantity === 'RA' ? 0.4 : 1}
                  />
                  {/* Roller at B */}
                  <polygon
                    points={`${toX(L)},${baseLineY} ${toX(L) - 10},${baseLineY + 14} ${toX(L) + 10},${baseLineY + 14}`}
                    fill="#10b981"
                    opacity={simQuantity === 'RB' ? 0.4 : 1}
                  />
                  <circle cx={toX(L) - 5} cy={baseLineY + 18} r="3" fill="#10b981" />
                  <circle cx={toX(L) + 5} cy={baseLineY + 18} r="3" fill="#10b981" />

                  {/* Section Cut Line if VC or MC */}
                  {(simQuantity === 'VC' || simQuantity === 'MC') && (
                    <g>
                      <line
                        x1={toX(c)}
                        y1="25"
                        x2={toX(c)}
                        y2={baseLineY + 30}
                        stroke="#f59e0b"
                        strokeWidth="1.5"
                        strokeDasharray="3 3"
                      />
                      <text
                        x={toX(c)}
                        y="22"
                        fill="#f59e0b"
                        fontSize="11"
                        fontFamily="monospace"
                        fontWeight="bold"
                        textAnchor="middle"
                      >
                        Section C (x = {c.toFixed(1)}m)
                      </text>
                    </g>
                  )}

                  {/* ILD Diagram Shaded Area */}
                  {simQuantity === 'RA' && (
                    <polygon
                      points={`${toX(0)},${baseLineY} ${toX(0)},${baseLineY - 90} ${toX(L)},${baseLineY}`}
                      fill="#8b5cf6"
                      opacity="0.2"
                    />
                  )}
                  {simQuantity === 'RB' && (
                    <polygon
                      points={`${toX(0)},${baseLineY} ${toX(L)},${baseLineY - 90} ${toX(L)},${baseLineY}`}
                      fill="#8b5cf6"
                      opacity="0.2"
                    />
                  )}
                  {simQuantity === 'VC' && (
                    <>
                      <polygon
                        points={`${toX(0)},${baseLineY} ${toX(c)},${baseLineY + (a / L) * 90} ${toX(c)},${baseLineY}`}
                        fill="#ec4899"
                        opacity="0.25"
                      />
                      <polygon
                        points={`${toX(c)},${baseLineY} ${toX(c)},${baseLineY - (b / L) * 90} ${toX(L)},${baseLineY}`}
                        fill="#8b5cf6"
                        opacity="0.25"
                      />
                    </>
                  )}
                  {simQuantity === 'MC' && (
                    <polygon
                      points={`${toX(0)},${baseLineY} ${toX(c)},${baseLineY - Math.min(100, Math.max(30, ((a * b) / L) * 16))} ${toX(L)},${baseLineY}`}
                      fill="#10b981"
                      opacity="0.25"
                    />
                  )}

                  {/* ILD Path Lines */}
                  <path d={ildPath} stroke="#c084fc" strokeWidth="3.5" fill="none" strokeLinecap="round" />

                  {/* Moving Unit Load (P = 1.0) Arrow */}
                  <g>
                    <line
                      x1={toX(xP)}
                      y1="40"
                      x2={toX(xP)}
                      y2={baseLineY - 5}
                      stroke="#ef4444"
                      strokeWidth="2.5"
                    />
                    <polygon
                      points={`${toX(xP)},${baseLineY - 2} ${toX(xP) - 5},${baseLineY - 14} ${toX(xP) + 5},${baseLineY - 14}`}
                      fill="#ef4444"
                    />
                    <rect
                      x={toX(xP) - 24}
                      y="16"
                      width="48"
                      height="20"
                      rx="4"
                      fill="#b91c1c"
                    />
                    <text
                      x={toX(xP)}
                      y="30"
                      fill="#ffffff"
                      fontSize="10"
                      fontFamily="monospace"
                      fontWeight="bold"
                      textAnchor="middle"
                    >
                      P = 1.0
                    </text>
                  </g>

                  {/* Current Ordinate Dot & Value Marker */}
                  <circle
                    cx={toX(xP)}
                    cy={
                      simQuantity === 'RA'
                        ? baseLineY - (1 - xP / L) * 90
                        : simQuantity === 'RB'
                        ? baseLineY - (xP / L) * 90
                        : simQuantity === 'VC'
                        ? xP < c
                          ? baseLineY + (xP / L) * 90
                          : baseLineY - ((L - xP) / L) * 90
                        : baseLineY - (xP <= c ? (b * xP) / L : (a * (L - xP)) / L) * (Math.min(100, Math.max(30, ((a * b) / L) * 16)) / Math.max(0.01, (a * b) / L))
                    }
                    r="5"
                    fill="#fbbf24"
                    stroke="#ffffff"
                    strokeWidth="2"
                  />

                  {/* Ordinates Labels */}
                  <text x={padX - 8} y={baseLineY + 4} fill="#94a3b8" fontSize="11" fontFamily="monospace" textAnchor="end">
                    0.0
                  </text>
                  <text x={svgW - padX + 8} y={baseLineY + 4} fill="#94a3b8" fontSize="11" fontFamily="monospace">
                    x = {L}m
                  </text>

                  {/* Peak Annotations */}
                  {simQuantity === 'RA' && (
                    <text x={padX} y={baseLineY - 98} fill="#c084fc" fontSize="12" fontFamily="monospace" fontWeight="bold">
                      +1.0 (at A)
                    </text>
                  )}
                  {simQuantity === 'RB' && (
                    <text x={toX(L)} y={baseLineY - 98} fill="#c084fc" fontSize="12" fontFamily="monospace" fontWeight="bold" textAnchor="end">
                      +1.0 (at B)
                    </text>
                  )}
                  {simQuantity === 'VC' && (
                    <>
                      <text x={toX(c) - 8} y={baseLineY + (a / L) * 90 + 16} fill="#f43f5e" fontSize="11" fontFamily="monospace" fontWeight="bold" textAnchor="end">
                        −{ (a / L).toFixed(2) }
                      </text>
                      <text x={toX(c) + 8} y={baseLineY - (b / L) * 90 - 8} fill="#a855f7" fontSize="11" fontFamily="monospace" fontWeight="bold">
                        +{ (b / L).toFixed(2) }
                      </text>
                    </>
                  )}
                  {simQuantity === 'MC' && (
                    <text
                      x={toX(c)}
                      y={baseLineY - Math.min(100, Math.max(30, ((a * b) / L) * 16)) - 10}
                      fill="#34d399"
                      fontSize="12"
                      fontFamily="monospace"
                      fontWeight="bold"
                      textAnchor="middle"
                    >
                      Peak = +{( (a * b) / L ).toFixed(2)} m
                    </text>
                  )}
                </svg>

                {/* Real-Time Result Readout Card */}
                <div className="mt-3 p-3 rounded-xl bg-slate-900/90 border border-slate-700/80 flex flex-wrap items-center justify-between gap-3 text-xs font-mono">
                  <div>
                    <span className="text-slate-400">Current Unit Load Position: </span>
                    <span className="text-amber-400 font-bold">x = {xP.toFixed(1)} m</span>
                  </div>

                  <div>
                    <span className="text-slate-400">ILD Ordinate y(x): </span>
                    <span className={`font-bold text-sm ${currentVal >= 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
                      {currentVal >= 0 ? '+' : ''}{currentVal.toFixed(3)} {simQuantity === 'MC' ? 'm' : ''}
                    </span>
                  </div>

                  <div>
                    <span className="text-slate-400">Response for 100 kN Load: </span>
                    <span className="text-purple-300 font-bold">
                      {(currentVal * 100).toFixed(1)} {simQuantity === 'MC' ? 'kN·m' : 'kN'}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* TAB 3: Step-by-Step Construction */}
          {activeTab === 'shear_moment' && (
            <div className="space-y-6 text-sm text-slate-300">
              {/* Reaction ILD Guide */}
              <div className="p-4 rounded-xl bg-slate-950 border border-slate-800 space-y-3">
                <h4 className="font-bold text-white text-base flex items-center gap-2">
                  <span className="w-6 h-6 rounded-full bg-blue-600 text-white flex items-center justify-center text-xs">1</span>
                  <span>How to Draw ILD for Support Reaction (RA or RB)</span>
                </h4>
                <div className="space-y-2 text-xs text-slate-300 pl-8">
                  <p>1. <b>Remove vertical restraint</b> at the support of interest (e.g., support A).</p>
                  <p>2. <b>Displace the node vertically upward</b> by unit displacement ($\Delta = +1.0$).</p>
                  <p>3. <b>Keep all other supports pinned/fixed</b> at zero displacement ($\Delta = 0$ at B).</p>
                  <p>4. Connect the points with a straight line. <b>Result:</b> Linear triangle with peak 1.0 at A and 0.0 at B.</p>
                </div>
              </div>

              {/* Shear Force ILD Guide */}
              <div className="p-4 rounded-xl bg-slate-950 border border-slate-800 space-y-3">
                <h4 className="font-bold text-white text-base flex items-center gap-2">
                  <span className="w-6 h-6 rounded-full bg-purple-600 text-white flex items-center justify-center text-xs">2</span>
                  <span>How to Draw ILD for Shear Force VC at Section C</span>
                </h4>
                <div className="space-y-2 text-xs text-slate-300 pl-8">
                  <p>1. <b>Cut the beam at Section C</b>. Imagine inserting a vertical frictionless slide guide that transmits moment and axial thrust but offers zero resistance to vertical shear.</p>
                  <p>2. <b>Translate the two severed edges</b> relative to each other so the right face goes UP and the left face goes DOWN by a total relative displacement of exactly <b>1.0</b> ($\Delta_R - \Delta_L = 1.0$).</p>
                  <p>3. Because the beam segments are rigid, their slopes must remain equal and parallel.</p>
                  <div className="p-3 rounded-lg bg-slate-900 border border-slate-800 font-mono text-xs text-purple-300 space-y-1">
                    <div>• Ordinate just left of C: y(C−) = −c / L (downward)</div>
                    <div>• Ordinate just right of C: y(C+) = +(L − c) / L (upward)</div>
                    <div>• Total step jump: y(C+) − y(C−) = (L − c)/L − (−c/L) = L/L = +1.0 (always exactly 1.0!)</div>
                  </div>
                </div>
              </div>

              {/* Bending Moment ILD Guide */}
              <div className="p-4 rounded-xl bg-slate-950 border border-slate-800 space-y-3">
                <h4 className="font-bold text-white text-base flex items-center gap-2">
                  <span className="w-6 h-6 rounded-full bg-emerald-600 text-white flex items-center justify-center text-xs">3</span>
                  <span>How to Draw ILD for Bending Moment MC at Section C</span>
                </h4>
                <div className="space-y-2 text-xs text-slate-300 pl-8">
                  <p>1. <b>Insert an internal frictionless hinge</b> at Section C (releases moment resistance M = 0).</p>
                  <p>2. <b>Apply an internal unit relative kink angle</b> (θ = θ1 + θ2 = 1.0 rad) pushing the apex upward.</p>
                  <p>3. The left segment rotates about support A (yA = 0), and the right segment rotates about support B (yB = 0).</p>
                  <div className="p-3 rounded-lg bg-slate-900 border border-slate-800 font-mono text-xs text-emerald-300 space-y-1">
                    <div>• Peak apex ordinate at section C: y_C = (a · b) / L</div>
                    <div>• (where a is distance from A to C, and b is distance from C to B).</div>
                    <div>• Zero ordinates at supports A and B.</div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* TAB 4: Moving Live Load Criteria */}
          {activeTab === 'moving_loads' && (
            <div className="space-y-6 text-sm text-slate-300">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="p-4 rounded-xl bg-slate-950 border border-slate-800 space-y-2">
                  <h4 className="font-bold text-amber-400 text-sm">1. Concentrated Load P</h4>
                  <p className="text-xs text-slate-400">
                    The effect of a single point load is the product of the load magnitude and the ILD ordinate directly under it:
                  </p>
                  <div className="p-2 rounded bg-slate-900 border border-slate-800 font-mono text-xs text-amber-300">
                    Result = P × y(x)
                  </div>
                  <p className="text-xs text-slate-500">
                    Maximum effect occurs when P is placed directly on the peak ordinate y_max.
                  </p>
                </div>

                <div className="p-4 rounded-xl bg-slate-950 border border-slate-800 space-y-2">
                  <h4 className="font-bold text-emerald-400 text-sm">2. Uniform Distributed Load w</h4>
                  <p className="text-xs text-slate-400">
                    The effect of a distributed live load $w$ over length from $x_1$ to $x_2$ equals the load intensity times the <b>area</b> under the ILD:
                  </p>
                  <div className="p-2 rounded bg-slate-900 border border-slate-800 font-mono text-xs text-emerald-300">
                    Result = w × ∫ y(x) dx
                  </div>
                  <p className="text-xs text-slate-500">
                    To maximize positive moment, place live load ONLY on the positive segments of the ILD!
                  </p>
                </div>

                <div className="p-4 rounded-xl bg-slate-950 border border-slate-800 space-y-2">
                  <h4 className="font-bold text-purple-400 text-sm">3. Moving Truck Axle Train</h4>
                  <p className="text-xs text-slate-400">
                    For multiple wheel loads $P_1, P_2, \dots$:
                  </p>
                  <div className="p-2 rounded bg-slate-900 border border-slate-800 font-mono text-xs text-purple-300">
                    Result = Σ (Pᵢ × yᵢ)
                  </div>
                  <p className="text-xs text-slate-500">
                    Criterion: Peak moment occurs when one of the heavy wheel loads is placed directly over the peak apex ordinate.
                  </p>
                </div>
              </div>

              {/* Practical Worked Example */}
              <div className="p-4 rounded-xl bg-slate-950/80 border border-slate-800 space-y-3">
                <h4 className="font-bold text-white text-sm">Practical Exam Example:</h4>
                <p className="text-xs text-slate-300 leading-relaxed">
                  A simply supported bridge girder has a span L = 12 m. We wish to find the maximum bending moment at midspan (c = 6 m) due to a moving highway UDL of w = 20 kN/m.
                </p>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 font-mono text-xs">
                  <div className="p-3 bg-slate-900 rounded-lg border border-slate-800">
                    <span className="text-slate-500 block">Peak Ordinate:</span>
                    <span className="text-emerald-400 font-bold">y_c = a·b/L = 6×6/12 = 3.0 m</span>
                  </div>
                  <div className="p-3 bg-slate-900 rounded-lg border border-slate-800">
                    <span className="text-slate-500 block">Area under Triangle:</span>
                    <span className="text-blue-400 font-bold">Area = 0.5 × 12 × 3.0 = 18.0 m²</span>
                  </div>
                  <div className="p-3 bg-slate-900 rounded-lg border border-slate-800">
                    <span className="text-slate-500 block">Max Bending Moment:</span>
                    <span className="text-purple-300 font-bold">M_max = 20 × 18 = 360 kN·m</span>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* TAB 5: Formulas Cheatsheet */}
          {activeTab === 'cheatsheet' && (
            <div className="space-y-4">
              <div className="overflow-x-auto rounded-xl border border-slate-800">
                <table className="w-full text-left text-xs font-mono">
                  <thead className="bg-slate-950 text-slate-400 border-b border-slate-800">
                    <tr>
                      <th className="p-3">Quantity</th>
                      <th className="p-3">Müller-Breslau Release Mechanism</th>
                      <th className="p-3">Peak Ordinates</th>
                      <th className="p-3">Shape</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/80 bg-slate-900/60">
                    <tr>
                      <td className="p-3 font-bold text-white">Reaction RA</td>
                      <td className="p-3 text-slate-300">Remove vertical support at A, displace +1.0 up</td>
                      <td className="p-3 text-purple-400">+1.0 at A, 0.0 at B</td>
                      <td className="p-3 text-slate-400">Single straight line</td>
                    </tr>
                    <tr>
                      <td className="p-3 font-bold text-white">Reaction RB</td>
                      <td className="p-3 text-slate-300">Remove vertical support at B, displace +1.0 up</td>
                      <td className="p-3 text-purple-400">0.0 at A, +1.0 at B</td>
                      <td className="p-3 text-slate-400">Single straight line</td>
                    </tr>
                    <tr>
                      <td className="p-3 font-bold text-white">Shear Force VC</td>
                      <td className="p-3 text-slate-300">Cut section, vertical slide guide with Δ = 1.0</td>
                      <td className="p-3 text-rose-400">Left: −a/L  |  Right: +b/L</td>
                      <td className="p-3 text-slate-400">Two parallel lines with unit step jump</td>
                    </tr>
                    <tr>
                      <td className="p-3 font-bold text-white">Bending Moment MC</td>
                      <td className="p-3 text-slate-300">Insert internal hinge at C, unit rotation θ = 1.0</td>
                      <td className="p-3 text-emerald-400">Apex = +(a · b) / L</td>
                      <td className="p-3 text-slate-400">Triangle with apex at section cut</td>
                    </tr>
                    <tr>
                      <td className="p-3 font-bold text-white">Overhanging Cantilever</td>
                      <td className="p-3 text-slate-300">Rigid segments rotate past exterior supports</td>
                      <td className="p-3 text-amber-400">Linearly extrapolated past support</td>
                      <td className="p-3 text-slate-400">Continuous straight line extending to tip</td>
                    </tr>
                  </tbody>
                </table>
              </div>

              <div className="p-4 rounded-xl bg-purple-950/30 border border-purple-800/50 flex items-start gap-3 text-xs text-purple-200">
                <CheckCircle2 className="w-4 h-4 text-purple-400 mt-0.5 flex-shrink-0" />
                <div>
                  <strong className="text-white block mb-0.5">Statically Indeterminate Beams (Continuous Beams):</strong>
                  For continuous multi-span beams, Müller-Breslau principle still holds exactly! But instead of rigid straight lines, the beam bends elastically, creating smooth cubic/quartic spline curves between supports.
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-800 bg-slate-950 flex items-center justify-between">
          <div className="text-xs text-slate-500">
            Interactive structural mechanics tutorial · BeamLab Pro
          </div>
          <button
            onClick={onClose}
            className="px-4 py-2 rounded-xl bg-purple-600 hover:bg-purple-500 text-white font-semibold text-xs transition-colors"
          >
            Close Tutorial
          </button>
        </div>
      </div>
    </div>
  );
};
